window.HB_TR["deuteronomy"]["ks"]=["1.\\tیم لفظ یم موسىٰ ین سارنٕے اسرائیلس سٍتـ̡ کٔرۍمٕتۍ، بیابانس منز، سمندرس سٍتـ̡ میدانس منز، پران تہٕ ٹوفیلس درمِیان تہٕ لبان تہٕ ہزروت تہٕ دزاہابس منز۔ {دی ریڈ...: یا، زُف}\n2. ({اتہِ} چُھہ کاہ دۅہن ہُند {سفر} کوہ سیر پہاڑ کِس وتہِ کٔرِتھ کادیشبرنیاہس تام۔)\n3.\\tتہٕ سپُد ژتٲہمہِ ؤریس مَنٛز، کاہمہِ ریتس مَنٛز، ریتہٕ کِس گۄڈنِکِس دۅہہٕ {یُس} موسىٰ ین بنی اسرٲیلس سٍتـ̡ کتھ کٔر، یُس خداوند تِمن ہُند حُکُم دِژمُت اوس۔\n4.\\tییلہ تمٔۍ امورین ہُند بادشاہ سِحون یُس ہیشبونس منز روزان اوس، تہٕ اوگ بشانُک بادشاہ، یُس ادری کِس استاروتس مَنٛز روزان اوس۔\n5.\\tاَمہِ طرفہٕ اردن موآب کِس سرزمینس مَنٛز، موسیٰ سٕندِ شریعت ہُند اعلان کرُن شروع کٔرِتھ وونُن،\n6.\\tسٲنـ̡ خدایہِ چُھہ حوربس مَنٛز اسہِ سٍتـ̡ کتھ کٔرِتھ وَنُن زِ تُہۍ چُھہ اتھ پہاڑس مَنٛز واریاہس کالس روزمُت:\n7. پھیرِو تہٕ پَنُن سفر کرُن، تہٕ امورین ہٕندِس پہاڑس کُن گژھِو، تہٕ اَتھ نکھٕ سارِنٕے مقامن کُن، میدانس منز، بالن منز، وادی منز، تہٕ جنوبس منز، تہٕ سمندرٕ کِس بٹھس پیٹھ، کنعانین ہٕندِس سرزمینس تام، تہٕ لبنان کُن، عظیم دریائے فرات کُن۔ {سٲری ...: ہیب۔ تٔمۍ سٕندۍ سٲری ہمسایہ}\n8. وچھ میہ چُھہ ژے برونہہ کُن زمینہٕ مقرر کٔرمٕژ: اژِتھ گژھ تہٕ سُہ زمینہٕ حٲصل کرُن یُس خداوند پننین باپ ابراہیم، اسحاق تہٕ یعقوبس نِش حلف کورمُت چُھ، یُس تِمن تہٕ تِہندِ پتہٕ تہندِس اولادس دِنہٕ خٲطرٕ حلف کورمُت چُھ۔ {سیٹ: ہیب۔ دِنہٕ آمُت}\n9.\\tتہٕ میہ ووت تمہِ وِزِ ژے سٍتـ̡ وونُن، بہٕ چُھس نہٕ ژے پانہٕ تنہا برداشت کٔرِتھ:\n10. خداوند تُہٕندِس خداہَن چُھہ تُہٕندِس خداہِ سٍتـ̡ بٔڑِتھ تہٕ وُچھِو تُہۍ از تہِ آسمانٕکۍ ستارٕ ہٕندِس پٲٹھۍ۔\n11. (تہندٮ۪ن مٲلن ہُند خداوند چُھہ تۅہہِ ساس لٹہِ تہِ بنوومُت، تہٕ تُہٕندِس وعدس سٍتـ̡ دِیُت تۅہہِ سٍتـ̡ برکت دِنہٕ!)\n12. بہٕ کِتھ کٔنۍ ہیکہٕ پانہٕ تُہند بوجھ، تہٕ تُہند بوجھ، تہٕ تُہند کشمکش تُلِتھ؟\n13.\\tژے عقلمند تہٕ سمجھدار تہٕ پننین قبیلن مَنٛز زاننہٕ یِن، تہٕ بہٕ بناوٕ تِم پانس پیٹھ حُکُران۔ {رٔٹِو: ہیب۔ دِیُو}\n14.\\tتہٕ ژے دیُت میہ جواب تہٕ وونُن، یُس کتھ ژے کتھ کٔرمٕژ چُھ، سُہ چُھ سانہِ خٲطرٕ اصل۔\n15.\\tتێلہِ بنیوو میہ تہندٮ۪ن قبیلن ہُند سردار، دانشمند تہٕ زاننہٕ آمُت، تہٕ بنووُن تِم توے پیٹھ، ساسہٕ بٔدۍ کپتان، ہتہٕ ہتہٕ کپتان، تہٕ پنژاہ پیٹھٕ کپتان، تہٕ دہن پیٹھٕ کپتان، تہٕ تہندٮ۪ن قبیلن مَنٛز افسر۔ {بنیومُت: ہیب۔ دِنہٕ آمُت}\n16.\\tتہٕ میہ دِژ تَمہِ وِزِ چُھس پننین باین درمِیان وجوہات بوزِو، تہٕ پرٮ۪تھ أکِس انسانس تہٕ تٔمۍ سٕندِس بٲیِس تہٕ أمِس سٍتـ̡ اجنبی سٍتـ̡ یُس أمِس سٍتـ̡ سٍتـ�\n17.\\tفیصلس منز گژھِ نہٕ نفرن ہُند احترام کرُن۔ {مگر} تۅہہ بوزِو لۄکٹۍ تہٕ بٔڈۍ۔ ژیہ گژھِ نہ انسان سٕندِس بُتھِس سٍتۍ خوف۔ یُس فیصلہٕ چُھہ خدایہ سُند: تہٕ یُس وجہ چُھہ تۅہہِ خٲطرٕ واریاہ مشکل چُھ، اَن میہ نِش تہٕ بہٕ بوزٕ یہِ۔ {احترام...: ہیب۔ بُتھِس تسلیم کٔرِو}\n18. تہٕ مے دِیُت تَمہِ وِزِ تِمن سارِنٕے چیزن ہُند حُکُم یِم ژے کرٕنۍ۔\n19. تہٕ ییلہ أسۍ حوریب پیٹھٕ نیرِو، أسۍ گٔیہِ تتھ سارِنٕے بٔڈ تہٕ خوفناک بیابانن منز، یُس تۅہہ امورین ہٕندِس پہاڑ کِس وتہِ کِنۍ وُچھمُت، یُس خداوند سانہِ خداین اسہِ حکم دِژمُت اوس۔ تہٕ أسۍ آیہِ کادیشبرنیاہس منٛز۔\n20. تہٕ مےٚ ووٚن ژےٚ، تہٕ تُہۍ چھِو امورین ہٕندِس پہاڑس پیٹھ آمٕتۍ، یُس سٲنـ̡ خداوند اسہِ دِوان چُھ۔\n21. وُچھِو، خداوند تُہٕندِس خداہَن چُھ تۅہہِ برونہہ کُن زمین بَنٲومٕژ: ہیوٚر ہیوٚر {تہٕ} یِتھ کٔنۍ چُھہ تُہٕندِس مٲلِس خداہِ سٕندِس خداہِ سٍتـ̡ ووٚنمُت۔ خوفہٕ نہٕ گژھِ، نہ گژھِ حوصلہ شکنی کٔرِتھ۔\n22. تہٕ تُہۍ وٲتِو میہ نِش سارِوٕے أکِس نِش، تہٕ وونُن، أسۍ سوزو پانس برونہہ کُن نفر، تہٕ تِم گژھن اسہِ زمینہٕ ژھانڈنہٕ، تہٕ اسہِ دُبارٕ خبر دِنہٕ زِ أسۍ کمہِ وتہِ گژھِ، تہٕ کَمن شہرن مَنٛز گژھِو۔\n23.\\tتہٕ یہ قول آو میہ خۅش کرنہٕ: تہٕ مے رٔٹۍ ژےٚ منزٕ باہ نفر، یُس أکِس قبیلس منز اکھ اوس۔\n24.\\tتہٕ تِم گٔیہِ پھیُر تہٕ پہاڑس کُن کھٔسِتھ وٲتِتھ وادی ایشکول کِس وادی کُن تہٕ ژھٲنڈِتھ ژھٲنڈِ۔\n25.\\tتہٕ تِمو نِش زمینہٕ ہُند پھل پننین اتھن منز، تہٕ أنِتھ اسہِ نِش دُبارٕ کتھ تہٕ وونُن، {یہِ} چُھ اکھ اصل زمین یُس خداوند سانہِ خدایہ اسہِ دِوان چُھ۔\n26.\\tبہر تہِ کٔرِو نہٕ ہیوٚر کھسُن، مگر کٔرٕکھ خداوند پنُن خدایہ سٕندِس حُکمس خلاف بغاوت:\n27.\\tتہٕ تۅہہ کٔر پننین خیمن منز بڑبڑاوان تہٕ وونُن، کیازِ خداوند چُھ اسہِ سٍتـ̡ نفرت کران، تٔمۍ کٔر اسہِ مصرٕچ سرزمینہٕ منزٕ نیبر، تاکہ اسہِ امورین ہٕندِس اتھس مَنٛز واتناوُن، تہٕ اسہِ تباہ کرنہٕ مۅکھہٕ۔\n28. اسہِ کوٚت کوٚت گژھو؟ سانٮ۪و بٲے چھُ سانہِ دِل حوصلہ شکنی کٔرمٕژ، یہ ؤنِتھ زِ لوٗکھ چھِ اسہِ کھۅتہٕ بوڈ تہٕ تھد۔ شہر چھہِ عظیم تہ آسمانس تام دیوار لگٲوتھ۔ تہٕ امہ علاوٕ چھِ اسہِ اَتہِ اناکیمن ہٕندۍ نیچوۍ وُچھمٕتۍ۔ {حوصلہ شکنی کٔرِتھ: ہیب۔ پگھلُن}\n29. اَمہِ پتہٕ ووٚن مے ژےٚ، خوفزدہ گژھ نہٕ تہٕ تِمن نِش گژھ نہٕ کھوژُن۔\n30. خداوند تُہند خدا یُس تۅہہِ برونہہ کُن چُھ، سُہ کرِ تۅہہِ خٲطرٕ لڑان، یُس تۅہہِ خٲطرٕ مصرس مَنٛز تۅہہِ ہٕندِ خٲطرٕ کورمُت چُھ۔\n31. تہٕ بیابانس مَنٛز، یێتہِ ژے وُچھمُت زِ خداوند تُہُند خدا کِتھہ پٲٹھـ̡ چُھہ تُہُند نیچو زٲنِتھ، یێلہِ وتہِ تہٕ یێلہِ تہٕ تُہۍ یێتھ جایہِ وٲتِو۔\n32. توتہِ کٔر نہٕ اتھ چیزس مَنٛز یُس خداوند پنُن خدایہ سُند ایمان اوس،\n33.\\tیُس ژے برونہہ کُن وتہِ وُچھِتھ ژیہ کُنہِ جایہ ژھانڈنہٕ خٲطرٕ، رٲژ نارس منز، تہٕ دۅہہٕ کُنہِ وتہِ گژھُن۔\n34.\\tتہٕ خداوند بوٗز تُہٕندِ کلامٕچ آواز، تہٕ ہیوٚتُن شرارت تہٕ وونُن قسم،\n35. یێمہِ بد سٍتـ̡ یِمو منزٕ کانہہ تہِ وُچھِ نہٕ سُہ اصل زمین، یُس بہٕ چُھس پننین مٲلن دِنُک قسم کھیوان۔\n36.\\tیپھنہ سُند نیچو بچاوُن کالب۔ سُہ وُچھِتھ تہٕ بہٕ دِیہٕ أمِس سُہ زمین یتھ پیٹھ تٔمۍ پٔکِتھ چُھ، تہٕ تٔمۍ سٕندِس شُرِس دِنہٕ، کیازِ سُہ چُھ پوٗرٕ پٲٹھـ̡ خداوند سٕنز پیروی کٔرمٕژ۔ {پورٕ...: ہیب۔ پورٕ گژھُن پتہٕ}\n37.\\tتہِ اوس خداوند تہِ چانہِ خٲطرٕ میانہِ سٍتۍ ناراض تہٕ وونُن زِ ژے تہِ گژھ نہٕ تتہِ اژُن۔\n38.\\t{مگر} یشوع سُند نیچو، یُس تۅہہِ برونہہ کنہِ کھڑا چُھ، سُہ گژھہِ تتہِ اژُن، تٔمِس حوصلہٕ افزٲیی۔\n39.\\tامہِ علاوٕ چُھہ تُہٕندِس لۄکٹِس شُرۍ، یِمن نہٕ اَمہ دۅہہٕ نیکی تہٕ بدس درمِیان کانہہ علم اوس، تِم گژھن تتہِ اژُن، تہٕ بہٕ دِیہٕ تِمن تہٕ تِمن دِنہٕ تہٕ تِمن ہُند قبضہٕ۔\n40.\\tمگر {یێلہِ} ژے پھیرِو تہٕ بحرِ احمر کِس وتہِ کِنۍ کٔرِو بیابانن مَنٛز سفر۔\n41.\\tتێلہِ دِژ ژے جواب تہٕ وونُن میہ زِ أسـ̡ چُھ خداوند سٕندِس خلاف گۅناہ کورمُت، أسـ̡ ہیوٚر تہٕ لڑٲے یُس خداوند سٲنـ̡ خدایہ سُند حکم دِتمُت چُھ۔ تہٕ ییلہ ژیہ پریتھ نفرس جنگک ہتھیار لٲگتھ ٲسو، تم ٲسکھ بالس پیٹھ کھسنہٕ خٲطرٕ تیار۔\n42. تہٕ خداوند ووٚن میہ زِ تِمن وَنُن زِ ہیوٚر نہٕ ہیوٚر تہٕ لڑٲے تہٕ تکیازِ بہٕ چُھس نہٕ ژےٚ منز؛ یِم نہٕ تُہۍ پننٮ۪ن دُشمنن برٛونٛہہ کنہِ مارنہٕ یِو۔\n43. یێلہِ کٔر میہ ژے سٍتـ̡ کتھ کرنہٕ۔ تہٕ تۅہہ کٔر نہٕ بوزُن، مگر خداوند سٕندِس حکمس خلاف کٔرٕکھ بغاوت، تہٕ گٔیہٕ بے تکلف سٍتـ̡ بالس کُن۔ {گٔیہ...: ہیب۔ تۅہہ گٔے گٔژھتھ تھوٚد کٔرِتھ\n44.\\tتہٕ اموریو یُس اتھ پہاڑس منز روزان اوس، دراو تۅہہِ خٕلاف تہٕ ژٔلِکھ تۅہہِ ہٕندِس پٲٹھۍ، تہٕ کورُکھ سیرس مَنٛز تہٕ ہورمہ تام تہِ تباہ کٔرِتھ۔\n45. تہٕ تم آو واپس تہٕ روو خداوند سٕندِ برونہہ کُن۔ مگر خداوند کرِ نہٕ تہنز آواز بوزناوٕن، تہٕ نہ دِژ تۅہہِ کُن۔\n46.\\tتَوَے روزِو کادیشس مَنٛز واریاہن دۅہن روزان، تِمن دۅہن مُطٲبِق یِمن دۅہن تُہۍ روزان چھِو۔","1.\\tپَتہٕ گٔیہِ أسۍ پھیُر، تہٕ بحیرہ احمر کِس وتہِ کِنۍ پَنُن سفر کٔرِتھ، یِتھ کٔنۍ خداوند میہ کٔرِتھ ووٚنمُت: تہٕ أسۍ گٔیہِ واریاہن دۅہن سییر پہاڑس مَنٛز۔\n2. تہٕ خداوند ووٚن میہ سٍتـ̡ وونُن،\n3.\\tژیہ چھہ اتھ بالس واریاہس کالس گھیرمت: شمالس کُن پھیرُن۔\n4.\\tتہٕ دِیُن لُکن ہُند حُکُم زِ یِم عیسو سٕندِس بٔنِس سٍتـ̡ پَنٕنـ̡ پى۪ٹھہٕ پى۪ٹھـ̡ تہٕ تِم گژھن تۅہہِ سٍتـ̡ کھوژان: لہذا کرو پانس سٍتـ̡ خبردار۔\n5. تِمن سٍتۍ گژھِ نہٕ مداخلت کرنہٕ۔ تکیازِ بہٕ دِیہ نہٕ ژے تِہٕنزِ زمینہٕ منز، نہٕ تہٕ اکھ فٹ کھجر۔ تکیازِ میہ چھہ کوہ سیر عیسوس اکھ قبضہ دِژمُت۔ {نہ...: ہیب۔ کھورِ ہندس تلاوس تام تہِ}\n6.\\tتِمن ہُند ماز ہییُن پونسہٕ خٲطرٕ، یُتھ کھٮ۪نہٕ ییہِ۔ تہٕ تُہۍ ہییِو تِمن ہُند آب تہِ پٲنسہٕ خٲطرٕ، یُتھ تُہۍ چیٚنہٕ یِو۔\n7. خداوند سٕندِ خٲطرٕ چُھہ تُہٕندِس خدایہِ سٍتـ̡ تُہٕندِس سارِنٕے کامہِ مَنٛز برکت دِژمٕژ: سُہ چُھہ تێہُند یَتھ بٔڈِس بیابانس مَنٛز پَکُن پَکُن زانان: یِمن ژتٲجی ؤرین چُھہ خداوند تُہند خدا چُھہ توے سٍتـ̡ روزمُت۔ ژیہ چھیہ نہ کانہہ کمی۔\n8. تہٕ ییلہ أسۍ پننین باین نِش یِم عیسو سٕندِ شُرۍ یِم سیرس مَنٛز روزان ٲسۍ، ایلاتھ پیٹھٕ میدانی وتہٕ کِنۍ تہٕ ایزیونگابر پیٹھٕ گٔیہِ، أسۍ پھیرۍ تہٕ موآب کِس بیابان کِس وتہِ کِنۍ پٔکۍ۔\n9. تہٕ خداوند ووٚن مے زِ موآبین گژھ نہٕ تکلیف دِنہٕ، تہٕ نہ کرٕ تِمن سٍتـ̡ جنگس مَنٛز مقابلہٕ، کیازِ بہٕ دِیہ نہٕ ژے تِہٕنزِ زمینہٕ سٍتـ̡ دِنہٕ۔ تکیازِ میہ چھہ لوط کین بچن اکھ قبضہ دِژمُت۔ {پریشانی...: یا، موآبس خلاف کرو نہ کانہہ دشمنی استعمال}\n10.\\tایمس اوس پتھ کالس منز اَتھ منز روزان، یُس عظیم تہٕ واریاہ تہٕ تھوٚد قوم اوس، یُس اناکیمس ہٕندۍ پٲٹھۍ۔\n11.\\tیِم تہِ ٲسۍ دیو شمار کرنہٕ آمٕتۍ، یِمن ہٕندِس پٲٹھۍ، اناکیم۔ مگر موابی چھہِ یمن ایمس ونان۔\n12.\\tحوریم تہِ ٲسۍ برونہہ کنہِ سیرس منز روزان۔ مگر عیسو سٕندِ اولادٕ گٔیہِ تِمن پتہٕ، ییلہ تِمو تِم پانس برونہہ کُن تباہ کٔرۍ، تہٕ تِمن ہٕنزِ جایہ روزُن۔ یِتھ کٔنۍ زن اسرٲیلَن پننِس ملکیتس سٍتـ̡ کٔر، یُس خداوند تِمن دِژمُت چھُ۔ {کامیاب: ہیب۔ وراثت} {سٹیڈ: یا، روم}\n13.\\tوۅنۍ تھوٚد تھوٚد، {میہ ووٚن}، تہٕ ژے نِش نِش نیرُن۔ تہٕ أسۍ گٔیہِ نالہٕ زیرید۔ {بروک: یا، وادی}\n14.\\tتہٕ یتھ جایہِ أسۍ کادیشبرنیاہس پیٹھ وٲتۍ، یوٚتام أسۍ نالہٕ زیریدس اپارِ وٲتِتھ، {اوس} ترہ ٲٹھ ؤری۔ یوتام زِ جنگی نفرن ہٕنز تمام نسلہٕ لشکرس منزٕ ضایع گٔیہ، یِتھ کٔنۍ خداوند تمن پیٹھ قسم دِژمُت۔ {بروک: یا، وادی}\n15. یێلہِ پٔزۍ پٲٹھـ̡ خداوند سُند اَتھٕ اوس تِمن خلاف، یێلہِ تِم لشکرس منزٕ تباہ کٔرِتھ، یوتام تِم ختم گٔیہِ۔\n16.\\tیێلہِ سپُد یێلہِ سارِنٕے جنگٕکۍ مرد لُکن مَنٛز کھٮ۪نہٕ تہٕ مارٕ گٔیہِ،\n17.\\tیُس خداوند چُھہ میہ سٍتـ̡ وَنُن،\n18.\\tتوے گژھہِ از دۅہہ موآب کِس بٹھہِ آرس کِنۍ نیرُن:\n19.\\tتہٕ ییلہ تہٕ ژے عمون کین بچن نِش نزدیک وٲتِو، تِمن کٔرِو نہٕ تِمن مُشکِل تہٕ تِمن سٍتـ̡ کٔرِو نہٕ تِمن سٍتـ̡ دِنہٕ، تکیازِ بہٕ دِیہ نہٕ ژے عمون سٕندِس بچن ہٕنزِ زمینہٕ ہُند قبضہٕ۔ تکیازِ میہ چھہ یہ لوط کین بچن دِژمُت۔\n20. (یہ تہِ اوس دیوَن ہٕنز سرزمین ماننہٕ یوان: پرانہِ زمانس منز ٲسۍ دیو اتھ منز روزان۔ تہٕ امونی چھِ تمن زمزومیم ونان۔ {Zamzummims: یتھ تہِ ونان چھِ، Zuzims}\n21. اکھ عظیم تہٕ واریاہ تہٕ تھود لوک، یُس اناکیمن ہٕندۍ پٲٹھۍ۔ مگر خداوند کٔر تِم تِمن برونہہ کُن تباہ۔ تہٕ تِمو گٔیہِ تِمن پتہٕ، تہٕ تِمن ہٕنزِ جایہ روزُن:\n22. یِتھ کٔنۍ تٔمۍ عیسو سٕندِس شُرین سٍتۍ، یُس سیرس منز روزان اوس، ییلہ تٔمۍ تِمن برونہہ کُن حورِم تباہ کٔرۍ۔ تہٕ تِمو پتہٕ بٔنِتھ تہٕ روٗدۍ از تام تہندِس جایہ روزان:\n23.\\tتہٕ یُس عزریمس منز روزان اوس، عزاہَس تام یُس کافر نیبر نیرِ، تِم تباہ کٔرِتھ تہٕ تِمن ہٕندِس بدلہٕ بٔسِتھ بٔسِتھ۔)\n24.\\tوۅتھٕ ووٚتھ، پنُن سفر کرُن، تہٕ دریائے ارنون اپارِ نیرُن: وچھ مے چُھس ہیشبونُک بادشاہ سِحون تہٕ تٔمۍ سٕنزِ زمینہٕ تہٕ تٔمۍ سٕندِس اتھس منز دِژمُت: قبضہ کرُن شروع کرُن، تہٕ جنگس مَنٛز کرُن أمِس سٍتـ̡ مقابلہٕ۔ {شروع...: ہیب۔ شروع کرو، قبضہ کرُن}\n25. اَمہ دۅہہ کرٕ بہٕ تۅہہِ ہُند خوف تہٕ تۅہہِ ہُند خوف تِمن قومن پیٹھ تراوُن، یِم تۅہہِ ہٕنز خبر بوزن، تہٕ ژے سٍتـ̡ ژے سٍتـ̡ ژٔلِتھ تہٕ ژے سٍتـ̡ غمگسار گژھن۔\n26. تہٕ مے سوٗزۍ کیڈیموتھ کِس بیابان منزٕ ہیشبون کِس بادشاہ سِہون نِش امن ہٕندِس کلامس سٍتـ̡ وونُن،\n27.\\tبہٕ گٔژھ پننہِ زمینہِ کِنۍ نیرُن: بہٕ گژھہٕ نہٕ دٔچھنِس کُن تہٕ نہ کھوورِ کُن۔\n28.\\tژے کٕنُن ماز پٲنسہٕ خٲطرٕ، یُتھ بہٕ کھٮ۪تھ تہٕ دِیُن میہ پونسہٕ خٲطرٕ آب، یُتھ بہٕ چیٚنہٕ یِوان: صرف بہٕ پَنٕنٮ۪ن قدمن پیٹھ نیرُن۔\n29. (یِتھ کٔنۍ عیسو سٕندِ اولاد، یُس سیرس مَنٛز روزان چُھ، تہٕ موابی یُس عرس مَنٛز روزان چُھ، تہٕ یُس میہ سٍتـ̡ کٔرِتھ چُھہ؛) یوتام بہٕ اردن پیٹھٕ تتھ زمینس مَنٛز نیرِتھ یُس خداوند سٲنـ̡ خدا اسہِ دِوان چُھ۔\n30. مگر ہیشبونُک بادشاہ سِہون دِژ نہٕ اسہِ أمِس نِش نیرُن، تکیازِ خداوند چُھہ تٔمۍ سُند روح سختی کٔرِتھ، تہٕ بنووُن تٔمۍ سُند دِل ضد، یُتھ زن سُہ از دۅہہ ظٲہر سپدان چُھ۔\n31. تہٕ خداوند ووٚن میہ زِ وُچھمُت چُھس سِحون تہٕ تٔمۍ سٕنز زمین ژے برونہہ کُن دِنہٕ شروع کٔرِتھ، یُتھ تہٕ تٔمۍ سٕنزِ زمینہِ ہٕندِس وٲرث سٍتـ̡ حٲصل کرُن۔\n32.\\tتمہ پتہ آو سیہون اسہِ خلاف، سُہ تہٕ تٔمۍ سٕندِس سارِنٕے لُکہٕ سٍتـ̡ جہازس مَنٛز لڑنہٕ خٲطرٕ۔\n33. تہٕ خداوند سُہ دِژ سُہ اسہِ برونہہ کُن دِنہٕ۔ تہٕ أسۍ مارۍ أمِس تہٕ تٔمۍ سٕنٛدٮ۪ن نیٚچوٮ۪ن تہٕ تٔمۍ سٕنٛدٮ۪ن سارِنٕے لوٗکَن مار۔\n34.\\tتہٕ أسۍ تٔمۍ سٕندِس سارِنٕے شہرس پیٹھ قبضہ کٔرِتھ تہٕ پرٮ۪تھ شہرٕکۍ مرد، زنانہٕ تہٕ لۄکٕٹۍ کٔرِکھ پوٗرٕ پٲٹھۍ تباہ کٔرِتھ، اسہِ تروو نہٕ کانہہ تہِ باقی: {مرد...: حب۔ مرد، زنانہٕ تہٕ لۄکٹٮ۪ن ہُنٛد پرٮ۪تھ شہر}\n35.\\tصرف سُہ چاروٲے یُس أسۍ پانس شکارٕ کٔرِتھ تہٕ شہرن ہُند لوُٹ یُس أسۍ نِیومُت۔\n36.\\tاَرَوَر پؠٹھٕ یُس دٔریاوٕ کِس بٔٹھِس پیٹھ {چُھ} تہٕ {چُھ} یُس دٔریاو کِس بٔٹھِس نِش چُھ، تہٕ گِلاد تام تہِ اوس نہٕ اکھ تہِ شہر یُس اسہِ خٲطرٕ زیادٕ مضبوط: خداوند سانہِ خداہن دِژ سارِنٕے اسہِ خٲطرٕ:\n37.\\tصرف آمون کین اولادن ہٕندِس سرزمینس مَنٛز ووت نہٕ تہٕ نہ دریائے جابوک کِس کُنہِ جایہ تہٕ نہ پہاڑن ہٕندِس شہرس مَنٛز، تہٕ یُس تہِ خداوند سانہِ خدایہ اسہِ منع کورمُت اوس۔","1.\\tپَتہٕ گٔیہِ أسۍ پھیُر تہٕ بشان کُن وتہِ وتہِ: تہٕ اوگ بشانُک بادشاہ آو اسہِ خٕلاف، سُہ تہٕ تٔمۍ سٕندِس سارِنٕے لُکہٕ سٍتـ̡ ادری کِس جنگس مَنٛز۔\n2. تہٕ خداوند ووٚن میہ زِ تس گژھ نہٕ خوف، کیازِ بہٕ کرٕ سُہ تہٕ تٔمۍ سٕندِس سارِنٕے لوک، تہٕ تٔمۍ سٕنزِ زمینہٕ تہٕ تٔمۍ سٕنزِ زمینہٕ تہٕ تٔمۍ سٕندِس اتھس مَنٛز۔ تہٕ تُہۍ کٔرِو أمِس سٍتـ̡ یِتھٕ پٲٹھۍ یُس امورین ہٕندِس بادشاہ سِحون سٍتـ̡ اوس یُس ہیشبونس منز روزان اوس۔\n3. یێمہِ پٲٹھـ̡ دِژ سٲنـ̡ خدایہِ سٍتـ̡ اوگ، باشانُک بادشاہ تہٕ تٔمۍ سٕندِس سارِنٕے لُکہٕ سٍتـ̡ تہٕ أسـ̡ دِژ أمِس سٍتـ̡ یێلہِ سٍتـ̡ کانہہ تہِ باقٕے نہٕ۔\n4.\\tتہٕ أسۍ تٔمہِ وِزِ تٔمۍ سٕندِس سارِنٕے شہرس پیٹھ قبضہ کٔرِتھ، تتہِ اوس نہٕ کانہہ شہر یُس اسہِ تِمن نِش نِش نِیومُت اوس، تریہ شہر، ارگوبُک سٲری علاقہٕ، باشانَس مَنٛز اوگ سٕنز بادشٲہی ۔\n5.\\tیِم سارِنٕے شہرَن ٲس تھدِ دیوار، دروازٕ تہٕ سلاخہٕ سٍتۍ تار لٔگِتھ۔ بے دیوار شہرن علاوٕ واریاہ زیادٕ۔\n6.\\tتہٕ أسۍ کٔر تِم پوٗرٕ پٲٹھۍتباہ یِتھ کٔنۍ أسۍ ہیشبون کِس بادشاہس سِہون سٍتـ̡ تباہ کٔرِتھ پرٮ۪تھ شہرٕکۍ مرد، زنانہٕ تہٕ شُرۍ پوٗرٕ پٲٹھۍ تباہ کٔرِتھ۔\n7. مگر سارِنٕے چاروٲے تہٕ شہرن ہٕندِ لوُٹ، أسۍ پانس شکار۔\n8. تہٕ اسہِ نِش اَمہِ وِزِ امورین ہٕندِس دۄن بادشاہن ہٕندِ اتھہٕ نِش سُہ زمین یُس اردن کِس اَتھ طرفہٕ اوس ، دریائے ارنون پیٹھٕ ہرمون کِس پہاڑس تام۔\n9. ({یُس} ہرمون چھہ سیرین ونان تہ اموری چھہِ اتھ شینیر ونان ۔)\n10.\\tمیدانٕکۍ سارِنٕے شہر، تہٕ سارِنٕے جلعاد تہٕ سارِنٕے باشانَس تام، بشانَس مَنٛز اوگ کِس بادشٲہی ہٕندِس شہرس تام۔\n11.\\tتکیازِ بشانُک بادشاہ اوس صرف اوگ بادشاہ دیوتن ہٕندِس باقیاتس منز روٗدمُت۔ وچھ تٔمۍ سُند بسترٕ اوس ششتٕرُک بستر۔ {کیا یہ} چُھ نہٕ عمون کین بچن ہٕندِس ربتھس منز؟ انسان سٕندِ کُنہِ ہُند زیچھر اوس نو کیوبِٹ، تہٕ ژور کیوبِٹ اَمہ کِس زیچھرس منز۔\n12.\\tتہٕ یہِ زمین، یُس اسہِ تمہِ وِزِ اسہِ نِش اوس، یُس دریائے ارنون نِش {چُھ}، تہٕ نصف پہاڑ گلعاد تہٕ اَمہ کین شہرن دِژ میہ روبینن تہٕ گادیتن دِنہٕ۔\n13.\\tتہٕ باقی جلعاد تہٕ سارِنٕے باشان، اوگ سٕنز بادشٲہی آسنہٕ کِنۍ، دِژ میہ مناشہ کِس نصف قبیلس دِنہٕ۔ ارگوبُک سورُے علاقہٕ، سارِنٕے باشانَس سٍتۍ، یَتھ دیوَن ہٕنٛز سرزمین وَننہٕ اوس یِوان۔\n14.\\tمانسی سٕندِس نیچوِس جیرَن نِیوو ارگوبُک سورُے مُلُک گیشوری تہٕ ماچتھی کِس ساحلس پیٹھ۔ تہٕ از تام اوس تمن پنن ناو بشنہووتجیر ونان۔\n15.\\tتہٕ مے دِژ گلعاد مچِرَس ۔\n16. تہٕ روبینن تہٕ گادیسن دِژ میہ گلعاد پیٹھہٕ دریائے ارنون تام نصف وادی تہٕ سرحد یوتام دریائے جابوک تام، {یُس} عمون کین بچن ہند سرحد چُھ۔\n17.\\tمیدانی تہٕ اردن تہٕ بٹھہٕ تہِ، چِنریتھ پیٹھہٕ میدانی سمندرس تام، {حتیٰ کہ} نوٗنہٕ سمندرس تام، اشدوتھپِسگاہ کِس مشرق کُن۔ {اشدوتھپیسگاہ؛ یا، پسگاہک چشمہٕ، یا، بال}\n18. تہٕ مے دِیُت تَمہِ وِزِ حُکُم، یہِ وَنُن زِ خداوند تُہٕندِس خدایہِ چُھہ یہِ زمین دِژمٕژ تہٕ تُہۍ گژھِو پننین باین ہٕندِس برونہہ کُن ہتھیار بٔنِتھ نیرِتھ، یُس سارِنٕے جنگہٕ خٲطرٕ مُلاقات سپدِ۔ {مِلُن...: ہیب۔ سنز آف پاور}\n19. مگر چانہِ زنانہٕ، تہٕ تُہٕندِ لۄکٕٹۍ تہٕ چاروٲے (کیازِ} بہٕ چُھس پتاہ زِ ژےٚ چُھہ واریاہ چاروٕ،) روزن پننین شہرن مَنٛز یِم مے ژے دِژمٕتۍ چھِ۔\n20. یوتام نہٕ خداوند تُہندین باین تہٕ تۅہہِ آرام دِیہ، تہٕ یوتام نہٕ تِمن سُہ زمینہٕ تہِ حٲصل کرِ، یُس خداوند تُہند خداہن تمن اردن نیبر دِژمُت چُھ، تہٕ {پتہٕ} کٔرِو تُہۍ پرٮ۪تھ أکِس نفرس تٔمۍ سٕندِس قبضس مَنٛز واپس، یُس مے ژے دِژمُت چُھ۔\n21. تہٕ مےٚ دِیُت تَمہِ وِزِ یشوع سُند حُکُم، یہِ وَنُن زِ تۅہہِ ہٕندِس خداہَن چھُ یِمن دۄن بادشاہن سٍتـ̡ یِمن سٍتـ̡ یِمن سٍتـ̡ یێلہِ تہٕ یێلہِ تہِ یێلہِ تێلہِ تێلہِ گٔژھِتھ چُھہ یێلہِ تہٕ یێلہِ تہِ یێلہِ تێلہِ تہِ یێلہِ تێلہِ تێلہ\n22. تِمن ہُند خوف گژھُن نہٕ: خداوند پنُن خدا سٕندِ خٲطرٕ کرِ سُہ تُہندِ خٲطرٕ جنگ۔\n23. تہٕ میہ کٔر تمہِ وِزِ خداوند سٕندِس سٍتـ̡ التجا کٔرِتھ وونُن،\n24. اے خداوند، ژے چُھہ پننِس بندس پَنُن عظمت، تہٕ پَنُن طاقتور اَتھٕ ہاوُن شروع کورمُت، یُس خدایہ چُھہ آسمانس یا زمینس مَنٛز، یُس تُہٕندِ کامہِ مُطٲبق تہٕ تُہٕندِس طاقتہٕ مُطٲبق ہیکہِ کٔرِتھ؟\n25.\\tبہٕ چُھس ژے دُعا کران زِ بہٕ گژھ اپارِ نیرُن، سُہ اصل زمین یُس اردنس نیبر چُھ، سہ اصل پہاڑ تہٕ لبنان۔\n26.\\tمگر خداوند اوس میانہِ خاطرہ شرارت تہٕ بوزُن نہٕ میانہِ خاطرہ، تہٕ خداوند ووٚن میہ زِ یہ گژھہِ کٲفی۔ میہ کٔر نہ اتھ معاملس متعلق مزید کتھ۔\n27.\\tپَنٕنۍ أچھ تُلِو مغرب کُن، شمالس کُن، جنوبس کُن تہٕ مشرقس کُن تُلِتھ تہٕ وُچھِو پنہٕ نِس أچھو سٍتـ̡ تہٕ وُچھِو نہٕ اتھ اردنس کُن۔ {پِسگاہ: یا، بال}\n28.\\tمگر یشوع سُند حکم دِیُن، تہٕ أمِس حوصلہٕ افزٲیی کٔرِو تہٕ مضبوٗط کرُن، تکیازِ سُہ گژھہِ یِمن لُکن برونہہ کُن نیرُن، تہٕ سُہ دِیہِ تِمن زمینہِ ہُند وارث یُس توے وُچھِو۔\n29.\\tیێلہِ أسۍ بِتھپیورَس خلاف وادی مَنٛز روزان۔","1. تێمہِ کِنۍ بوزو، اے اسرائیل، قوانینن تہٕ فیصلن ہٕنز یُس بہٕ ژے ہیچھناوان چُھ، یُس تہٕ تۅہہ کرُن، یُس تہٕ تُہۍ روزِو، تہٕ گژھِو تہٕ تتھ زمینس پیٹھ قبضہ کرُن یُس تُہٕندِس آباؤ اجداد سُند خداوند چُھہ دِژمُت۔\n2. یُس کلامُک بہٕ چُھس حُکُم کٔرِتھ تہٕ یُس بہٕ چُھس تُہٕندِس خدایہ سٕندِس حُکمن ہُند حُکُم تھاوُن، یُس بہٕ چُھس تُہٕندِس حُکُم سٍتـ̡ تھاوُن تہٕ تێلہِ کٔرِو نہٕ اَتھ سٍتـ̡ کم کٔرِتھ۔\n3. چُھہ تۅہہِ اچھن وُچھمُت زِ خداوند کیا کوٚر بعلپیور سٕندِ سٍتـ̡ یِمن سارِنٕے لُکن ہٕندِ خٲطرٕ، خداوند تُہٕندِس خداہن چُھ تِم پانس مَنٛز تباہ کٔرِمٕتۍ۔\n4. مگر یُس خداوند پنُن خدایہ چُھہ ژٔٹِتھ روزان چُھہ، چُھہ از تہٕ سارِوٕے أکِس زندٕ۔\n5. وُچھِو مے ژے شریعت تہٕ فیصلہٕ ہیچھناوٕنۍ، یێتھے پٲٹھـ̡ خداوند میانہِ خدایہ چُھہ میہ حُکُم دِژمُت، یێلہِ تہِ\n6. تَمہِ مۄکھٕ تھاوُن تہٕ کٔرِو {تِم}؛ یێلہِ چُھہ تُہٕنز حکمت تہٕ تُہٕنز فہم قومن ہٕندِس نظرس منز، یُس یِم سارِنٕے قونوُن بوزِ، تہٕ ونُن، یێلہِ یہِ بٔڈ قوم چُھہ اکھ عقلمند تہٕ سمجھدار لوکھ۔\n7. کُس قومہٕ چُھہ یُس خدا چُھہ تِمن نزدیک، یُس خداوند سُند خدا چُھہ تِمن سارِنٕے {چیزن منز} یُس أسـ̡ أمِس بُلان چُھہ؟\n8. تہٕ کُس قومہٕ چُھ یُتھ عظیم چُھ، یُس شریعت تہٕ فیصلہٕ چُھہ یُس میہ از ژے برونہہ کُن مقرر کورمُت چُھ؟\n9. صرف پَنُن پان ہوشیار تہٕ پَنُن روح تھاوُن محنتہٕ سٍتـ̡ یُس تُہٕندِس أچھن وُچھمُت چُھ، تہٕ یِم گژھن تُہٕندِس دِلہٕ سٍتـ̡ سارِنٕے دۅہن ہٕندِس دِلَس مَنٛز دِنہٕ، مگر تِمن ہیچھناوُن پَنٕنـ̡ نیٚچوـ̡ تہٕ پَنٕنـ̡ نیچوـ̡ ۔\n10.\\t{خاص کرِ} ییمہِ دۅہہ ژے حوربس منز خداوند پنُن خدایہ برونہہ کنہِ کھڑا گوو، ییلہِ خداوند میہ ووٚن، مے جمع کرو لوکھ جمع تہٕ بہٕ کرٕ تِمن پنٕنۍ کتھ بوزناوٕن، یُتھ زن تِم سارِنٕے دۅہن زمینس پیٹھ روزن، تہٕ تِم ہیچھناوِ پننین شُرین ہیچھناوٕنۍ۔\n11. تہٕ تُہۍ وٲتِتھ پہاڑس تَل کھڑا۔ تہٕ پہاڑ دٔزِتھ آسمانس منز، اوٚبر، اوٚبر، تہٕ گٔنۍ انہِ گٹہِ۔ {درمیان: ہیب۔ دِل}\n12.\\tتہٕ خداوند کٔر نارٕ منزٕ ژے سٍتـ̡ کتھ کرنہٕ: ژے بوز لفظن ہٕنز آواز، مگر وُچھُکھ نہٕ کانہہ ہِشر۔ صرف {ژیہ بوز} اکھ آواز۔ {صرف...: ہیب۔ اکھ آواز محفوظ کٔرتھ}\n13. تہٕ تٔمۍ کٔر توے پنُن عہد عیلن، یُس تۅہہِ دَہ حُکُم دِنُک حُکُم دِیُت۔ تہٕ تٔمۍ لیکھۍ تم کنن ہندین دۄن ٹیبلن پیٹھ۔\n14. تہٕ خداوند دِیُت میہ تمہِ وِزِ حُکُم زِ سُہ کرٕ ژے شریعت تہٕ فیصلہٕ ہیچھناوٕن، یُتھ تہٕ یێلہِ\n15.\\tتێلہِ کرو پانس سٍتـ̡ رژھرٕ۔ تکیازِ تمہِ دۅہہ وُچھ نہٕ تۅہہِ ہٕندِس دۅہہٕ {یُس} خداوند چُھہ نارس منزٕ حوربس مَنٛز کتھ کٔرِتھ:\n16. یێلہِ کٔرِو پان بد کار تہٕ کُنہِ تہِ شکلہِ ہٕنز تشبیہ، مرد یا زنانہٕ ہٕنز ہشر بَناوٕن،\n17.\\tکُنہِ تہِ درندٕ سٕنز ہِش یُس زمینس پیٹھ چُھ، کُنہِ تہِ پکھہٕ دار جاناوار سٕنز ہِش یُس ہوہس منز وُڑان چُھ،\n18.\\tکُنہِ تہِ چیزچ ہشر یُس زمینس پیٹھ کھسان آسہِ، کُنہِ تہِ گاڈِ ہٕنز ہشر یُس زمینہِ تل آبس منز {آسہِ}۔\n19. تہٕ یێلہِ ژے پَنٕنۍ أچھ آسمانس کُن تُلِتھ، تہٕ یێلہِ تہٕ آفتاب، زون تہٕ تارکھ وُچھِو، تہٕ یێلہِ تہِ یێلہِ تہِ یِمن ہٕنزِ عبادت کرنہٕ خٲطرٕ مجبور کرنہٕ یُن، یُس خداوند تُہند خداہن سارنٕے آسمانس تل سارنٕے قومن مَنٛز تقسیم کورمُت چھُ۔ {تقسیم: یا، دِنہٕ}\n20. مگر خداوند چُھ تُہہِ نِیومُت، تہٕ ژے ششتٕرِ بھٹہٕ منزٕ نیبر کٔرِتھ تہٕ یِتھ کٔنۍ تُہۍ از تہِ چھِو تٔمِس خٲطرٕ وٲرِثی لُکھ بٔنِتھ۔\n21. اَمہِ علاوٕ اوس خداوند میانہِ سٍتـ̡ چُھہ تُہٕندِ خٲطرٕ ناراض تہٕ قَسم کٔرِتھ زِ بہٕ گژھٕ نہٕ اردنس اَپار گژھُن، تہٕ بہٕ گژھٕ نہٕ تتھ اصل زمینس مَنٛز اژُن، یُس خداوند تُہند خدا چُھہ ژےٚ وَراثت دِژمُت:\n22. مگر بہٕ پزِ یَتھ سرزمینس مَنٛز مرُن، بہٕ پزِ نہٕ اردن اپارِ گژھُن، مگر ژے گژھِو اَتھ اصل زمینس پیٹھ قبضہ کرُن۔\n23. پانَس سٍتـ̡ ہوشیار گژھِو، یُس خداوند پنُن خدایہ سُند عہد مٔشِد گٔژھِو، یُس تٔمۍ تۅہہِ سٍتـ̡ بنوومُت چُھ، تہٕ تۅہہِ بَناوُن کُنہِ تہِ {چیز} ہٕنز شکلہٕ، یُس تُہٕندِس خداہِ سٍتـ̡ منع کورمُت چُھ۔\n24. خداوند سٕندِ خٲطرٕ چُھ تُہند خدا {چُھ} دزنہٕ وول نار، {حتیٰ کہ} حسد کرن وول خدا۔\n25.\\tییلہ تہِ ژیہ بچہٕ تہٕ شُرِ بٔنِتھ تہٕ زمینس مَنٛز واریاہس کالس روزِو، تہٕ کُنہِ تہِ چیزٕچ شکلہٕ بناوِو، تہٕ خداوند خدایہ سٕندِس نظرس منز کرِو بُرٕ کٔرِتھ، یُس أمِس غصہٕ دِنہٕ مۅکھہٕ کٔرِو:\n26. بہٕ چُھس از تہٕ آسمانس تہٕ زمینس پانس خلاف گواہی دِنہٕ خٲطرٕ بلاوان، زِ تُہۍ گژھو جلدٕے اتھ زمینہٕ سٍتـ̡ ختم گٔژھِتھ یێلہِ تہٕ یێلہِ تُہۍ اردنس پیٹھ قبضہ کرنہٕ خٲطرٕ گژھِو۔ تُہۍ گژھِو نہٕ اَتھ پیٹھ پَنٕنـ̡ دۅہہٕ زیٹھراوٕنـ̡ بلکہ گژھِو پوٗرٕ پٲٹھـ̡ تباہ کرنہٕ۔\n27. تہٕ خداوند کرِ تۅہہ قومن مَنٛز پھٔہلِتھ تہٕ یێلہِ یێلہِ خداوند تۅہہِ نِش نِیہ۔\n28. تہٕ اَتہِ کٔرِو تُہۍ دیوتاہن ہٕنزِ خدمت، یُس نہٕ وُچھان چُھ، بوزان چُھ، کھٮ۪وان تہٕ نہ چُھہ سونگھان۔\n29. مگر یێلہِ تتہِ پى۪ٹھہٕ پى۪ٹھہٕ خداوند پَنُن خدایہِ ژھانڈِو، تێلہِ میلہِ سُہ سُہ یێلہِ پنہٕ نِس دِلہٕ سٍتـ̡ تہٕ پنہٕ نِس پوٗرٕ دِلہٕ سٍتـ̡ سٍتـ̡ ژھانڈان چھُ۔\n30. یێلہِ تہٕ یێلہِ تُہۍ مُصیبتَس مَنٛز گژھِو، تہٕ یِم سٲری چیز یێلہِ تہِ پٔتِمِس دۅہس مَنٛز، یێلہِ تہٕ یێلہِ تہٕ تٔمۍ سٕندِس خدایہِ سٕندِس خداہس کُن پھیرِو، تہٕ تٔمۍ سٕنزِ آوازِ ہُند فرمانبردار روزُن۔ {are...: Heb. ہیو لوٚب ژے}\n31. (خداوند سٕندِ خٲطرٕ چُھہ تُہند خدا {چُھ} رحم دل خدا﴾ سُہ چُھہ نہٕ تۅہہِ ترٲوِتھ، نہ کرِ تُہہِ تباہ تہٕ نہ کرِ تُہٕندِس مٲلِس سٍتـ̡ سُہ عہد یُس تِمن سٍتـ̡ حلف کورمُت چُھ۔\n32.\\tوۅنۍ پرژھہِ تِمن دۅہن مُتلق یُس خداین زمینس پیٹھ انسان تخلیق کٔرِتھ تہٕ اسمانہٕ کہِ اکہِ طرفہٕ بییِس طرفہٕ پرژھہِ، یُس کانہہ بٔڈ چیز اوس، یا یِتھُے بوزنہٕ آمُت؟\n33.\\tکیا لُکو بوز خدایہ سٕنز آواز نارس منز، یِتھٕ کٔنۍ ژے بوزمُت، تہٕ زندٕ؟\n34.\\tیا کیا خداین چُھہ یہ حکم دِژمُت زِ سُہ گژھُن {تہٕ} کُنہِ قومہٕ منز، فتنہٕ سٍتـ̡، نشانو سٍتـ̡ تہٕ عجائبات سٍتـ̡ تہٕ جنگہٕ سٍتـ̡ تہٕ طاقتور اتھہٕ سٍتـ̡ تہٕ بٔڈۍ خوفہٕ سٍتـ̡ یُس خداوند تُہندِ خدایہِ سٍتـ̡ تُہٕندِ خٲطرٕ مصرس مَنٛز تُہٕندِس خٲطرٕ کورمُت چُھ؟\n35.\\tژے ہاونہٕ آمُت، یُتھ ژے ہٲوِتھ زِ خداوند چُھہ خدا۔ {امس علاوٕ} چُھ نہٕ بییہٕ کنہہ تہٕ۔\n36. آسمانہٕ منزٕ بنوو تۅہہ پنٕنۍ آواز بوزنہٕ خٲطرٕ، یُتھ سُہ کرِ تۅہہِ ہیچھناوُن: تہٕ زمینس پیٹھ ہٲو تۅہہِ پنُن بٔڈ نار۔ تہٕ ژے بوز تٔمۍ سٕنز کتھ نارس منز۔\n37.\\tتہٕ کیازِ سُہ چُھہ پننین مٲلن سٍتـ̡ محبت کران، تێمہِ کِنۍ ژٲر تِمن ہٕندِ پتہٕ تِہُند اولاد، تہٕ نیرُن تُہٕندِس نظرس منز پننہِ طاقتہٕ سٍتـ̡ مصرہٕ منزٕ نیبر۔\n38.\\tژے کھۅتہٕ بٔڈ تہٕ طاقتور قومن کڈنہٕ خٲطرٕ، ژے اَننہٕ خٲطرٕ، تہٕ تِہٕنز زمین دِنہٕ خٲطرٕ، یِتھ کٔنۍ از تہِ چھُ۔\n39. تێمہِ کِنۍ زانِو از دۅہہ، تہٕ پننِس دِلس مَنٛز غور کرُن، زِ خداوند چُھ آسمانس مَنٛز تہٕ بۄن کُن زمینس مَنٛز: {بێیہ} چُھہ نہٕ۔\n40. تێمہِ کِنۍ گژھ تٔمۍ سٕندِس حکمس تہٕ تٔمۍ سٕندِس حکمس پیٹھ عمل کرُن، یُس بہٕ از ژے حکم دِوان چُھ، یُتھ ژے تہٕ تُہٕندِس شُرِس سٍتـ̡ رٔلِتھ روزُن، تہٕ یُس خداوند تُہند خدا چُھہ دِژمُت، ہمیشہٕ خٲطرٕ روزُن۔\n41. پَتہٕ موسىٰ کٔر اَتھ طرفہٕ تریہ شہر اردنس کُن آفتاب کھسنہٕ کُن۔\n42.\\tزِ قاتل گژھہِ تتہِ ژلِتھ، یُس پننس ہمساین بے خبری منز مارِ، تہٕ پتھ کالس منز اوس نہٕ تس نفرت۔ تہٕ یِمو منزٕ کُنہِ شہرس کُن ژلِتھ ہیکہِ سُہ زندٕ روزِتھ:\n43.\\t{یعنی}، بیابانن منز، میدانی ملکس منز، روبینیٹس منز؛ تہٕ گیدِس مَنٛز رموتھ؛ تہٕ ماناسیٹس ہٕندِس باشانس منز گولان۔\n44. تہٕ یہِ شریعت یُس موسىٰ ین بنی اسرٲیلِس برونہہ کُن مقرر کورمُت:\n45.\\tیِم گواہ، تہٕ قونوُن، تہٕ فیصلہٕ، یِم موسىٰ ین مصرہٕ منزٕ نیرنہٕ پتہٕ بنی اسرٲیلِس سٍتـ̡ کٔرۍمٕتۍ،\n46.\\tاَمہِ طرفہٕ اردن، بیت پیورس خلاف وادی منز، امورین ہٕندِس بادشاہ سِحون سٕندِس سرزمینس منز، یُس ہیشبونس مَنٛز روزان اوس، یُس موسىٰ تہٕ بنی اسرٲیلِیو مصرہٕ منزٕ نیرنہٕ پتہٕ مار۔\n47.\\tتہٕ تِمن نِش ٲس تٔمۍ سٕنز زمین، تہٕ بشان کِس بادشاہ اوگ سٕنز زمین، یِم امورین ہٕندِس زٕ بادشاہس سٍتـ̡ ٲسۍ، یِم اتھ طرفہٕ اردن کُن آفتاب کھسنہٕ کُن ٲسۍ۔\n48.\\tآروئر پیٹھہ یُس دریائے ارنون کِس بٹھس پیٹھ {چُھ}، یوتام زِ سیون پہاڑس تام، یُس {چُھ} ہرمون،\n49. تہٕ اتھ طرفہٕ سورے میدان، اردن مشرقس کُن، حتیٰ کہ میدانک سمندرس تام، پسگاہ کِس چشمن تل۔","1. تہٕ موسىٰ ہن بُلوو سارِنٕے اسرٲیلِس تہٕ تِمن وونُن، اے اسرٲیل، تِم قونونن تہٕ فیصلہٕ یِم بہٕ از تہندین کنن منز کتھ کران چھِ، یُتھ تۅہہ ہیچھِو، تہٕ تھاوُن تہٕ یِم کرِو۔ {کیپ...: ہیب۔ تِم تھاوُن تھاوُن}\n2. خداوند سٲنـ̡ خداین کور اسہِ سٍتـ̡ حوربس مَنٛز اکھ عہد ۔\n3. خداوند چُھ نہٕ سانین مٲلن سٍتـ̡ یہِ عہد کورمُت، بٔلکہِ اسہِ سٍتـ̡ تہِ، یُس أسـ̡ سارِنٕے سٍتـ̡ از تہِ زندٕ چُھ۔\n4. خداوند کٔر نارس منز پہاڑس منز بتھہِ کُن کتھ کرنہٕ،\n5. (بہٕ اوسُس تَمہِ وِزِ خداوند تہٕ ژےٚ درمِیان کھڑا گومُت، تہٕ تۅہہِ اوس نہٕ نارٕ سٍتـ̡ کھوژمُت، تہٕ ووت نہٕ پہاڑس پیٹھ۔)\n6. بہٕ چُھس خداوند تُہند خدا، یُس ژے مصر کہِ سرزمینہٕ منزٕ غلامی ہٕندِس گرٕ منزٕ نِش نِش نیبر کٔرِ۔ {غلامی: ہیب۔ خادم}\n7. میانہِ برونہہ گژھہِ نہ کانہہ تہِ خدا۔\n8.\\tژے بناو نہ کانہہ تہِ کُنہِ چیزچ {کُنہِ چیز} ہِش یُس ہیرِ کُنہِ آسمانس مَنٛز، یا {چُھ} بۅنہ کنہِ زمینس مَنٛز، یا یُس {چُھ} زمینہٕ بۅنہ کنہِ آبس مَنٛز:\n9. تِمن سٍتـ̡ کٔرِو نہٕ پَنُن سجدٕ تہٕ تہٕ تِہٕنز خدمت کٔرٕن: کیازِ بہٕ چُھس خداوند تُہند خدا چُھس اکھ حسد کرن وول خدا، یُس مٲلن ہٕنزِ بدکاری ہٕندِس شُرین سٍتـ̡ دِوان چُھہ یُس میہ سٍتـ̡ نفرت کران چُھ،\n10.\\tتہٕ یِمن منز ساسہٕ بٔدۍ یِم میہ محبت کران چھِ تہٕ میانین حکمن پیٹھ عمل کران چھِ۔\n11. تُہۍ گژھ نہٕ پننِس خدایہِ سُند ناو بیکار رٔٹِتھ رٔٹِتھ، کیازِکہِ خداوند کرِ نہٕ تٔمِس بے گناہ یُس تٔمۍ سُند ناو بیکار رٔٹِتھ آسہِ۔\n12. سبت دۅہ تھاوُن یُس پاک کرنہٕ خٲطرٕ تھاوُن، یِتھ کٔنۍ تُہٕندِ خداہِ چُھہ تُہند حُکُم دِژمُت۔\n13. شیہ دۅہن کٔرِو محنت تہٕ پنٕنۍ سورے کٲم کٔرِو:\n14. مگر سٔتِم دۅہہٕ چُھہ خداوند تُہند خدایہ سُند سبت دۅہہٕ: اتھ مَنٛز گژھِ نہٕ توے کانہہ کٲم کٔرِتھ، نہ پنُن نیچو، نہ پنٕنۍ کورِ، نہ پنُن نوکر، نہ پنُن نوکر، نہ پنُن گَرد، نہ پنُن گَر، نہ پنُن کانہہ چارو، تہٕ نہ تُہٕندِس دروازس مَنٛز چُھہ کانہہ اجنبی یُس تُہٕندِس دروازس اندر چُھہ؛ یُتھ تُہند نوکر تہٕ تُہٕنٛز نوکر تہٕ تُہۍ تہِ آرام کٔرِتھ۔\n15.\\tتہٕ یاد تھاوُن زِ تہٕ تُہٕندِس خداہِ سٕندِس خداہَن دِژ ژےٚ تتہِ طاقتور اتھہٕ سٍتـ̡ تہٕ بٔڑِتھ نٔرِ سٍتـ̡ نِش نیبر۔\n16. پننِس مٲلِس تہٕ ماجہِ ہُند احترام کٔرِو، یِتھ کٔنۍ تُہٕندِس خداہِ سُند حُکُم چُھ دِژمُت۔ یُتھ زن تُہند دۅہ زیٹھراوُن، تہٕ یُتھ زمینہِ مَنٛز یُس خداوند تُہند خدا دِوان چُھ۔\n17.\\tژیہ گژھ نہ مارُن۔\n18.\\tتہٕ گژھِ نہٕ زنا کٔرِتھ۔\n19.\\tژیہ نہ ژوٗرِ کٔرِتھ۔\n20.\\tتہٕ تہٕ کٔرِو نہٕ پننِس ہمساین خلاف اپُز گوٲہی دِنہٕ۔\n21.\\tنہ گژھ پننس ہمساین سٕنزِ زنانہِ ہٕنز خواہش تہٕ نہ گژھ پننِس ہمساین ہٕندِس گرس سٕندِس گرس سٍتۍ، تٔمۍ سٕندِس کھہس سٕندِس کھہس سٍتۍ، یا تٔمۍ سٕندِس نوکرس سٕندِس خادمس سٍتـ̡ یا تٔمۍ سٕندِس خادمس سٍتـ̡ یا تٔمۍ سٕندِس گٔرِس سٍتـ̡ یا کُنہِ تہِ چیزس یُس تہندِس ہمساین سُند آسہِ۔\n22.\\tیِم لفظ کٔر خداوند تُہٕندِس سارِنٕے مجلسس سٍتـ̡ نارس منز، اوٚبرٕ سٍتـ̡ تہٕ گٔنِس انہِ گٹہِ منز، بٔڈۍ آوازٕ سٍتـ̡ تہٕ تٔمۍ کٔر نہٕ بییہ کانہہ تہِ اضافہٕ۔ تہٕ تٔمۍ لیکھۍ تِم کنن ہٕندِس دۄن ٹیبلن منز، تہٕ واتنووُن میہ تام۔\n23.\\tتہٕ ییلہ ژے انہِ گٹہِ منزہ آواز بوز، (تکیازِ پہاڑ اوس نارس سٍتـ̡ دزان،) تہٕ ژے وٲتِو میہ نزدیک، حتیٰ کہ پننین قبیلن ہٕندِ سارِنٕے سربراہ تہٕ تُہند زِٹھہٕ۔\n24. تہٕ تۅہہ ووٚن، وُچھو، خداوند سٲنِس خداہن ہٲو اسہِ پَنُن جلال تہٕ عظمت، تہٕ اسہِ چُھ نارس منزٕ تٔمۍ سٕنز آواز بوزمٕژ: اسہِ چُھ از وُچھمُت زِ خدا چُھ انسانس سٍتـ̡ کتھ کران، تہٕ سُہ چُھ زندٕ روزان۔\n25. وۅنۍ کیازِ پزِ اسہِ مرُن؟ تکیازِ یہ بٔڈ نار گژھہِ اسہِ کھالِتھ: اگر أسۍ بییہِ تہِ پننِس خدایہ سٕنز آواز بوزو، تیلہِ گژھہِ أسۍ مرُن۔ {بوزو: ہیب۔ بوزنَس منٛز کٔرِو شٲمِل}\n26.\\tسارِنٕے ماز سٍتـ̡ کُس چُھہ یُس زندٕ خدایہ سٕنز آواز بوزمُت چُھ، یُس نارس مَنٛز کتھ کران چُھ، یێلہِ أسـ̡ أسـ̡ {چُھ} تہٕ زندٕ رودمُت؟\n27.\\tیێلہِ گژھِو یێلہِ سٍتـ̡ خداوند سُند خدا کتھ کرِ، تہٕ سُہ کتھ کرٕنـ̡ یُس خداوند سُند خدا چُھہ تۅہہِ سٍتـ̡ کتھ کرِ تہٕ أسۍ بوزو {یہ}، تہٕ کرو {یہ}۔\n28.\\tتہٕ خداوند بوز تُہنزِ کلامٕچ آواز، یێلہِ تہٕ یێلہِ ژے میہ سٍتـ̡ کتھ کٔرِ۔ تہٕ خداوند ووٚن میہ زِ مے چُھہ یمن لوکن ہٕندِ کلامٕچ آواز بوزمٕژ، یُس تِمو تۅہہِ سٍتـ̡ کتھ کٔرمٕژ چُھ، تِمو چُھ سُہ سُہ وَننہٕ آمُت۔\n29.\\tکاش تِمن مَنٛز یُتھ دِل آسہِ، زِ تِم آسن میہ کھوژان، تہٕ میٲنۍ سارِنٕے حُکُم روزن ہمیشہٕ، یُتھ زن تِمن سٍتـ̡ تہٕ تِہندین شُرین سٍتـ̡ ہمیشہٕ روزُن!\n30.\\tگژھ تمن ونُن، ژیہ کرو بییہ پننین خیمن منز۔\n31.\\tمگر ژے کٔرِو میہ سٍتـ̡ کھڑا تہٕ بہٕ کَرٕ ژے سٍتـ̡ سٲری حُکُم، تہٕ قوانین، تہٕ فیصلہٕ، یُس ژے تِمن ہیچھناوُن، یُس بہٕ تِمن دِنہٕ آمُت چھُ، یُس بہٕ تِمن دِنہٕ آمُت چھُ۔\n32. تَمہِ کِنۍ گژھِو یِتھ کٔنۍ خداوند تُہٕندِس خدایہِ سُند حُکُم دِیُتمُت چھُ، تہٕ گژھِو نہٕ دٔچھنِس کُن تہٕ کھوورِ طرفہٕ پھیرُن۔\n33. تُہۍ پٔکِو تِمن سارِنٕے وتہٕ سٍتـ̡ یِمن ہُند حُکُم چُھہ تُہٕندِس خداہس سٍتـ̡ دِژمُت چُھ، یێلہِ تہٕ یێلہِ تُہٕندِس زمینس مَنٛز روزُن پَنٕنـ̡ دۅہہٕ روزُن۔","1. وۅنۍ چِھ یِم حُکُم، قونوُن، تہٕ فیصلہٕ، یِم خداوند تُہٕندِس خداہَن چُھہ تۅہہِ ہیچھناوُن حُکُم دِژمُت، یُس تُہٕندِس زمینس مَنٛز کٔرِتھ یێلہِ تہِ یێلہِ تُہۍ یہِ حٲصِل کرنہٕ خٲطرٕ گٔژھِو: {گٔژھِو: حب۔ پاس اوور}\n2. یێلہِ ژٕ ہێکہِ خداوند پنٕنِس خداہس سٍتـ̡ خوف کٔرِتھ، یێمہِ سٍتـ̡ تٔمۍ سٕندِس سارِنٕے حکمس تہٕ تٔمۍ سٕندِس حُکمن ہُند حُکُم چُھس، یُس بہٕ چُھس تہٕ تُہٕندِس نیچوِس سٍتـ̡ تہٕ تُہٕندِس نیچوِس سٍتـ̡ سارِنٕے دۅہن ہُند حُکُم دِوان چُھس۔ تہٕ تُہند دۅہ گژھن زیٹھراوُن۔\n3.\\tاے اسرائیل، بوزو تہٕ کرُن {یہ}۔ یُتھ زن تۅہہِ سٍتـ̡ رٔٹِتھ روزُن، تہٕ یێلہِ تُہٕندِس مٲلِس خداہِ سٕندِس خداہِ سٍتـ̡ دۄدٕ تہٕ ماچھ سٍتـ̡ وسان چھُ۔\n4. بوزو، اے اسرائیل: خداوند سون خدا {چُھ} اکھ خدا:\n5. تہٕ تہٕ پَنٕنہِ سارِوٕے دِلہٕ سٍتـ̡ تہٕ پَنٕنـ̡ سارِنٕے دِلہٕ سٍتـ̡ تہٕ پَنٕنـ̡ سارِوٕے طاقتہٕ سٍتـ̡ محبت کٔرِو۔\n6. تہٕ یِم لفظ یِم بہٕ از ژے حُکُم دِوان چھِ، تُہٕندِس دِلس مَنٛز آسن:\n7.\\tتہٕ تُہۍ ہیچھناوُن پننین شُرین تہٕ ییلہ تہٕ تُہۍ پنہٕ نِس گرس مَنٛز بِہتھ تہٕ وتہِ پکان تہٕ ییلہ تہٕ وتہِ پکان چھِو، تہٕ ییلہ تہٕ ژے تھوٚد کھسِتھ تہٕ تِمن متعلق کتھ کرٕنۍ۔ {ہیچھناوُن: ہیب۔ وہٹ، یا، تیز}\n8.\\tتہٕ تِم گٔژھِو پننہِ اَتھٕ سٍتـ̡ أکِس نشانہٕ سٍتـ̡ بٔنِتھ تہٕ تِم گژھن تُہنزن اچھن مَنٛز بٔنِتھ۔\n9. تہٕ تُہۍ لیکھِو یِم پننہِ گرٕ کِس کھورِ تہٕ دروازن پیٹھ۔\n10. تہٕ یێلہِ یێلہِ خداوند تُہُند خدایہ تُہہِ تُہٕندِس مٲلِس سٍتـ̡ ، ابراہیم، اسحاق تہٕ یعقوبس سٍتـ̡ تہٕ یعقوبس سٍتـ̡ عٔظیٖم تہٕ اصل شہر دِنہٕ خٲطرٕ، یُس نہٕ ژے بٔنِتھ آسہِ،\n11.\\tتہٕ سارِوٕے اصل چیزو سٍتـ̡ بٔرِتھ مکانہٕ، یِم نہٕ ژے بٔرِتھ آسہِ، تہٕ کُرٕ کھٔنِتھ یِم نہٕ ژے کھٔنِتھ چھِ، انگور تہٕ زیتون کُلۍ، یِم نہٕ ژے لگٲومٕتۍ۔ ییلہ ژیہ کھیوٚو تہٕ پورٕ گژھہِ؛\n12. {پَتہٕ} ہوشیار روزُن یُس خداوند مٔشِد گٔژھِتھ یُس ژے مصرٕچ سرزمینہٕ منزٕ غلامی ہٕندِ گرٕ منزٕ نیبر کڈُن۔ {غلامی: ہیب۔ غلام یا خادم}\n13. تہٕ پَزِ پَنٕنِس خداہٕ سٕندِس خداہس سٍتـ̡ خوف تہٕ تٔمِس سٍتـ̡ پۯاوُن تہٕ تٔمِس سٕندِس ناوُک قَسم کٔرِو۔\n14. تُہۍ گژھِو نہٕ باقٕے دیوتاہن ہٕندِس پَتہٕ یِمن لُکن ہٕندِس دیوتاہن ہٕندِس پٔکھۍ یِم پانس اندۍ پٔکھۍ چھِ۔\n15.\\t(خداوند سُند خدا چُھہ تُہند خدا چُھہ یُس تۅہہِ مَنٛز حسد کٔرِتھ) یێلہِ گژھہِ تۅہہِ سٍتـ̡ خدایہِ سُند غصہٕ تہٕ تُہٕندِس خداہس سٍتـ̡ ژٔلِتھ تہٕ ژیہ کرِ زمینہٕ سٍتـ̡ تباہ کرنہٕ۔\n16. یِتھٕ پٲٹھـ̡ چُھہ نہٕ تُہٕندِس خداہس آزمائش کٔرِتھ، یِتھٕ پٲٹھـ̡ تُہٕندِس خداہس سٍتـ̡ آزمائش کٔرِو۔\n17. خداوند پنُن خدایہ سٕندِس حُکمن تہٕ تٔمۍ سٕنزِ گوٲہی تہٕ تٔمۍ سٕندِس قوانینن ہٕندِس حُکمس سٍتـ̡ پٲٹھـ̡ تھاوُن، یُس تٔمۍ سُند حُکُم چُھ دِژمُت۔\n18.\\tتہٕ یُس خداوند سٕندِس نظرس منز صحیح تہٕ اصل آسہِ، یُتھ تہٕ یُس تۅہہِ سٍتـ̡ رٔٹِتھ روزُن، تہٕ یُس خداوند پننین مٲلن سٍتـ̡ حلف دِژمُت چُھ،\n19. پَنٕنـ̡ سارِنٕے دُشمن کٔرِو پانس برونہہ کُنـ̡ کٔرِتھ، یێلہٕ پٲٹھـ̡ خداوند چُھ کَرنہٕ آمُت۔\n20. {تہٕ} ییلہِ تُہند نیچو یِنہٕ وٲلِس وقتس منز ژےٚ پرژھہِ، یہِ ونان زِ گوٲہی، قوانین، تہٕ فیصلہٕ کیا چُھہ، یِمن ہُند حُکُم چُھ تۅہہِ دِژمُت؟ {منز...: ہیب۔ پگہہ کُن}\n21. تیلہٕ چُھہ پننِس نیچوِس وَنُن زِ أسۍ أسۍ مصرس مَنٛز فرعون سٕندِ غلام ٲسۍ۔ تہٕ خداوند کٔر اسہِ طاقتور اتھہٕ سٍتـ̡ مصرہٕ منزٕ نیبر:\n22.\\tتہٕ خداوند ہٲو مصرس پیٹھ، فرعونس پیٹھ تہٕ تٔمۍ سٕندِس سارِنٕے گرس پیٹھ، سانہِ نظرن برونہہ کنہِ نشانہٕ تہٕ عجائب ہاونہٕ: {درد: حب۔ برائی}\n23. تہٕ تٔمۍ کٔر اسہِ تتہِ نِش نٮ۪بر، یُس سُہ اسہِ اَننہٕ خٲطرٕ، سُہ زمین دِنہٕ خٲطرٕ یُس سُہ سانٮ۪ن مٲلن سٍتـ̡ قسم دِوان چھُ۔\n24. تہٕ خداوند دِیُت اسہِ یِم سارِنٕے قونوٗن انجام دِنُک حُکُم زِ سُہ کرِ اسہِ زِندٕ روزُن، یِتھ کٔنۍ زِ سُہ روزِ اسہِ زِندٕ رژھراونہٕ، یِتھ کٔنۍ از تہِ چُھ۔\n25. تہٕ یێلہِ أسـ̡ یِم سارِنٕے حُکُم خداوند سٕندِس خداہس برونہہ کُن یِم سارِنٕے حُکمن ہُند عمل کرُن، یێلہِ تٔمۍ اسہِ حُکُم دِژمُت چُھ۔","1. یێلہِ خداوند تُہُند خدا ژے تتھ زمینس مَنٛز انِتھ یێلہِ تہٕ تۅہہِ سٍتـ̡ یێلہِ تہٕ ژے سٍتـ̡ واریاہ قوتہٕ کٔرِتھ تہٕ ژے سٍتـ̡ واریاہ قوتہٕ کٔرِتھ تہٕ یِمن ہٕندِس سٍتـ̡ تہٕ یِمن ہٕندِس سٍتـ̡ سَتھ قومہٕ ژے کھۅتہٕ زیادٕ بٔڈ تہٕ طاقتور چھِ۔\n2. تہٕ یێلہِ خداوند تُہُند خدا تُہٕندِس برونہہ کُن نجات دِیہِ۔ ژے کرِ تمن مارُن، {تہٕ} مکمل طور تباہ کرُن۔ تِمن سٍتـ̡ کٔرِو نہٕ کانہہ عہد تہٕ نہ کرُن تِمن سٍتـ̡ رحمت:\n3.\\tتِمن سٍتـ̡ گژھِ نہٕ خاندر کٔرِتھ۔ پنٕنۍ کوٗر دِیُکھ نہٕ تٔمۍ سٕندِس نیچوِس تہٕ نہ تٔمۍ سٕنز کورِ پَنٕنِس نیٚچوِس نِش نِنہٕ۔\n4. تِکیازِ تِم رٔٹِن تُہُند نیچو میانہِ پتہٕ یِنہٕ نِش، یُتھ زن تِم باقین دیوتاہن ہٕنز خدمت کٔرِتھ، یِتھٕ پٲٹھۍ گژھہِ خداوند سُند غصہٕ تہٕ ژےٚ گژھہِ اچانک تباہ کرنہٕ۔\n5.\\tمگر یِتھٕ پٲٹھۍ کرو تِمن سٍتـ̡ سٍتـ̡ سٍتـ̡ تِہٕنزِ قربان گاہ تباہ کٔرِو، تہٕ تِہٕنزِ شکلہٕ پھُٹرٲوِو، تہٕ تِہٕندِ باغہٕ ژٹِوٕن، تہٕ تِہٕنزِ کھٔنِتھ بُتٕہ زٲلِتھ نارٕ سٍتـ̡ زالنہٕ۔ {تہنز تصویر: ہیب۔ تہند مجسمہٕ، یا، ستون}\n6. تِکیازِ تُہۍ چُھہ خداوند پنُن خدایہِ سٕندِ خٲطرٕ اکھ مقدس لُکھ چُھ، یُس تُہٕندِس خداہِ سٍتـ̡ چُھہ ژے پانس سٍتـ̡ اکھ خاص لُکھ بننہٕ خٲطرٕ منتخب کورمُت، سارِنٕے لُکن ہٕندِ کھۅتہٕ زیادٕ۔\n7. خداوند کٔر نہٕ توے سٍتـ̡ پَنُن محبت تہٕ نہ چُھہ ژٲرمُت، تکیازِ تۅہہِ ٲسِو کُنہِ تہِ لُکہٕ کھۅتہٕ زیادٕ تعداد۔ تکیازِ تم ٲسۍ سارِنٕے لُکن منز سارِوٕے کھۄتہٕ کم:\n8. مگر کیازِ خداوند چُھ تۅہہِ محبت کٔرمٕژ، تہٕ یُس تٔمۍ تُہٕندِس آباؤ اجدادن سٍتـ̡ حلف کورمُت اوس، تێلہِ چُھہ خداوند ژے طاقتور اتھہٕ سٍتـ̡ نیبر کٔرِتھ، تہٕ کٔرٕن تۅہہِ غلامَن ہٕندِس گرٕ منز، مصرٕکِس بادشاہ فرعون سٕندِ اتھہٕ نِش نجات دِنہٕ۔\n9. تێمہِ کِنۍ زانِو زِ خداوند چُھہ تُہند خدا، سُہ چُھہ خدا، یُس تِمن سٍتـ̡ عہد تہٕ رحمتُک عمل تھاوان چُھ، یُس أمِس سٍتـ̡ محبت کران چُھہ تہٕ تٔمۍ سٕندِس حکمس ساس پُردن تام تھاوان چُھ۔\n10.\\tتہٕ یُس أمِس نفرت کران چُھ، تِمن ہُند بدلہٕ دِیہِ تِمن ہٕندِس بُتھِس سٍتـ̡ دِنہٕ۔\n11. تێمہِ کِنۍ گژھ تُہۍ حُکمن تہٕ قوانینن تہٕ فیصلن ہٕنز پاسداری کرٕن، یِم بہٕ ژے از دۅہہ حکم دِوان چھِ۔\n12.\\tتێلہِ گژھہِ یێلہِ یِمن فیصلن ہٕنز کتھ بوزن، تہٕ یێلہِ تُہٕندِس خداہس سٍتـ̡ تہٕ یێلہِ تُہٕندِس مٲلِس سٍتـ̡ عہد تہٕ رحمتُک قایم کرُن: {if: Heb. کیازِ}\n13. تہٕ سُہ کرِ تۅہہِ محبت، تہٕ دِیہِ تۅہہِ برکت، تہٕ کرِ تۅہہِ ہُند پھل، تہٕ تُہٕنزِ زمینہِ ہُند پھل، تہٕ تُہٕندِس شراب، تہٕ تُہٕندِس تیٖلس سٍتـ̡ تہٕ تُہٕندِس کۅکرِ ہٕندِس مَولہٕ سٍتـ̡ تہٕ تُہٕندِس کۅکرس سٍتـ̡ دِنہٕ خٲطرٕ تہٕ تُہٕندِس مٲلِس سٍتـ̡ دِنہٕ خٲطرٕ تہٕ دِیہِ تُہٕندِس مٲلِس سٍتـ̡ دِنہٕ خٲطرٕ۔\n14.\\tژے گژھہِ سارِنٕے لُکن ہٕندِس برکتس سٍتـ̡ برکت حٲصِل کرنہٕ، تہٕ ژے آسہِ نہٕ تہندِس چارواین مَنٛز نَر تہٕ زنانہٕ بنجر۔\n15.\\tتہٕ خداوند کرِ ژے نِش سارِنٕے بیمارِ دور تہٕ تۅہہِ سٍتـ̡ کرِ نہٕ مصرٕچ بد بیمارِ یُس توے زانان چُھ، تێلہِ تراوِ نہٕ۔ مگر تِمن سارِنٕے سٍتـ̡ یِم تۅہہِ سٍتـ̡ نفرت کران چھِ۔\n16. تہٕ تُہۍ کٔرِو تِمن سارِنٕے لُکن کھٮ۪وان یِم خداوند تُہُند خدا ژےٚ نجات دِیہِ۔ چانہِ أچھ گژھِ نہٕ تِمن پیٹھ رحم کٔرِتھ، تہٕ نہ کٔرِو تہندٮ۪ن دیوتاہن ہٕنز عبادت کرنہٕ۔ تۅہہ آسہِ تۅہہِ خٲطرٕ اکھ جال۔\n17.\\tاگر ژیہ پننِس دلس منز وَنُن زِ یِم قوم چھِ میانہِ کھۅتہٕ زیادٕ زیادٕ۔ بہٕ کِتھ کٔنۍ ہیکہٕ تمن بے دخل کٔرتھ؟\n18.\\tتُہۍ گژھِ نہٕ تِمن سٍتـ̡ خوفزدہ گژھُن: {مگر} گژھہِ یاد تھاوُن زِ خداوند تُہند خداہن کیا کوٚر فرعونس تہٕ سارنٕے مصرس سٍتـ̡ ۔\n19. یِم بٔڈ فتنہ یُس تۅہہِ أچھن وُچھمُت، تہٕ نشانہٕ، تہٕ عجائبات، تہٕ طاقتور اتھہٕ، تہٕ بٔڑِتھ نٔر یێمہِ سٍتـ̡ خداوند تُہٕندِس خدایہِ سٍتـ̡ تُہٕندِس خدایہِ سٍتـ̡ تُہٕندِس خدایہِ سٍتـ̡ یِمن سٍتـ̡ تُہٕندِس خدایہِ سٍتـ̡ تُہٕندِس خداہس سٍتـ̡ یِمن سٍتـ̡ تُہٕندِس خدایہِ سٍتـ̡ تُہٕندِس سٍتـ̡ کٔرِتھ تہٕ یِمن سٍتـ\n20.\\tامہِ علاوٕ، خداوند تُہند خدا سوزِ تِمن مَنٛز ہارنیٹ، یوتام نہٕ یِم باقٕے روزان تہٕ تۅہہِ نِش ژوٗرِ روزن۔\n21. تُہۍ گژھِ نہٕ تِمن سٍتـ̡ خوفزدہ گژھُن: یێلہِ خداوند تُہُند خدا چُھہ یُس تُہُند خدا چُھہ تُہٕندِس مَنٛز اکھ طاقتور تہٕ خوفناک۔\n22. تہٕ خداوند تُہند خدا کرِ تِم قومن پانس برونہہ کُن کم وارٕ وارٕ ژٔٹِتھ، تہٕ ژے ہێکہِ نہٕ یِم اَکی ساتہٕ کھٮ۪نہٕ یِن، یێلہِ کھێلہِ ہٕندِس درندَس ہُند ہُرراوُن۔ {پُٹ...: ہیب۔ تُلُن بند کٔرِو}\n23. مگر خداوند تُہند خدا کرِ تِم تۅہہِ تام واتناوُن، تہٕ کرِ تِم تباہ کٔرِتھ تِم تباہ کرنہٕ۔ {اُن...: ہیب۔ تۅہہِ بُتھِس برونہہ کُن}\n24. تہٕ سُہ دِیہِ تِہٕندِس بادشاہس پانس اتھس مَنٛز، تہٕ توے کٔرِو تِہُند ناو اسمانس تل تباہ کٔرِتھ، توٚت تام ہیکہِ نہٕ کانہہ تہِ انسان تۅہہِ برونہہ کُن کھڑا گژھِتھ، یوٚت تام نہٕ تِم تباہ کرِ۔\n25.\\tتِہندین دیوتاہن ہٕنزِ کھٔنِتھ بٔنِتھ تہٕ یِمن سٍتـ̡ رۄپہٕ تہٕ سۄنہٕ یُس نہٕ تِمن سٍتـ̡ رۄپہٕ سٍتـ̡ رٔٹِتھ تہٕ نِیُن تہٕ نِیُن پانس نِش نِن، یێلہِ گژھہِ تُہٕندِس خداہس سٍتـ̡ پۯاوُن، تکیازِ یہِ چُھہ خداوند تُہندِ خداہٕ سٕندِ خٲطرٕ ناپسندیدگی ہٕندِس سٍتـ̡ ناپسندیدٕ۔\n26.\\tتہٕ تہٕ کُنہِ تہِ کُنہِ گَرَس مَنٛز اَنُن، یێلہِ گژھِو تۅہہِ یِتھُے بد دُعا بٔنِتھ: {مگر} ژے کٔرِو اتھ سٍتـ̡ سراسر نفرت، تہٕ توے کٔرِو اتھ سٍتـ̡ نفرت۔ تکیازِ یہ {چھُ} اکھ لعنتی چیز۔","1. تِم سٲری حُکُم یِم بہٕ ژے از دۅہہ حکم دِوان چھِ، یُس تۅہہِ زندٕ روزُن، تہٕ بٔڈِتھ تہٕ گژھِو تتھ زمینس پیٹھ قبضہ کٔرِتھ یُس خداوند پننین مٲلن سٍتـ̡ حلف دِژمُت چھُ۔\n2.\\tتہٕ ژے روزِ یاد روزُن یُس خداوند تُہند خدایہ ژۅتجی ؤرین بیابانس مَنٛز دِژمُت، تہٕ تۅہہِ ثٲبت کرنہٕ خٲطرٕ، تہٕ یہ زاننہٕ خٲطرٕ زِ تُہندِس دلس مَنٛز کیا چُھہ، کیا چُھہ تٔمۍ سٕندِس حکمس پیٹھ عمل کٔرِتھ، کِنہٕ نہٕ۔\n3.\\tتہٕ تٔمۍ کٔر تۅہہِ عاجزی تہٕ فاقہٕ تہٕ دِژُن ژے مَنا کھٮ۪وان، یُس نہٕ ژے زانان اوس، تہٕ تہندٮ۪ن مٲلن ٲس نہٕ خبر۔ یێلہِ سُہ گژھہِ تۅہہِ زانہِ زِ انسان چُھ نہٕ صرف روٹی سٍتـ̡ زندٕ روزان، بٔلکہِ چُھ خداوند سٕندِ ٲسہِ منزٕ نیرن وٲلِس پرٮ۪تھ کُنہِ لفظہٕ سٍتـ̡ زندٕ روزان۔\n4.\\tچانۍ پوشاک ووت نہ ژیہ پرون تہ نہ کھۅر پھوٚلمت یمن ژتٲجی ؤرین پیٹھ۔\n5. تُہۍ گژھہِ پننِس دِلس مَنٛز تہِ غور کرُن، یِتھٕ پٲٹھۍ انسان پننِس نیچوِس سزا دِوان چُھ، تِتھے پٲٹھـ̡ خداوند چُھہ تُہند خدا تہِ عذاب۔\n6. تێمہِ کِنۍ گژھِو خداوند پَنٕنـ̡ خدایہِ سٕندِس حُکمن ہٕنز پاسداری، تٔمۍ سٕنزِ وتہِ پٲٹھـ̡ پٔکِتھ تہٕ تٔمِس سٍتـ̡ خوفزدہ روزُن۔\n7. خداوند سٕندِ خٲطرٕ چُھ تُہند خدا ژے أکِس اصل زمینس مَنٛز انان، یُس آبہٕ کِس نالہٕ سٍتـ̡ تہٕ سرٛنٮ۪ر سٍتـ̡ یُس وادی تہٕ بالہٕ منزٕ نیران چُھ۔\n8.\\tکٕنٕک، جو، تہٕ انگور تہٕ انجیر کُلۍ تہٕ انار ہٕنز زمین۔ تیل، زیتون تہٕ شہد ہٕنٛز سرزمین؛ {تیل...: ہیب۔ تیلُک زیتون کُل}\n9. یُس سرزمینہٕ یَتھ مَنٛز تُہۍ بَنہٕ بغٲر روٹی کھٮ۪وان آسہِ، اَتھ مَنٛز گژھِ نہٕ کُنہِ تہِ کُنہِ چیزٕچ کٔمی۔ اکھ زمین ییمِچ کٔنہِ ششتٕر چھِ، تہٕ ییمِس بالو منزٕ ژے پیتل کھٔنِتھ ہیکو۔\n10. ییلہِ ژے کھیوٚو تہٕ پوٗرٕ گژھِو، تیلہِ کٔرِو خداوند پنُن خدایہ سٕندِس نیک زمینہٕ خٲطرٕ برکت یُس تٔمۍ ژےٚ دِژمُت چھُ۔\n11. خبردار روزُن زِ ژے گژھ نہٕ خداوند پنُن خدا، تٔمۍ سٕندِس حکمن، تہٕ تٔمۍ سٕندِس حکمس تہٕ تٔمۍ سٕندِس قوانینن پیٹھ عمل نہ کٔرِتھ، یُس بہٕ از ژے حکم دِوان چُھس:\n12. یێلہِ چُھہ ژے کھٮ۪وان تہٕ بٔرِتھ تہٕ رٔٹِتھ بٔنِتھ روزُن۔\n13.\\tتہٕ ییلہ تُہٕندِ گُرٕ تہٕ تُہٕندِ رۄپہٕ تہٕ سۄنہٕ بٔڑِتھ تہٕ تُہٕندِس سٍتـ̡ یێلہِ تہٕ تُہٕندِس سٍتـ̡ چُھہ سُہ سُہ زیادٕ سپدِ۔\n14. تیلہِ گژھہِ پنُن دِل تُلُن، تہٕ ژے گژھ خداوند پنُن خدا، یُس ژے مصرٕچ سرزمینہٕ منزٕ غلامی ہٕندِ گرٕ منزٕ نیبر کڈُن آو۔\n15.\\tکٔمۍ کٔر ژے تتھ عظیم تہٕ خوفناک بیابانس مَنٛز، {یَتھ مَنٛز} نار ناگ، تہٕ بِچھو، تہٕ خشک سالی ٲس، ییتہِ نہٕ آب اوس نہٕ۔ یُس ژے چِھنہٕ کِنہِ چِھنہٕ منزٕ آب دِنہٕ آمُت۔\n16.\\tیُس ژے بیابانس مَنٛز منا کھیوٚو، یُس نہٕ تۅہہِ ہٕندِس مٲلس پتاہ اوس، یُس نہٕ تۅہہِ عاجز کرِ، تہٕ سُہ کرِ تۅہہِ ثٲبت کرنہٕ، یُس تۅہہِ ہٕندِس ٲخری اندس پیٹھ نیکی کرِ۔\n17.\\tتہٕ ژے چُھہ پننِس دِلس منز ونان زِ میانہِ طاقتہٕ تہٕ میانہِ اتھہٕ ہٕندِ طاقتن دِژ مے یہِ دولت۔\n18.\\tمگر توے پزِ خداوند پنُن خدایہ یاد تھاوُن، کیازِ سُہ چُھ سُہ یُس تۅہہِ دولت حٲصل کرنُک اختیار دِوان چُھ، یُس سُہ پَنُن عہد پورٕ کرِ، یُس سُہ پننین مٲلن سٍتـ̡ حلف کٔرِتھ، یُس از تہِ چُھ۔\n19. تہٕ یێلہِ تہِ گٔژھِو تۅہہِ خٕلاف۔\n20. یِتھٕ پٲٹھـ̡ یِمن قومن ہُند خداوند تُہٕندِس بُتھِس برونہہ کُن تباہ چُھہ کٔرِتھ، تِتھے پٲٹھـ̡ گژھِو تُہۍ فنا گٔژھِو۔ تکیازِ تۅہہِ آسہِ نہٕ خداوند پنُن خدایہ سٕنزِ آوازِ ہٕنز فرمانبردار۔","1. بوزو، اے اسرٲیل: ژے چُھہ از دۅہہ اردن مٔنزۍ نیرُن، پانس کھوتہ بٔڈ تہٕ طاقتور قومن پیٹھ قبضہ کرنہٕ خٲطرٕ اژُن، یِم شہر عظیم تہٕ آسمانس تام تار لگاونہٕ آمٕتۍ،\n2.\\tاکھ بٔڈ تہٕ تھوٚد لُکہٕ، یُس تۅہہ زانان چھُ، تہٕ یِمن مُتلق ژے بوزمُت چھُ، یُس انک سٕندِس بچس برونہہ کُن کھڑا ہیکہِ ٲسِتھ!\n3.\\tتێلہِ گژھہِ از دۅہہ سمجُن زِ خداوند تُہند خدا چُھہ سُہ یُس توے برونہہ کُن گژھان چُھ۔ یِتھٕ پٲٹھـ̡ دَزنہٕ یِنہٕ وٲلِس نارس سٍتـ̡ سُہ کرِ تِم تباہ تہٕ سُہ کرِ تِم تُہٕندِس بُتھِس برونہہ کُن، یێلہِ کٔرِو تِم ژٔٹِھتھ تہٕ یِمن ہُند ژٔٹِھتھ ژٔلِتھ تہٕ یِمن ہُند وَنُن چُھہ تۅہہِ سٍتـ̡ دِژمُت۔\n4. پَنٕنِس دِلَس مَنٛز کَتھ کٔرِو نہٕ، یێمہِ پَتہٕ خداوند تُہٕندِس خداین تێمہِ سٍتـ̡ تِم ژے برونہہ کُن کٔڑِتھ دِژمُت، یہِ ؤنِتھ زِ میانہِ نیکی سٍتـ̡ چُھہ خداوند یِمن زمینہٕ حٲصِل کرنہٕ مۅکھہٕ بێیہِ دِژمُت، مگر یِمن قومن ہٕنزِ بدکٲری کِنہِ چُھ خداوند تِم ژے برونہہ کُن کٔڑِتھ کٔڈِتھ۔\n5.\\tنہ تہنزِ نیکی خٲطرٕ، تہٕ نہ پننہِ دِلہٕ چہِ پاکیزگی خٲطرٕ، تہٕ چُھہ تِہٕندِس زمینس پیٹھ قبضہ کرنہٕ خٲطرٕ گژھُن، بلکہ یِمن قومن ہٕنزِ بدکٲری کِنۍ چُھ خداوند تُہند خدا تِمن پانس برونہہ کُن کٔڑِتھ ژٔلِتھ تہٕ سُہ کرِ سُہ کلام پورٕ کرنہٕ یُس خداوند تُہٕندِس مٲلِس ابراہیم، اسحاق تہٕ یعقوب سٍتـ̡ حلف دِوان چُھ۔\n6. تێمہِ کِنۍ سمجھ زِ خداوند تُہند خدا چُھہ نہٕ یہِ اصل زمین دِوان یُس تُہنزِ نیکی خٲطرٕ حٲصل کرنہٕ خٲطرٕ چُھہ یہِ رٔٹِتھ دِوان۔ تِکیازِ تُہۍ چھِو اَکھ سخت لُکھ ۔\n7. یاد تھاوُن، {تہٕ} مٔشِد گژھُن، کِتھہ کٔنۍ کٔرِو ژے خداوند پنُن خدایہ بیابانس مَنٛز غصہٕ دِنہٕ خٲطرٕ: ییمہِ دۅہہٕ ژے مصرٕکہِ سرزمینہٕ منزٕ نیرِتھ نیرِو، یێتھ تام تہٕ یێتھ جایہِ وٲتِو، تێہہ چُھہ خداوند سٕندِس خلاف بغاوت کٔرمٕژ۔\n8.\\tحوربس منز تہِ کٔر یێلہِ خداوند سُند شرارت تہٕ یێلہِ خداوند ژے ژےٚ ژےٚ تباہ کٔرِتھ ژےٚ ژے سٍتـ̡ شرارت کٔرِتھ۔\n9. ییلہ بہٕ کنہِ ہٕندِس میزس رٔٹنہٕ خٲطرٕ پہاڑس پیٹھ کھسنہٕ آمُت، یُس خداوند سٕندِ سٍتـ̡ تہِ کورمُت اوس، تێلہِ بہٕ کُنہِ پہاڑس مَنٛز ژتٲجی دۅہن تہٕ ژتٲجی رٲژ روزُن، بہٕ کٔر نہ روٹی کھیوٚو تہٕ نہ آب چیوٚمُت:\n10. تہٕ خداوند دِژ مےٚ خدایہ سٕنزِ اونگجہِ سٍتـ̡ لیکھِتھ زٕ کٔنـ̡ کٔنـ̡ دِنہٕ۔ تہٕ تِمن پیٹھ اوس {لیکھنہٕ آمُت} سارِنٕے لفظو مطٲبق، یُس خداوند ژےٚ سٍتـ̡ مجلسہٕ کِس دۅہہٕ نارس منزٕ پہاڑس مَنٛز کتھ کٔرمٕژ۔\n11. تہٕ یہِ سپُد ژتٲجی دۅہہٕ تہٕ ژتٲجی رٲژ ہٕندِس ٲخرس پیٹھ، {یہ} خداوند دِژ مے کٔنِس زٕ تختہٕ، {حتیٰ کہ} عہد کِس میزس تہِ۔\n12.\\tتہٕ خداوند ووٚن میہ زِ وۅتھ، وۅتھ، یێلہِ پٲٹھـ̡ وُچھِتھ وُچھِو۔ تِکیازِ تُہٕندِس لُکہٕ سٍتـ̡ یُس ژے مصرہٕ منزٕ نیبر کڈِمُت چُھ، تِمو چُھہ پانس سٍتـ̡ فساد کٔرِم تِم چھِ جلدٕے وتہِ نِش پھیران یُس مےٚ تِمن حُکُم اوس دِتمُت۔ تِمو چھِ تِم اکھ پگھلِتھ تصویر بنٲومٕژ۔\n13. اَمہِ علاوٕ چُھہ خداوند میہ سٍتـ̡ وُچھمُت، تہٕ وُچھِتھ چُھہ یِم لُکھ وُچھمُت:\n14. بہٕ تراوٕ تِمن تباہ کٔرِتھ، تہٕ تِہُند ناو مِٹٲوِتھ تہٕ بہٕ بناوٕ تِمن ہٕندِ کھۅتہٕ بٔڈ قوم۔\n15.\\tتہ بہٕ ووت پہاڑ پیٹھٕ بۄن، تہٕ پہاڑ دٔزِتھ دٔزِتھ تہٕ میھدٕکۍ زٕ میز ٲسۍ میانین دۅن اتھن منز۔\n16. تہٕ میہ وُچھ تہٕ وُچھمُت چُھہ تۅہہِ پۯاوُن بَچھرٕ بَناوُن، یُس خداوند سُند حُکُم اوس دِژمُت۔\n17.\\tتہٕ مے رٔٹۍ زٕ میز، تہٕ کٔرِن پننیو دۅیو اتھو منز، تہٕ ژےٚ أچھن برونہہ کُن بریک۔\n18. تہٕ بہٕ پیوٚو خداوند سٕندِس برونہہ کُن، یِتھ کٔنۍ گۅڈنِچہِ ژتٲجی دۅہہٕ تہٕ ژتٲجی رٲژ پٲٹھۍ، بہٕ کٔر نہٕ روٹی تہٕ نہ آب چیوٚمُت، تِکیازِ تۅہہ کٔر تِمن سارِنٕے گۅناہو سٍتـ̡ یُس تۅہہ خداوند سٕندِس نظرس مَنٛز بدکار کٔرِتھ تہٕ تس شرارت دِنہٕ مۅکھہٕ گۅنہٕ کٔرۍ۔\n19. کیازِ بہٕ اوسُس شَرارتہٕ تہٕ گرم ناراضگی سٍتـ̡ کھوژان، یێمہِ سٍتـ̡ خداوند ژے ژے تباہ کرنہٕ خٲطرٕ غصہٕ دِژمُت۔ مگر خداوند کٔر تمہِ وِزِ تہِ بوز۔\n20. تہٕ خداوند اوس ہارونس سٍتـ̡ سٮ۪ٹھاہ شَرارتہٕ زِ یێمہِ سٍتـ̡ کٔر ہارون سٕندِ خٲطرٕ تہِ دُعا۔\n21.\\tتہٕ میہ نِش تُہند گۅناہ یُس ژے بَنوومُت اوس، تہٕ زٲلِتھ دِژُن نارٕ سٍتـ̡ تہٕ تھپھ کٔرِتھ تھپھ کٔرِتھ، تہٕ میہ ترووُن اَمیُک غبار تتھ نالہِ مَنٛز یُس بالہٕ پیٹھٕ وسان اوس۔\n22.\\tتہٕ عبرہ تہٕ مساہس مَنٛز، تہٕ کِبروتھتاواہ ہس مَنٛز، تم کٔر خداوند سُند غصہٕ دِنہٕ۔\n23. یِتھے پٲٹھۍ ییلہ خداوند ژےٚ کادیشبرنیا پٮ۪ٹھٕ سوزمُت چھُ، یُس مےٚ دِژمُت چھُ، سُہ زمینہٕ حٲصِل کرُن یُس مےٚ دِژمُت چھُ۔ تێلہِ کٔر تۅہہ خداوند پننِس خدایہ سٕندِس حُکمس خلاف بغاوت، تہٕ تێہہ کٔر نہٕ تس پیٹھ یقین تہٕ نہ کٔرٕکھ تٔمۍ سٕنز آواز۔\n24. یێلہِ دۅہہ چُھہ میہ ژے زانان چُھہ تێلہِ چُھہ خداوند سٍتـ̡ بغاوت کٔرمٕژ۔\n25. یِتھٕ پٲٹھۍ پیوٚو بہٕ خداوند سٕندِس برونہہ کُن ژتٲجی دۅہ تہٕ ژتٲجی رٲژ پیوٚو، یِتھٕ پٲٹھۍ بہٕ پیوٚو {گۄڈنِکِس وِزِ}۔ کیازِکہِ خداوند اوس ووٚنمُت زِ سُہ کرِ تۅہہِ برباد۔\n26. تێمہِ کِنۍ کٔر میہ خداوند سٕندِ دُعا تہٕ وونُن، اے خدایہ، پَنٕنـ̡ لوکـ̡ تہٕ پنُن وَراثت، یُس ژے پننہِ عظمتٕ سٍتـ̡ نجات دِژمُت چُھ، یُس ژے طاقتور اتھہٕ سٍتـ̡ مصرہٕ منزٕ نیبر کڈنہٕ آمُت چُھ۔\n27. پَنٕنـ̡ خادم، ابراہیم، اسحاق تہٕ یعقوب یاد تھاوُن۔ یِمن لُکن ہٕنزِ ضد کُن تہٕ نہ تِہٕنزِ بدکٲری کُن تہٕ تِہٕندِس گۅنہٕ کُن وُچھِو۔\n28.\\tیێلہِ سٍتـ̡ یێلہِ تہِ ژے اسہِ نِش دِژمُت چھُ، تێلہِ ہیوٚک نہٕ تِم تِمن زمینس مَنٛز أنِتھ یُس تٔمِس سٍتـ̡ تِمن سٍتـ̡ وعدٕ کورمُت اوس، تہٕ کیازِ تٔمِس اوس تِمن سٍتـ̡ نفرت، تِمن ہٕندِس بیابانس مَنٛز مارنہٕ خٲطرٕ أنِتھ ہیوٚک نہٕ۔\n29. توتہِ چھِ تِم تُہٕندِ لُکھ تہٕ تُہٕندِ وَرثہٕ، یُس ژے پنہٕ نِس طاقتور طاقتہٕ سٍتـ̡ تہٕ پننہِ بٔڑِتھ نٔرِ سٍتـ̡ حٲصِل کٔرِتھ دِژمُت۔","1.\\tتمہِ وِزِ ووٚن رب میہ زِ ژے کٔرِو گۅڈنِکِس پٲٹھـ̡ زٕ کٔنـ̡ کٔنـ̡ تہٕ کٔرِو میانہِ نِش پہاڑس مَنٛز، تہٕ بَنوو ژے لٔکرِ ہُند صندوق۔\n2. تہٕ بہٕ لیکھہٕ میزن پیٹھ تِم لفظ یِم گۄڈنِکِس میزس مَنٛز ٲسۍ، یِم ژے ژے پھُٹرٲوِتھ چھِ، تہٕ ژے تھاوِ تِم صندوقس مَنٛز۔\n3.\\tتہٕ میہ بنوو شِٹِم لٔکرِ ہُند اکھ صندوق، تہٕ کٔرٕن گۄڈنِکِس پٲٹھۍزٕ کٔنہِ ہٕندۍ زٕ میز ژٔٹِتھ تہٕ تھوٚد پہاڑس پیٹھ، یِم زٕ میز میٲنس اتھس منز ٲسۍ۔\n4. تہٕ تٔمۍ لیکھۍ میزن پیٹھ، گۄڈنِکِس تحریرس مطٲبق، داہ حکم، یِم خداوند ژےٚ مجلسہٕ کِس دۅہہٕ نارس منزٕ پہاڑس مَنٛز دِژمٕتۍ، تہٕ خداوند دِژ مے دِنہٕ۔ {حکم: حب۔ لفظ}\n5. تہٕ بہٕ ووت پان پھیُر تہٕ پہاڑہٕ پیٹھٕ بۄن تہٕ تھووُن صندوقس منز میز یُس میہ بنٲومُت اوس۔ تہٕ تتہِ چھِ تِم موجود، یِتھٕ کٔنۍ خداوند مےٚ حُکُم دِیُت۔\n6.\\tتہٕ بنی اسرٲیلِیو کٔر جاکان کین بچن ہٕندِس بیروتھ پیٹھٕ موسیرا تام سفر، تتہِ گۆو ہارون مٔرِتھ تہٕ تتہِ آو سُہ دفن کرنہٕ۔ تہٕ تٔمۍ سُند نیچو الیزارن کٔر تٔمۍ سٕندِ بدلہٕ پادری سٕندِس دفترس مَنٛز خدمت۔\n7. اَتہِ پٮ۪ٹھٕ گٔیہِ تِم گُڈگوڈا کُن سفر۔ تہٕ گُڈگوڈا پٮ۪ٹھٕ جوتباتھ تام، یُس آبٕکۍ دریاوَن ہُند سرزمین۔\n8.\\tتمہِ وِزِ کٔر خداوند سٕندِ عہدُک صندوق رٹنہٕ خٲطرٕ، خداوند سٕندِ برونہہ کُن کھڑا روزُن تہٕ از تام تٔمۍ سٕندِ ناوٕ سٍتـ̡ برکت دِنہٕ خٲطرٕ۔\n9. اَمہِ مۄکھٕ چُھ نہٕ لیوی سٕندِس بٲے سٍتـ̡ کانہہ حصہٕ تہٕ نہ وراثت۔ خداوند چُھ تٔمۍ سُند وراثت، یُس خداوند چُھہ تُہند وعدٕ کوٚرمُت۔\n10.\\tتہٕ بہٕ روٗد پہاڑس منز، گۅڈنچہ لٹہِ ژتٲجی دۅہ تہٕ ژتٲجی رٲژ۔ تہٕ خداوند کٔر میہ تمہِ وِزِ تہِ بوزمُت، {تہٕ}خداوند کرِ نہٕ تۅہہ تباہ کرنہٕ۔ {گۄڈٕنِک...: یا، پٔتِم دۄہ}\n11. تہٕ خداوند ووٚن میہ زِ وۅتھ، لوکن برونہہ کُن گژھ پنُن سفر، یُس میہ پننین مٲلن دِنُک حلف چُھس کٔرمُت۔ {نِیو...: ہیب۔ سفرس منز گژھو}\n12. تہٕ وُن، اسرائیل، خداوند پنُن خدا کیا چُھ تُہٕندِس خداہس سٍتـ̡ تُہٕندِس خداہس سٍتـ̡ ڈرُن، تٔمۍ سٕندِس سارِنٕے وتہٕ سٍتـ̡ پَکُن، تہٕ أمِس سٍتـ̡ محبت کرُن، تہٕ پَنٕنـ̡ دِلہٕ تہٕ سٲرۍسٕے روحہٕ سٍتـ̡ خداوند سٕنز عبادت کرُن،\n13. خداوند سٕندِ حُکمن تہٕ تٔمۍ سٕندِس حکمس پیٹھ عمل کرنہٕ خٲطرٕ، یُس بہٕ از تہٕ تۅہہِ ہٕندِ بھلائی خٲطرٕ حُکُم دِوان چُھ؟\n14. وُچھِو، اسمانُک تہٕ آسمانُک آسُن {چُھ} خداوند سُند خدا، زمین {تہ} تہٕ اتھ مَنٛز موجود سارِنٕے چیزن سٍتـ̡ {چُھ}۔\n15.\\tصرف خداوند اوس تِمن ہٕندِس مٲلس سٍتـ̡ محبت کرنہٕ خٲطرٕ خۅش سپدان، تہٕ تٔمۍ چُھہ تِمن ہٕندِس بُلِس سٍتـ̡ ژٲرمُت، {حتیٰ کہ} تہِ چُھہ تِمن سارِنٕے لُکن پیٹھ، یِتھٕ پٲٹھـ̡ از تہِ چُھ۔\n16. تَمہِ مۄکھٕ کٔرِو پنٕنِس دِلُک ختنہٕ، تہٕ کٔرِو نہٕ سختی کٔرِتھ۔\n17. خداوند تُہند خدا چُھہ خداہَن ہُند خدا، تہٕ خداوَن ہُند خدا، یُس نہٕ شخصن ہُند خیال تھاوان چُھ، تہٕ یُس نہٕ اِنتِظام رٹان چُھ:\n18.\\tسُہ چُھ بے باپ تہٕ بیواہ سُند فیصلہٕ انجام دِوان، تہٕ کھٮ۪ن تہٕ پوشاک دِنہٕ سٍتـ̡ چُھ اجنبی سُند محبت کران۔\n19.\\tتێلہِ کرو اجنبی سٍتـ̡ محبت، تکیازِ تم ٲسِو مصر کِس سرزمینس مَنٛز اجنبی ۔\n20. تُہۍ گژھ پننِس خدایہِ سٕندِس خداہس سٍتـ̡ خوفزدہ گژھُن۔ تٔمۍ سٕنٛز عبادت کٔرٕن، تہٕ تٔمۍ سٕنٛدس ناوٕ سٍتـ̡ کٔرِو قٕسم۔\n21. سُہ چُھہ تُہند تعریف، تہٕ سُہ چُھ تُہند خدا، یٔمۍ تۅہہِ خٲطرٕ یِم بٔڈ تہٕ خوفناک کٲم کٔرۍ، یِم تۅہہِ أچھن وُچھمٕژ چھِ۔\n22.\\tتُہند مول گٔیہِ تریہ تہٕ داہ نفرن سٍتـ̡ مصرس مَنٛز۔ تہٕ وۅنۍ چُھہ خداوند تُہند خدایہ ژے بنوومُت اسمانُک ستارہٕ۔","1. تێمہِ کِنۍ گژھِو تُہۍ خداوند پَنٕنِس خداہس سٍتـ̡ محبت کٔرِتھ، تہٕ تٔمۍ سٕندِس حکمس تہٕ تٔمۍ سٕندِس حکمس تہٕ تٔمۍ سٕندِس حکمس تہٕ تٔمۍ سٕندِس حکمس ہمیشہٕ تھاوُن۔\n2.\\tتہٕ ژیہ زان از دۅہہ: کیازِ {بہٕ چُھس نہٕ پننین شُرین سٍتـ̡ کتھ کران یِم نہٕ زانان آسہِ، تہٕ یِمو نہٕ خداوند تُہندِ خدایہِ سُند عذاب، تٔمۍ سٕنزِ عظمت، تٔمۍ سُند طاقتور اتھ، تہٕ تٔمۍ سٕنزِ پھٔہلِتھ نٔر وُچھمٕژ آسہِ،\n3. تہٕ تٔمۍ سٕندِ معجزات تہٕ تٔمۍ سٕندِ اعمال یُس تٔمۍ مصرس منز فرعونس بادشاہ فرعونس تہٕ تٔمۍ سٕندِس سارِنٕے سرزمینس سٍتـ̡ کٔرۍ۔\n4. تہٕ یُس تٔمۍ مصر کِس فوجس سٍتـ̡ تہٕ تِہندین رتھن سٍتـ̡ کور۔ کِتھہ پٲٹھـ̡ بنیوو بحرِ احمرُک آب یِمن سٍتـ̡ یێلہِ تۅہہِ پَتہٕ پَتہٕ پٲٹھـ̡ تہٕ کِتھہ پٲٹھـ̡ چُھہ خداوند تِم از تام تباہ کورمُت۔\n5.\\tتہٕ یُس تٔمۍ بیابانس مَنٛز ژےٚ سٍتـ̡ کٔر، یوتام تُہۍ یَتھ جایہِ وٲتِو۔\n6.\\tتہٕ یُس تٔمۍ روبن سٕندِس نیچوِس الیاب سٕندِس نیچوِس داتھنس تہٕ ابیرامس سٍتـ̡ کٔر، کِتھہ کٔنۍ کٔر زمینہِ پنُن بوش تہٕ تِمن ہٕندِس گرس تہٕ تِہندِ خیمہ تہٕ سُہ سورُے چیز یُس تِمن ہٕندِس قبضس منز اوس، سارِنٕے اسرٲیلِس منز: {مادہ...: یا یُس تِمن پتہٕ یُس زِندٕ مادہ اوس} {اوس...:  ہیب۔ تہندِس قدمن پیٹھ}\n7. مگر تہنزِ أچھو وُچھمٕژ خداوند سٕندِ سارِنٕے بٔڈ اعمال یِم تٔمۍ کٔرۍ۔\n8. تێمہِ کِنۍ کٔرِو تِم سارِنٕے حُکُم یِم بہٕ ژے از حُکُم دِوان چھِ، یُتھ تہٕ ژے گژھِو مضبوط، تہٕ گژھِو اتھ زمینس پیٹھ قبضہ کٔرِتھ، یێلہِ تہٕ یێلہِ تہِ گژھِو اتھ پیٹھ قبضہ کرنہٕ۔\n9. تہٕ یُس خداوند پننین مٲلن سٍتـ̡ دِنہٕ خٲطرٕ تہٕ تِہندِس بیولس دِنُک قسم چُھ دِژمُت، یُس دۄدٕ تہٕ ماچھ سٍتـ̡ وسان آسہِ۔\n10.\\tتتھ زمینہِ خٲطرٕ، ییتہِ تہِ ژیہ اتھ قبضہ کرنہٕ خٲطرٕ گٔژھِو، سُہ چُھہ نہٕ مصرٕچ زمینہٕ ہٕندۍ پٲٹھۍ، ییتہِ تہٕ ژے پنُن بیول ووومُت، تہٕ پننیو کھۄرٕ سٍتۍ آب دِژُکھ جڑی بوٹین ہٕندِس باغٕکۍ پٲٹھۍ۔\n11.\\tمگر سُہ زمین، ییتہِ تہِ تم اتھ قبضہ کرنہٕ خٲطرٕ گژھِو، {چُھ} بالن تہٕ وادین ہٕنز زمین، {تہٕ} آسمانٕچ روٗدُک آب چیوان چُھ:\n12. سُہ زمین یُس خداوند تُہند خدا چُھہ رٲچھ کران: یێمہِ سٍتـ̡ چُھہ یێمہِ سٍتـ̡ چُھہ یێمہِ سٍتـ̡ {کیرتھ...: ہیب۔ سیکیتھ}\n13. تہٕ یێلہِ تہٕ یێلہِ تێلہِ تێلہِ میانہِ حکمس سٍتـ̡ بوزن، یُس بہٕ از ژے حکم دِوان چُھ، خداوند پنُن خدایہ سٕندِس سٍتـ̡ محبت کرُن، تہٕ پنہٕ نـ̡ دِلہٕ سٍتـ̡ تہٕ سٲرۍسٕے روحہٕ سٍتـ̡ تٔمِس سٍتـ̡ خدمت کرٕنـ̡\n14.\\tیُس بہٕ دِیہ ژے پننہِ زمینہِ ہُند روٗد تٔمِس وقتس منز، گۅڈنیُک روٗد تہٕ دوٚیِم روٗد، یُتھ ژے پنہٕ نِس مَژس مَنٛز تہٕ شراب، تہٕ پنہٕ نِس تیٖلس مَنٛز جمع کٔرِتھ۔\n15. تہٕ بہٕ سوزٕ چانہِ کھہَن مَنٛز گاسہٕ، یُتھ ژٕ کھٮ۪تھ تہٕ پوٗرٕ گٔژھِو۔ {سوز: ہیب۔ دِو}\n16. پَنُن دِل گژھہِ نہٕ دھوکہٕ دِنہٕ، تہٕ یِمن ہٕنزِ پوٗزا کٔرِو تہٕ یِمن ہٕنزِ پوٗزا کٔرِو۔\n17. تہٕ {پتہٕ} خداوند سُند قہر گژھہِ توے سٍتـ̡ دِنہٕ، تہٕ سُہ کرُن اسمانس بند، یُتھ نہٕ روٗد پیٚیہِ، تہٕ زمینہٕ دِیہِ نہٕ پنُن پھل دِنہٕ۔ تہٕ {مُتٲثِر} گژھِو تَمہِ اصل زمینہٕ سٍتـ̡ یُس خداوند ژےٚ دِژمُت چُھ۔\n18. تێمہِ کِنۍ تھاوِو میٲنۍ کلام پننِس دِلس تہٕ پننِس روحس مَنٛز، تہٕ یِم تھٲوِو پننِس اتھس پیٹھ نشانہٕ خٲطرٕ، یُتھ تِم گژھن تُہنزن اچھن درمیان بُتھٕ۔\n19.\\tتہٕ تُہۍ ہیچھناوِو تِمن پنٕنـ̡ شُرۍ، ییلہ تہٕ تُہۍ پَنٕنِس گَرَس مَنٛز بِہِتھ، تہٕ ییلہ تہٕ وَتہِ پکان چُھہ، ییلہ تہٕ وُتھٕ وُتھان چُھہِو۔\n20. تہٕ تُہۍ لیکھِو تِم پننہِ گرٕ کِس دروازس پیٹھ تہٕ پننین دروازن پیٹھ:\n21.\\tیُتھ زِ تُہٕندِس دۅہہٕ گژھن تہٕ تُہٕندٮ۪ن شُرین ہٕندِ دۅہہٕ گٔژھِتھ یُس خداوندٕ تُہٕندِس مٲلِس سٍتـ̡ دِنُک حلف چُھ دِژمُت، یِتھٕ پٲٹھـ̡ زمینس پیٹھ اسمانُک دۅہ دِنہٕ خٲطرٕ۔\n22. یێلہِ تێلہِ تێلہِ یِم سارِنٕے حُکمن ہُند حُکُم یِم بہٕ چُھس حُکُم دِوان چُھہ، یێلہِ تِم کٔرِو تِمن ہٕندِس خداہس سٍتـ̡ محبت کرُن، تٔمۍ سٕنزِ سارِنٕے وتہِ پٲٹھـ̡ پٔکِتھ پٔکِتھ تہٕ أمِس سٍتـ̡ رٔٹِتھ روزُن۔\n23. تیلہِ کٔرِ خداوند یِم سارِنٕے قومن پانس برونہہ کُن ژٔلِتھ تہٕ تۅہہِ ہٕندِ کھۅتہٕ بٔڈ قومن ہٕندِس مٲلِس سٍتـ̡ حٲصِل سپدِ۔\n24.\\tپریتھ جایہ یتھ پیٹھ تۅہہِ کھورِ پکان آسہِ تۅہہِ آسہِ: بیابان تہ لبنان پیٹھ، دریاو فرات، دریائے فرات پیٹھہ تہِ آسہِ تۅہہِ سمندرس تام۔\n25.\\tکانہہ تہِ انسان گژھہِ نہٕ تۅہہِ برونہہ کُن کھڑا گژھِتھ: کیازِ، خداوند تُہند خدا کرِ تۅہہِ سٍتـ̡ خوفہٕ تہٕ خوفہٕ تُہٕندِس سارِنٕے زمینس پیٹھ یێلہِ تۅہہِ پٔکِتھ پۯاوُن، یێلہِ تٔمۍ چُھہ تۅہہِ وَننہٕ آمُت۔\n26. وچھ میہ از دۅہہ ژے برونہہ کنہِ اکھ نعمت تہٕ لعنت مقرر کٔرمٕژ۔\n27. یێلہِ تُہۍ خداوند پنٕنِس خدایہ سٕندِس حُکمن ہٕنز اطاعت کٔرِو، یُس بہٕ ژے از دۅہہ حُکُم کٔرِتھ:\n28.\\tتہٕ اکھ لعنت، یێلہِ نہٕ تۅہہِ خداوند پنُن خدایہ سٕندِس حُکمن ہٕنز فرمانبرداری کٔرِو، مگر یێلہِ بہٕ ژیہ از حُکُم دِوان چُھہ، تتھ وتہِ نِش پھیُرِو یُس نہٕ ژے زانان آسہِ۔\n29. تہٕ یێلہِ یێلہِ خداوند تُہُند خدایہ ژے تتھ زمینس مَنٛز أنِتھ ییتہِ تہٕ تۅہہِ یہ حٲصِل کرنہٕ خٲطرٕ گژھِو، تہٕ ژے کرِ کوہ گریزمس پیٹھ برکت تہٕ ایبال پہاڑس پیٹھ لعنت۔\n30.\\tکیا تِم چُھنہٕ اردن کِس دوٚیمہِ طرفہٕ یُس آفتاب لوسُن چُھ، کنعانین ہٕندِس سرزمینس منز، یُس مورہ کِس میدانس نِش گلگلس خلاف شیمپینس منز روزان چُھ؟\n31. تِکیازِ تُہۍ گژھِو اردن اَپارِ اَتھ زمینس پیٹھ قبضہ کرنہٕ خٲطرٕ یُس خداوند تُہُند خدا دِیُت تہٕ تُہۍ گژھِو اَتھ مَنٛز روزُن۔\n32.\\tتہٕ تُہۍ کٔرِو تِم سٲری قونوٗن تہٕ فیصلہٕ یِم میہ از ژے برونہہ کُن مقرر کٔرۍمٕتۍ۔","1. یِم چھِ تِم قونوٗن تہٕ فیصلہٕ، یِم تُہۍ زمینس مَنٛز کرنہٕ خٲطرٕ عمل کرٕنۍ، یُس تُہٕندِس آباؤ اجدادن ہُند خداوند خدایہ دِوان چُھ، سارِنٕے دۅہہٕ یُس تُہۍ زمینس پیٹھ روزان چھِو۔\n2. تُہۍ کٔرِو تِم سارِنٕے جاے تباہ کٔرِتھ، یِمن مَنٛز تۅہہِ آسہِ تِمن ہٕندِس دیوتاہن ہٕنز خدمت کٔرِتھ، تھدٮ۪ن پہاڑن پیٹھ، بالن پیٹھ، تہٕ پرٮ۪تھ سبز کُلِس تل: {قبضہٕ: یا، وراثت}\n3.\\tتہٕ تِہٕندِ قربان گاہ پھُٹرٲوِو، تہٕ تِہٕندِس گُرِ نار سٍتـ̡ زٲلِو۔ تہٕ تُہۍ کٔرِو تِہٕندٮ۪ن دیوتاہن ہٕنزِ کھٔنِتھ بٔنِتھ تہٕ تِمن ہٕندِس ناو کٔرِو تَتھ جایہِ مَضموٗن۔ {اوور تھرو: ہیب۔ بریک ڈاون}\n4. یۅہے کٔرِو نہٕ خداوند پننِس خداہس سٍتـ̡ یێلہِ تہِ کٔرِتھ۔\n5. مگر تتھ جایہ یُس خداوند تُہند خدا تُہند تمام قبیلو منزٕ ژٲرِتھ تٔمۍ سُند ناو تھاونہٕ خٲطرٕ، تہٕ تتہِ گژھِو تٔمۍ سٕندِس بستی تام تہٕ تتہِ گژھِو۔\n6. تہٕ تَتہِ أنِو پَنٕنۍ زٲلِتھ نذران، تہٕ پنٕنۍ قربانی تہٕ پنٕنۍ دَہٕ، تہٕ پنٕنۍ نذرانہ تہٕ پنٕنۍ کھورِ تہٕ پَنٕنۍ کھورِ ہٕنزِ نذرانہٕ۔\n7. تہٕ تتہِ گژھِو خداوند پنُن خدایہ سٕندِس برونہہ کُن کھٮ۪و، تہٕ تُہۍ کٔرِو تِمن سارِنٕے سارِنٕے چیزس مَنٛز شاد سپدُن، یُس تہٕ تُہٕندِس خداہس سٍتـ̡ چُھہ تُہٕندِس خداہس سٍتـ̡ برکت دِژمُت۔\n8.\\tتم کٔرِو نہٕ تِم {چیز} یُس أسۍ از یتہِ کران چھِ، پرٮ۪تھ کانہہ انسان یُس تہِ پننہِ نظرِ منز صحیح آسہِ۔\n9. تِکیازِ تُہۍ چھِو نہٕ وُنیُک تام باقیَس تہٕ وَرثس کُن آمُت، یُس خداوند تُہُند خدا دِوان چھُ۔\n10. مگر {یێلہِ} تُہۍ اردنس پیٹھ گژھِو، تہٕ تتھ زمینس مَنٛز روزِو یُس خداوند تُہند خدا چُھہ وٲرث دِژمُت، تہٕ {یێلہِ} سُہ چُھہ تُہٕندِس سارِنٕے دُشمنن نِش آرام دِیہِ، یُتھ تُہۍ رٔہِو رٲچھ کٔرِتھ۔\n11. تیلہِ گژھہِ اکھ جاے یُس خداوند تُہند خدا پنُن ناو روزنہٕ خٲطرٕ منتخب کرِ۔ تتہِ أنِو سُہ سُہ یُس بہٕ چُھس حُکُم کَران۔ تُہٕندِ دَزنہٕ آمٕژ نذرانہٕ، تہٕ تُہٕنزِ نذرانہٕ، تہٕ تُہٕندِس سٍتـ̡ چُھہ تُہٕندِس سٍتـ̡ دِنہٕ آمُت، تہٕ تُہٕندِس سارِنٕے ژٲرِس سٍتـ̡ یُس تُہٕندِس خداہس سٍتـ̡ عہد کران چُھہ: {تُہُند انتخاب...: ہیب۔ تہندِ قسمک انتخاب}\n12. تہٕ تُہۍ کٔرِو خداوند پنُن خدا، تہٕ پنٕنۍ نیچوۍ، تہٕ پنٕنۍ کورِ، تہٕ پنٕنۍ خادم، تہٕ پنٕنۍ نوکرۍ، تہٕ لاوی یُس تُہنٛدس دروازس اندر چُھ۔ تکیازِ تس چھہ نہ توے سٍتۍ کانہہ حصہ تہ نہ وراثت۔\n13.\\tپَنُن خیال تھاوُن زِ ژے کٔرِو نہٕ پرٮ۪تھ جایہِ یُس تہِ وُچھِو، پنٕنۍ زٲلِتھ نذرانہ پیش کٔرِتھ:\n14. مگر یُس جایہ خداوند تہندِس قبیلس مَنٛز ژٲرِ، تتہِ کٔرِو پنٕنۍ زٲلِتھ نذرانہ پیش کرنہٕ، تہٕ تتہِ کٔرِو سُہ سُہ یُس بہٕ چُھس حُکُم کٔرِتھ کٔرِتھ۔\n15.\\tیێلہِ تہِ ژے پننین سارنٕے دروازن مَنٛز ماز مارِتھ تہٕ کھٮ۪وُن، یُس تہٕ تُہٕندِس خدایہ سٕنزِ نعمتہٕ مُطٲبِق یُس تٔمۍ تۅہہِ دِژمُت چُھ، ناپاک تہٕ پاک ہیکن اَمہ سٍتـ̡ کھٮ۪ن، یِتھے پٲٹھـ̡ روبُک تہٕ گُرِ ہٕندِس سٍتـ̡ کھٮ۪تھ۔\n16.\\tصرف گژھہِ نہ خون کھیوٚن۔ ژیہ تراوِ یہ زمینس پیٹھ آبکۍ پاٹھۍ تراوُن۔\n17.\\tتوے ہێکہِ نہٕ پنہٕ نِس دروازس اندر پننہِ مکایہِ ہُند حصہٕ، یا شرابُک، یا تیلُک، یا پنہٕ نِس چاروُک یا پنہٕ نِس ریوڑُک دِنہٕ آمُت، تہٕ نہ پنُن کانہہ وعدٕ یُس تُہۍ نِش دِوان چھُ، تہٕ نہ پننہِ مرضی ہُند نذرانہ تہٕ نہ پننہِ اتھہٕ سٍتـ̡ نذرانہ کٔرِتھ:\n18.\\tمگر تۅہہِ پزِ یِم خداوند پننِس خداہس برونہہ کُن کھیوٚن، یُس تُہُند خدا ژٲرِ، تُہُند نیچو تہٕ پنُن کورِ تہٕ پنُن نوکر، تہٕ پننہِ نوکرِ تہٕ لیوی یُس تُہندِ دروازس اندر چُھ، تہٕ یُس تہٕ تُہۍ پَنٕنـ̡ خدایہِ سٕندِس سٍتـ̡ پَنٕنـ̡ پَنٕنـ̡ خدایہِ سٕندِس سٍتـ̡ خوش گٔژھِو۔\n19. پانس سٍتـ̡ ہوشیار روزُن زِ یوتام تُہۍ زمینس پیٹھ روزان چُھہ، تێلہِ گژھہِ نہٕ لاوی تراوُن۔ {یوت تام ...: ہیب۔ سارِنٕے دۅہہ}\n20. یێلہِ خداوند تُہُند خدا تُہٕندِس حِصس بٔڑاوِ، یێلہِ تٔمۍ ژےٚ وعدٕ کورمُت چُھ، تہٕ تہٕ ژٕ ونُن، بہٕ چُھس ماز کھٮ۪وان، کیازِ تُہند روح چُھ ماز کھینُک خواہش۔ ژے ہیکو ماز کھیوٚن، یُس تہِ تُہند روح خواہش کرِ۔\n21. یێلہِ تُہٕندِس خداہِ سُند ناو تھاونہٕ خٲطرٕ یُس جاے ژٲرمُت چُھ، تێلہِ کٔرِو پَنٕنـ̡ پَنٕنـ̡ کھیٚلہٕ تہٕ پَنٕنـ̡ پَنٕنـ̡ کھیٚیہِ یُس خداوند چُھہ ژے دِژمُت، یُس میہ چُھہ حُکُم دِژمُت چُھ، تہٕ یێلہِ تێلہِ چُھہ تُہٕندِس دروازس مَنٛز کھٮ۪وان یُس تُہٕندِس رَفُک حُکُم چُھہ دِژمُت۔\n22.\\tیێتھے پٲٹھـ̡ یێلہِ کُنہِ کُنہِ تہٕ کُنہِ کھٮ۪نہٕ یِنہٕ چُھ، یێتھے پٲٹھـ̡ چُھہ یِمن کھٮ۪نـ̡ تہٕ ناپاک تہٕ پاکیزٕ یِمن ہِوٕے کھٮ۪ن۔\n23.\\tصرف گژھہِ یقینی زِ ژیہ گژھہِ نہ خون، تکیازِ خون چھہ زندگی۔ تہٕ ژے ہیکو نہٕ ماز سٍتۍ زندگی کھٮ۪تھ۔ {be...: Heb. مضبوٗط روٗزِو}\n24.\\tژیہ گژھہِ نہ یہ کھیوٚن۔ ژے تراوُن یہ آبہٕ پٲٹھۍ زمینس پیٹھ۔\n25.\\tژے گژھ نہ یہ کھیوٚن۔ یێلہِ تہٕ تۅہہِ سٍتـ̡ تہٕ تُہٕندِس پَتہٕ پَتہٕ یێلہِ تہٕ یُس خداوند سٕندِس نظرس منز صحیح آسہِ۔\n26. صرف پَنٕنـ̡ مُقدس چیز یُس تہٕ پَنٕنـ̡ عہد کرُن، تہٕ گژھِو تتھ جایہِ یُس خداوند ژٲرِ۔\n27. تہٕ پَنٕنہِ دزنہٕ آمٕژ نذرانہٕ، ماز تہٕ خوُن، خداوند پنُن خدا سٕندِس قربان گاہَس پیٹھ پیش کرنہٕ، تہٕ تُہٕندِس خدایہِ سٕندِس قربان گاہس پیٹھ یِیہِ تُہٕندِس قربان گاہَس پیٹھ تراونہٕ، تہٕ تُہُند ماز کھٮ۪نہٕ۔\n28.\\tیِم سٲری لفظ یِم بہٕ ژے حکم دِوان چھِ، یێلہِ تہٕ تێہہِ پَتہٕ تہندٮ۪ن شُرین سٍتـ̡ ہمیشہٕ خٲطرٕ رٔٹِتھ روزِ، یێلہِ تہٕ یێلہِ تہٕ یُس خداوند پنُن خدایہ سٕندِس نظرس مَنٛز نیک تہٕ صحیح آسہِ۔\n29. یێلہِ خداوند تُہُند خدا تُہٕندِس برونہمہِ نِش قومن ژٹِھہ، یێلہِ تہٕ تُہۍ یِمن ہٕندِس ملکَس مَنٛز روزِو، تہٕ تِمن ہٕندِس سرزمینس مَنٛز روزِو۔ {کامیاب...: ہیب۔ وراثت، یا، تمن پیٹھ قبضہ کرُن}\n30.\\tپَنُن خیال تھاوُن زِ تِمن ہٕندِس پَتہٕ یِنہٕ سٍتـ̡ پھسنہٕ یِنہٕ پتہٕ یِم ژے برونہہ کُن تباہ گٔژھِ۔ تہٕ یہ زِ تُہۍ چھِو نہٕ تِہندین دیوتاہن ہٕنز پرژھہٕ گٲر کٔرِتھ، یِمو قومن کِتھ کٔنۍ ٲسۍ پننین دیوتاہن ہٕنز خدمت کٔرمٕژ؟ بہ تہِ کرِ میہ تہِ۔ {by...: ہیب۔ تمن پتہٕ}\n31. تُہۍ گژھِ نہٕ خداوند پننِس خداہس سٍتـ̡ یِتھ کٔرِتھ، یێمہِ سٍتـ̡ سُہ نفرت چُھ، تِمو کٔرِو پننین خداہَن سٍتـ̡ کرنہٕ۔ تِہندِ نیچوۍ تہٕ کورِ تہِ چھِ تِم پننین دیوتاہن نارس منز زٲلِتھ۔ {کُن: ہیب۔ of the}\n32.\\tیُس تہِ بہٕ چُھس حکم دِوان، سُہ کرُن تہٕ کٔرِو نہٕ اتھ سٍتـ̡ کٔرِتھ تہٕ کٔرِو نہٕ اتھ سٍتـ̡ کٔرِتھ۔","1. اگر تۅہہِ مَنٛز کانہہ پیغمبر یا خوابن ہُند خواب وچھن وول آسہِ، تہٕ تۅہہِ کانہہ نشانی یا معجزہ دِیہِ،\n2.\\tتہٕ سُہ نشانہٕ یا عجائب سپُد، یَتھ مُتلق تٔمۍ ژےٚ وَنُن زِ أسۍ پٔکِو باقٕے دیوتاہن پتہٕ، یِم نہٕ ژے زانان چھِ، تہٕ أسۍ کرو تِمن ہٕنز خدمت۔\n3. تُہۍ پزِ نہٕ تٔمِس پیغمبر سٕندِس کلامَس بوزُن، یا خوابن ہُند خواب وچھن وٲلِس سٕندِس کلامَس سٍتـ̡ بوزُن: یێلہِ خداوند تُہُند خدا چُھہ تُہٕندِس خداہس سٍتـ̡ پَنٕنـ̡ دِلہٕ سٍتـ̡ تہٕ سارِوٕے روحہٕ سٍتـ̡ محبت کران۔\n4. یێمہِ سٕندِس خدایہِ سٕندِس پَتہٕ پٔکِو، تہٕ تٔمِس سٍتـ̡ پٔکِو، تہٕ تٔمِس سٍتـ̡ رٔٹِو، تہٕ تٔمِس سٍتـ̡ رٔٹِو۔\n5.\\tتہٕ سُہ پیغمبر، یا خوابن ہُند خواب وچھن وول گژھہِ مارنہٕ یُن۔ تکیازِ تٔمۍ چُھ کتھ کٔرمٕژ خداوند پنُن خدایہ، یُس تۅہہِ مصرہٕ کِس سرزمینہٕ منزٕ نیبر کڈُن، تہٕ تۅہہِ غلامی ہٕندِس گرٕ نِش نجات دِنہٕ خٲطرٕ، یُس تۅہہِ خدایہِ تُہٕندِس خدایہِ سٍتـ̡ پکنُک حُکُم دِیُتمُت چھُ۔ یێلہِ کٔرِو ژے بُرٕ پانس منزٕ دوٗر کٔرِتھ۔ {پھیرُن...: ہیب۔ خداوند خٕلاف بغاوت}\n6. یێلہِ تُہُند بوے ، تُہٕندِس ماجہِ ہُند نیٚچُو، یا تُہُند نیچو، یا تُہٕنزِ کورِ ، یا تُہٕندِس سٍتـ̡ زنانہٕ، یا تُہُند دوس، یُس تُہٕندِس روحس ہُند پٲٹھـ̡ چُھہ، ژیہ تہٕ تُہٕندِس مٲلِس سٍتـ̡ پٲٹھـ̡ ژٔرِتھ دِنہٕ آمُت۔\n7. {یعنی}، لوکن ہندین دیوتاہن ہند یم تۅہہِ اندۍ پکھۍ چھہِ، تۅہہِ نِش نزدیک، یا ژے نِش دور، زمینہِ ہندِ {اکہ} اندس پیٹھ تہِ زمینہِ ہندس اندس تام۔\n8. تُہۍ گژھ نہٕ أمِس رضامندی دِنہٕ تہٕ نہ بوزُن۔ نہ گژھہِ چانہِ اچھ تس پیٹھ رحم کٔرتھ، نہ گژھہِ نہ ژیہ تس پوشہِ تھاوُن:\n9.\\tمگر ژے کرِ تس مٲرِتھ۔ تُہند اَتھٕ آسہِ أمِس گۄڈٕ أمِس مارنہٕ خٲطرٕ، تہٕ پتہٕ سارِنٕے لُکن ہُند اَتھٕ۔\n10.\\tتہٕ ژے کٔرِو أمِس کَنہِ سٍتـ̡ کٔنہِ سٍتـ̡ کٔرِتھ مَرُن۔ کیازِکہِ تٔمۍ چُھ ژےٚ خداوند پنُن خدایہِ نِش دور کرنٕچ کوشش کٔرمٕژ، یُس ژےٚ مصرٕکہِ سرزمینہٕ منز، غلامی ہٕندِس گرٕ نِش نِش نیبر کڈُن۔ {غلامی: ہیب۔ غلام}\n11. تہٕ سارِنٕے اِسرٲیلِس بوزُن تہٕ خوفہٕ روزُن، تہٕ کُنہِ تہِ کُنہِ تہِ بُرکاری کرٕنـ̡ یُس تۅہہِ مَنٛز آسہِ۔\n12. یێلہِ تہٕ تُہۍ پننِس کُنہِ شہرس مَنٛز بوزِو، یُس خداوند تُہٕندِس خداہن تَتہِ روزنہٕ خٲطرٕ دِژمُت چُھ، تہٕ وَنُن چُھ،\n13. {یقین} انسان ، بِلیال سٕندِ اولاد، ژٔلِتھ تہٕ چُھکھ تِہندِ شہرٕکۍ بسکیٖن دِنہٕ آمٕتۍ، یہِ ؤنِتھ زِ أسۍ گٔژھِو باقین دیوتاہن ہٕنز عبادت کٔرِتھ، یِم نہٕ تۅہہ زانان چھِ۔ {شُرۍ...: یا، شرارتی مرد}\n14.\\tتیلہ کرو پرژھہ گٲر تہٕ تلاش، تہٕ محنت سان پرژھہٕ۔ تہٕ وُچھِو، {اگر یہِ پزر آسہِ}، {تہٕ} کتھ چھِ یقینی زِ {یہ} چھُ یِژھ مکروہ کٲم کرنہٕ آمٕژ۔\n15.\\tژے کٔرِو یٔقیٖنی طور تَمہِ شہرٕکین بسکینن تلوار ہٕندِ کُنہِ سٍتـ̡ تہٕ اَتھ مَنٛز موجود سارِنٕے چیزن تہٕ تَمہِ سٕندِس چارواین تلوار ہٕندِس کنارٕ سٍتـ̡ تباہ کٔرِتھ۔\n16. تہٕ تُہۍ کرو اَمہِ کِس سٲرِسٕے غُنیمت سٍتـ̡ اَمہِ کِس سڑکہِ مَنٛز، تہٕ یێمہِ سٍتـ̡ سارِوٕے لُٹنہٕ سٍتـ̡ زٲلِتھ تہٕ یێمہِ سٍتـ̡ یێلہِ ہُند خدایہِ سٕندِ خٲطرٕ، تہٕ یہِ روزِ ہمیشہٕ خٲطرٕ اکھ ڈھیر۔ یہٕ ییہٕ نہٕ دوبارٕ تعمیر کرنہٕ۔\n17.\\tتہٕ یێلہِ تہٕ یێلہِ نہٕ تُہٕندِس اَتھَس سٍتـ̡ کانہہ تہِ لُطفہٕ دِنہٕ، یُتھ خداوند پنہٕ نِس غصہٕ سٍتـ̡ ژٔٹِھتھ تہٕ تۅہہِ کرِ رحم تہٕ تۅہہِ سٍتـ̡ رحم کرُن، تہٕ تۅہہِ کرِ تُہٕندِس مٲلِس سٍتـ̡ قسم۔ {لعنت: یا، وقف کرنہٕ}\n18.\\tیێلہِ تێلہِ گژھہِ خداوند پنُن خدایہ سٕنزِ آواز بوزُن، تٔمۍ سٕندِس سارِنٕے حُکمن ہٕنز پاسداری کٔرِتھ یُس بہٕ ژے از دۅہہ حکم دِوان چُھ، تێلہِ کرُن یُس خداوند پنُن خدایہ سٕندِ نظرِ منز صحیح چُھ۔","1. تُہۍ چھِو خداوند پنٕنِس خدایہ سٕندِ شُرۍ: تہٕ ژٔٹِو نہٕ پَنٕنـ̡ مُردٕ سٕندِ خٲطرٕ کُنہِ تہِ\n2. تِکیازِ تُہۍ چُھہ خداوند پنُن خدایہ سٕندِ خٲطرٕ اکھ مقدس لُکھ تہٕ خداوند چُھہ ژےٚ پانس خٲطرٕ اکھ خاص قوم بننہٕ خٲطرٕ منتخب کورمُت، یُس زمینس پیٹھ موجود سارِنٕے قومن پیٹھ۔\n3.\\tژے گژھ نہ کانہہ مکروہ چیز کھیوٚن۔\n4. یِم جانور یِم تُہۍ کھٮ۪وان چھِو: بیل، کٹہٕ تہٕ ژھاوٕل،\n5. ہارٹ، تہٕ روبک، تہٕ کُلہٕ ہِرُن، تہٕ جنگلی ژھاوٕل، تہٕ پِگرگ، تہٕ جنگلی داند تہٕ چاموئیس۔ {pygarg: یا bison: Heb. ڈِشَن}\n6.\\tتہٕ پرٮ۪تھ کانہہ جانور یُس کھُر پھٔٹِتھ ژ\n7. توتہِ گژھِ نہٕ یِم کھٮ۪وان یِم کھٮ۪وان چھِ، یا یِمن ہُند کھُر پھٔٹِتھ چھُ۔ ﴿یِتھٕ کٔنِتھ} اونٹ، تہٕ خرگوش تہٕ کُنی: تِکیازِ تِم چھِ کۅکر چٮ۪وان، مگر کھُر چھُنہٕ تقسیم کران۔ {لہذا} تِم چِھ تۅہہِ خٲطرٕ ناپاک ۔\n8.\\tتہٕ سور، کیازِ یہِ کھُر چُھہ پھیُر، توتہِ چُھہ نہٕ کھورٕ چُھہ، یہِ چُھہ نہٕ تۅہہِ خٲطرٕ ناپاک تہٕ تِہُند ماز کھٮ۪وان تہٕ تِہٕندِس مٔرِتھ لاشہٕ سٍتـ̡ اَتھٕ لاگُن۔\n9.\\tیِم چُھہ آبس مَنٛز کھٮ۪نہٕ یِنہٕ وٲلِس سٍتـ̡ کھٮ۪وان یُس پَکھہٕ تہٕ پَکھہٕ چُھہ سُہ کھٮ۪وُن:\n10. تہٕ یُس نہٕ پکھہٕ تہٕ پکھہٕ آسہِ نہٕ تۅہہ کھٮ۪تھ۔ یہِ چھُ تۅہہِ خٲطرٕ ناپاک۔\n11.\\tسارِنٕے صاف جاناوارن ہُند کھٮ۪نہٕ یُن۔\n12.\\tمگر یِم {تِم} چھِہ یِمن منز نہٕ تۅہہ کھٮ۪نہٕ یِوان: گُر، تہٕ اوسیفریج، تہٕ اوسپرے،\n13.\\tتہٕ گُرِ تہٕ گاڈٕ تہٕ گُرٕ تہٕ گُرٕ\n14. تہٕ پرٮ۪تھ کۅکر پننہِ قسمہ پتہٕ،\n15.\\tراتہٕ مۄغل تہٕ رٲژ ہُند باز، تہٕ کۅکر تہٕ باز تہٕ باز،\n16.\\tلۄکُٹ راتہٕ مۄغل، تہٕ بٔڈ راتہٕ مۄغل، تہٕ ہنس\n17. تہٕ پیلیکن، تہٕ گِیر عقاب تہٕ کورمورنٹ،\n18.\\tتہٕ سارِوٕے تہٕ بٔرۍ، تہٕ لۅتہٕ تہٕ کۅکر۔\n19.\\tتہٕ یُس پرٮ۪تھ کانہہ چیز یُس وُڑان چُھ، سُہ گژھِ نہٕ کھٮ۪نہٕ یُن۔\n20. {مگر} سارِنٕے صاف جاناوارن ہٕندِ کھٮ۪نہٕ خٲطرٕ۔\n21.\\tیُس کانہہ تہِ چیز یُس پانس سٍتـ̡ مران چُھہ، تہٕ ژے دِیُن تُہٕندِس دروازس مَنٛز موجود اجنبی شخصس دِنہٕ، یُس سُہ کھٮ۪نہٕ ییہِ۔ نتہٕ ہیکِو یہِ أکِس اجنبی سٕندِس کٕنِتھ: تِکیازِ تُہۍ چھِو خداوند پنٕنِس خداہٕ سٕندِ خٲطرٕ مُقدس لُکھ ۔ ژے گژھ نہ ماجہ ہٕندِس دۄدس منز شُر وُچھُن۔\n22.\\tژے کٔرِو پٔزۍ پٲٹھـ̡ پَنٕنـ̡ سٍتـ̡ پۯاوُن، یُس کھہٕ ؤری پتہٕ ؤری وادٕ دِیہِ۔\n23. تہٕ یێلہِ چُھہ تُہٕندِس خداہس سٍتـ̡ کھٮ۪وان یُس سُہ پنُن ناو تھاونہٕ خٲطرٕ منتخب کرِ، تُہٕندِس مَنُک تہٕ تُہٕندِس تیٖلُک تہٕ پَنٕنـ̡ گاوُن تہٕ پَنٕنـ̡ پۯاوٕنـ̡ پى۪ٹھ۔ یُتھ زن تُہۍ ہێکہِ ہمیشہٕ پننِس خداہس سٍتـ̡ خوف کرُن ہیٚچھِو۔\n24. تہٕ اگر وَتھ ژےٚ خٲطرٕ زیادٕ زیچھر آسہِ، تہٕ تُہۍ ہیوٚک نہٕ یہِ تُلِتھ ہێکان۔ {یا} یێلہِ یێلہِ تۅہہِ نِش واریاہ دوٗر آسہِ، یێلہِ خداوند تُہُند خدا چُھہ تتہِ پنُن ناو تھاوُن، یێلہِ خداوند تُہند خدایہ چُھہ تۅہہِ برکت دِژمُت:\n25. تیلہِ گژھ ژے پونسہٕ بٔنِتھ، تہٕ پونسہٕ پانس اتھس منز رٔٹِتھ تہٕ گژھ تتھ جایہِ تام یُس خداوند تُہند خدا ژٲرِ۔\n26. تہٕ تُہۍ دِیُن یہِ پونسہٕ یُس تہٕ تُہٕندِس رَسٕندِس مَنٛز چُھ، یُس تہٕ تُہٕندِس دَرٕ سٍتـ̡ چُھہ دِیُن، تہٕ یێلہِ تہٕ تُہٕندِس گَرٕ سٍتـ̡ چُھہ یێلہِ تہٕ یێلہِ تہٕ یێمہِ سٍتـ̡ تُہٕندِس خداہس سٍتـ̡ کھٮ۪وان چُھ، تہٕ تُہٕندِس گَرٕ سٍتـ̡ چُھہ یێلہِ تہٕ یێلہِ تہٕ تُہٕندِس گَرٕ سٍتـ̡ خۅش گٔژھِو۔ ژے پرژھان}\n27. تہٕ سُہ لاوی یُس تہندِس دروازس اندر چُھہ؛ ژے گژھ نہٕ تس تراوُن۔ تِکیازِ أمِس چُھنہٕ تۅہہِ سٍتـ̡ کانہہ حصہٕ تہٕ وراثت۔\n28.\\tتریہ ؤری سپدِتھ گژھہِ تۅہہ امی ؤریس منز پنُن سارِوٕے حصہٕ نیبر نیرُن، تہٕ یُس پنہٕ نِس دروازس اندر تھاوُن:\n29.\\tتہٕ لاوی، (تکیازِ أمس چُھنہٕ تۅہہِ سٍتـ̡ کانہہ حصہ تہٕ وراثت) تہٕ اجنبی تہٕ بے باپ، تہٕ بیواہ یُس تہندِس دروازس اندر چُھہ، یِن یِن تہٕ کھین تہٕ تسٕندِس سٍتـ̡ تسٕندِس سٍتـ̡ چُھہ تسٕندِس سٍتـ̡ تہٕ بێواہ بێیہِ تہٕ بێواہ یِن تہٕ کھین تہٕ تسٕندِس سٍتـ̡ تسٕندِس سٍتـ̡ پى۪ٹھ۔ یُتھ خداوند تُہند خدا کرِ تۅہہِ پننہِ اتھہٕ کِس سارِنٕے کامہِ مَنٛز برکت دِنہٕ۔","1. پرٮ۪تھ سَتھ ؤری سپدِتھ گژھِ ژے رِلہٕ تراوُن۔\n2.\\tتہٕ یِہ چُھہ رہائی ہُند طریقہٕ: پرٮ۪تھ کانہہ قرض دِنہٕ وول یُس پننِس ہمساین دِیہِ سُہ گژھِ یلہٕ تراوُن۔ سُہ گژھِ نہٕ پننِس ہمساین یا پننِس بٲیِس سٍتۍ وابستہٕ۔ تکیازِ اتھ چھہ لارڈس ریلیز ونان۔ {قرض دہندگان: ہیب۔ پنن اتھہ دِنُک مالک}\n3. أکِس غیر ملکی سٍتـ̡ ہیکو ژے {یہٕ دوبارٕ} حٲصل کٔرِتھ: مگر {یہ} یُس تُہٕندِس بٲے سٍتـ̡ چُھہ تُہٕندِس اتھس سٍتـ̡ یلہٕ تراوُن۔\n4. یێلہِ تہِ آسہِ نہٕ تۅہہِ مَنٛز غریب۔ تکیازِ خداوند کرِ تۅہہِ تتھ زمینس مَنٛز واریاہ برکت یُس خداوند تُہند خدا چُھہ تۅہہِ دِژمُت {یُس تُہند خدا چُھہ تۅہہِ دِژمُت: {بچٲوِو...: یا، تۅہہِ مَنٛز آسہِ نہٕ کانہہ غریب}\n5. صرف یێلہِ تێلہِ تہِ یێلہِ تہٕ یێلہِ تہٕ یِم سارِنٕے حُکمن ہُند عمل کرُن یِم بہٕ ژے از دۅہہ حُکُم دِوان چھِ۔\n6. خداوند سٕندِ خٲطرٕ چُھہ تُہُند خدا چُھہ تۅہہِ سٍتـ̡ برکت دِوان، یێلہِ تٔمۍ سُند وعدٕ کورمُت چُھ، تہٕ تێہہ دِیُن واریہن قومن دِیُن، مگر تێہہ دِیُن نہٕ قرضہٕ۔ تہٕ تُہۍ کٔرِو واریاہن قومن پیٹھ حکومت، مگر تِم کرِ نہٕ تۅہہِ پیٹھ حکومت۔\n7. یێلہِ تہندِس زمینس مَنٛز تُہٕندِس کُنہِ تہِ دروازس مَنٛز تہٕ یُس خداوند تُہند خدا دِوان چُھ، تێلہِ گژھِ نہٕ پَنُن دِل سخٕت کٔرِتھ، تہٕ پَنُن دِل کٔرِو نہٕ پَنٕنِس غریبس نِش اتھہٕ بند۔\n8.\\tمگر توے کٔرِو أمِس کُن پنُن اَتھٕ وُچھُن، تہٕ یُس سُہ یژھہٕ یژھہٕ تٔمِس خٲطرٕ کٲفی دِنہٕ۔\n9. خبردار روزُن زِ تُہٕندِس بدکار دِلس مَنٛز گژھہِ نہٕ کانٛہہ تہِ خیال یُس یہِ ونان چھُ، سٔتِم ؤری، رِہٲیی ہُند ؤری چُھہ اتھس پیٹھ۔ تہٕ تۅہہِ أچھ گٔژھ پننِس غریب بٲیِس سٍتۍ بد کار تہٕ تٔمِس دِژ نہٕ کانہہ تہِ۔ تہٕ سُہ چُھ تۅہہِ خٕلاف خداوند کُن فریاد کران، تہٕ یہِ چُھہ تۅہہِ خٲطرٕ گۅناہ۔ {سونچ: ہیب۔ لفظ} {بدکار: ہیب۔ بیلیال}\n10. یێلہِ تہٕ تێہُند دِل گژھہِ نہٕ دِل دِنہٕ، تێلہِ گژھہِ نہٕ تُہُند دِل دِنہٕ، تێکیازِ یێمہِ کامہِ خٲطرٕ کرِ تُہند خدا تُہٕندِس سارِنٕے کامہِ مَنٛز تہٕ یێلہِ تہٕ تُہٕندِس سارِنٕے کامہِ سٍتـ̡ دِیہِ تۅہہِ سٍتـ̡ برکت دِنہٕ۔\n11. غریبَن ہٕندِ خٲطرٕ روزِ نہٕ زانہہ زمینہٕ نِش نیرُن، تێمہِ مۄکھٕ چُھس بہٕ ژے حُکُم دِوان زِ ژٕ کٔرِو پَنٕنِس بٲیِس خٲطرٕ، پننِس غریبَس تہٕ پننِس مُلکس مَنٛز پَنٕنـ̡ پَنٕنـ̡ اَتھٕ کھولٕنـ̡ ۔\n12. {تہٕ} اگر تُہند بوے ، اکھ عبرانی مرد ، یا اکھ عبرانی زنانہٕ ، تہٕ چُھہ تۅہہِ شیٚن ؤرین خدمت کرنہٕ۔ تیلہ دِیُن سٔتِم ؤریس منز ژے سُہ پانس نِش آزاد کرنہٕ۔\n13.\\tتہٕ ییلہ ژے أمِس پانس نِش آزاد کٔرِتھ، تہٕ گژھ نہٕ سُہ خٲلی نیرُن:\n14. تُہۍ کٔرِو سُہ پننہِ کھورِ منزٕ تہٕ پننہِ فرشہٕ منزٕ تہٕ پننہِ شرابہٕ منزٕ فراخ دِنہٕ۔\n15. تہٕ ژے گژھہِ یاد روزُن زِ تہٕ ژے ٲسٕکھ مصرٕکِس سرزمینس مَنٛز اکھ غلام تہٕ خداوند خداہن کٔر ژے نجات دِژمٕژ، تێمہِ کِنۍ چُھس بہٕ ژے از تام یہِ حُکُم دِوان۔\n16.\\tتہٕ یہِ گژھہِ یێلہِ سُہ ژے وَنُن زِ بہٕ گژھہٕ نہٕ ژے نِش نیرُن۔ تکیازِ سُہ چُھ ژے تہٕ تُہٕندِس گرس سٍتـ̡ محبت کران، کیازِ سُہ چُھہ ژے سٍتـ̡ رژھر؛\n17. تیلہِ گژھہِ تۅہہ تُہٕندِس کنس سٍتـ̡ دروازس تام دِنہٕ، تہٕ سُہ روزِ ہمیشہٕ خٲطرٕ تُہند خادم۔ تہٕ تہٕ پنہٕ نِس نوکرس تہٕ کرٕ تۅہہ یۅہے کٔرِتھ۔\n18.\\tییلہ تہِ ژیہ تس پانس نِش آزاد کٔرِتھ سوزِو، یہ گژھہِ نہ ژیہ مشکل باسان۔ تِکیازِ سُہ چُھہ تۅہہِ سٍتـ̡ شیٚن ؤرین ہٕنزِ خدمتہٕ سٍتـ̡ دۄگنہٕ کرایہٕ دار خدمتگارس لایق، تہٕ خداوند تُہند خدا کرِ تۅہہِ سٍتـ̡ یێلہِ تہٕ تُہٕندِس سارِنٕے سٍتـ̡ دِیہِ تۅہہِ سٍتـ̡ برکت دِنہٕ۔\n19.\\tیُس سارِنٕے گۅڈنچہ نَر یُس تُہٕندِس کھیٚلہٕ سٍتـ̡ تہٕ پنہٕ نِس کھورِ سٍتـ̡ یێلہِ کٔرِو تُہٕندِس خداہس سٍتـ̡ پاک کرنہٕ۔\n20. تُہۍ گژھِو خداوند سٕندِس خداہس برونہہ کُن ؤری پتہٕ ؤری کھٮ۪وان یُس خداوند ژٲرِ، تۅہہِ تہٕ تُہٕندِس گَرَس مَنٛز۔\n21. تہٕ یێلہِ اَتھ مَنٛز کانہہ عیب آسہِ، یێلہِ زن سُہ لوٚنگہٕ آسہِ، یا انہِ آسہِ، تہٕ تێہہ کٔرِو نہٕ سُہ خداوند پننِس خداہٕ سٕندِ خٲطرٕ قربان کرنہٕ۔\n22.\\tژیہ کھیوٚو یہ پننین دروازن منز: ناپاک تہٕ پاک گژھن یہ کھٮ۪ن، یتھے پاٹھۍ گۅپھ تہٕ کۅکرِ ہٕندۍ پٲٹھۍ۔\n23.\\tصرف گژھ نہ امیک خون کھیوٚن۔ ژے تراوُن یہ آبہٕ پٲٹھۍ زمینس پیٹھ۔","1. ابیبُک ریتھ مُطٲبِق تھاوُن تہٕ خداوند پننِس خداہس سٍتـ̡ فسح تھاوُن، کیازِ ابیبِس کِس رٮ۪تس مَنٛز کٔر تُہند خدایہ ژے رٲژ مصرہٕ منزٕ نیبر۔\n2. تێمہِ مۅکھہٕ کٔرِو تُہۍ پَنٕنِس خدایہِ سٕندِس خداہٕ سٕندِس سٍتـ̡ یێلہِ پَنُن ناو تھاونہٕ خٲطرٕ ژٲرِو۔\n3.\\tژیہ کھیوٚو نہ اتھ سٍتۍ خمیر روٹی کھیوٚن۔ سَتھ دۅہہٕ کھیٚیہِ خمیر روٚس روٹی، {حتیٰ کہ} مصیبتٕچ روٹی تہِ۔ تِکیازِ تُہۍ درٛاو جلدی سان مصر کہِ سرزمینہٕ پیٹھٕ نیبر، یُتھ تۅہہِ یاد روزِو سُہ دۅہ ییٚلہِ تُہۍ پننہِ زندگی ہٕندِ سارِنٕے دۅہہٕ مصرٕکہِ سرزمینہٕ منزٕ نیبر نیرِو۔\n4. تہٕ سَتھ دۅہہٕ گژھہِ نہٕ ژے سٍتـ̡ خمیر روٹی وُچھنہٕ۔ یُس ماز ژیہ گۅڈنچہ دۅہہ تہِ قربان کورمُت اوس، سہ گژھہِ سارۍسٕے رٲژ صبحس تام روزُن۔\n5. ژے ہیکو نہٕ پنہٕ نِس کُنہِ تہِ دروازس مَنٛز فسح قربان کٔرِتھ، یُس خداوند تُہند خدا دِوان چُھ: {قربانی: یا مارُن}\n6. مگر تتھ جایہِ یُس خداوند تُہند خدا پنُن ناو تھاونہٕ خٲطرٕ منتخب کرِ، تتہِ کرو تہٕ آفتاب لوسنہٕ وِزِ تہٕ تمہِ موسمس مَنٛز یُس تہٕ تُہۍ مصرہٕ منزٕ نیرِ۔\n7. تہٕ تُہۍ گژھِو تَتھ جایہِ روُزِو تہٕ کھٮ۪وان یُس خداوند تُہُند خدا ژٲرِ، تہٕ صبحٲے پھیرِو، تہٕ پَنٕنٮ۪ن خیمن مَنٛز گژھِو۔\n8. شیٚیہِ دۅہہٕ گژھِ تُہۍ خمیرٕ روٚس روٹی کھٮ۪وان، تہٕ سٔتِمہِ دۅہہٕ گژھہِ خداوند پنٕنِس خداہٕ سٕندِ خٲطرٕ اکھ سنجیدہ مجلس: تَتھ مَنٛز گژھِ نہٕ کانہہ کٲم کٔرِتھ۔ {سنجید...: ہیب۔ پابندی}\n9.\\tسَتھ ہفتہٕ گٔنزراوُن: سَتھ ہفتہٕ گٔنزراوُن شروع کٔرِتھ {یُتھ وقت} ژیہ دٲر دِنہٕ خٲطرٕ شروع کٔرِتھ۔\n10.\\tتہٕ تہٕ کٔرِو ہفتن ہُند عید خداوند پننِس خداہس سٍتـ̡ پننہِ اتھہٕ سٍتـ̡ آزادانہ نذرانہ سٍتـ̡ خراج دِنہٕ سٍتـ̡ ، یُس تُہٕندِس خداہس سٍتـ̡ دِیُن، یُس تُہٕندِس خداہس سٍتـ̡ دِیُن، یُس تُہٕندِس خداہس سٍتـ̡ دِیُن: {اکھ خراج : یا، کافی}\n11. تہٕ گژھ خداوند سٕندِس برونہہ کُن پُنُن خدا، تہٕ پنُن نیچو، تہٕ پنُن خادم، تہٕ پنُن نوکر، تہٕ لیوی یُس تہندِس دروازس اندر چُھ، تہٕ اجنبی تہٕ بے باپ تہٕ بیواہ یُس تُہٕندِس درمِس مَنٛز چُھ، یُس خداوند تُہند خدا چُھ تَتھ جایہِ تھاونہٕ خٲطرٕ منتخب کورمُت۔\n12.\\tتہٕ ژے گژھہِ یاد تھاوُن زِ تہٕ ژٕ ٲسِو مصرس مَنٛز غلام تہٕ یِمن قونونن ہُند عمل کرُن۔\n13.\\tژے کٔرِو سَتَن دۅہن خیمہ ہُند عید مناونہٕ، یێمہِ پَتہٕ ژے پنہٕ نِس مکایہِ تہٕ شرابس مَنٛز جمع کٔرِو: {مکایہ...: ہیب۔ فرش، تہٕ تُہند شراب پریس}\n14. تہٕ ژے گژھ پننہِ دعوتس مَنٛز شاد گژھُن، تہٕ پنُن نیچو، تہٕ پنٕنۍ نوکر، تہٕ پنٕنۍ نوکر، تہٕ لاوی، اجنبی تہٕ بے باپ تہٕ بیواہ یُس تُہندس دروازس اندر چُھ۔\n15. سَتھ دۅہہٕ روزِ تُہۍ خداوند پنُن خدایہ سٕندِ خٲطرٕ اکھ مقدس دعوت یتھ جایہِ خداوند منتخب کرِ، کیازِ خداوند تُہند خدا کرِ تۅہہِ سٲرۍسٕے اضافس مَنٛز تہٕ پننین اتھن ہٕندِس سارِنٕے کامہِ مَنٛز برکت دِنہٕ۔\n16. ؤریس مَنٛز تریہ لٹہِ گژھن تُہند سارِنٕے مرد خداوند تہندِس خداہس برونہہ کُن یُس سُہ ژٲرِتھ کرِ۔ خمیر روٚس روٹی ہٕندِس عیدس منز، تہٕ ہفتن ہٕندِس عیدس منز، تہٕ خیمہ خانن ہٕندِس عیدس منز، تہٕ تِم گژھن نہٕ خداوند سٕندِس برونہہ کُن خٲلی ظٲہر گژھن:\n17. پرٮ۪تھ کانہہ انسان دِیہِ تُہٕندِس خدایہِ سٕنزِ نعمتہٕ مُطٲبِق یُس تٔمۍ تۅہہِ دِژمُت چھُ۔ {as...: Heb. تٔمۍ سٕنٛدِ اَتھٕ کہِ تحفہٕ مطٲبق}\n18.\\tقاضی تہٕ افسر، ژے بناو پننین سارنٕے دروازن مَنٛز، یُس خداوند تُہند خدا چُھہ تُہٕندِس قبیلس مَنٛز دِوان، تہٕ تِم کرِ لوکن ہُند انصاف سٍتـ̡ فٲصلہٕ۔\n19. ژے گژھ نہٕ فیصلہ کٔرِتھ۔ توے گژھِ نہٕ شخصن ہُند احترام کٔرِتھ، تہٕ نہ رٔٹِتھ تحفہٕ، تکیازِ تحفہٕ چُھ دانشمندن ہٕنزِ أچھ انہٕ کٔرِتھ، تہٕ نیکوکارن ہٕندِس کلامَس بگاڑان چھُ۔ {الفاظ: یا، معاملہ}\n20. یُس سراسر انصاف چُھ، یُس تہٕ تُہۍ روزِو تہٕ تُہٕندِس خدایہِ سٕندِ دِنہٕ آمٕژ زمینُک وٲرث حٲصِل کٔرِتھ۔ {یہٕ کُس...: ہیب۔ انصاف، انصاف}\n21.\\tژے کُنہِ تہِ کُلِس ہُند باغ لاگُن، یُس ژے بَناوُن۔\n22.\\tنہ کرِ ژیہ {کنہِ} تصویر بٔنتھ۔ یُس خداوند تُہند خدا نفرت کران چھُ۔ {تصویر: یا، مجسمہ، یا، ستون}","1. ژے گژھ نہٕ خداوند سٕندِ خٲطرٕ پنُن خدایہِ سٕندِ خٲطرٕ قربان کٔرِتھ، یَتھ مَنٛز کانہہ تہِ بد کار آسہِ، {یا} کُنہِ تہِ بد کاری آسہِ، کیازِ یہِ چُھہ خداوند تُہند خدایہ سٕندِ خٲطرٕ مُنفرت۔ {کٹہٕ: یا، ژھاوٕل}\n2. یێلہِ تہندِس دروازس مَنٛز یُس خداوند تُہُند خدا دِوان چُھ، مرد یا زنانہٕ، یێلہِ تُہٕندِس خدایہِ سٕندِس نظرس مَنٛز بد کاری کٔرِمٕژ آسہِ، تٔمِس عہدٕچ خلاف ورزی کٔرِتھ،\n3. تہٕ گۆو تہٕ باقین دیوتاہن ہٕنز خدمت کٔرٕن، تہٕ تِمن ہٕنز پوجا کٔرٕن، آفتاب، یا زونہٕ، یا آسمانٕچ کُنہِ تہِ فوجس سٍتۍ، یُس نہٕ میہ حکم دِتمُت چُھ۔\n4.\\tتہٕ یہِ وَننہٕ یُن، تہٕ ژے بوزمُت تہٕ پرژھہٕ گٲر کٔرِتھ، تہٕ وُچھِو، {یہِ} پٔزِ، {تہٕ} یُس پٲٹھۍ، {یُس} اسرٲیلِس مَنٛز چُھ یِژھ مکروہ سپدان۔\n5. تیلہِ أنِو سُہ مرد یا زنانہٕ، یٔمۍ یہِ بدکار کٲم کٔرمٕژ آسہِ، تہٕ تِمن کٔرِو پَنٕنِس دروازس تام، تہٕ تِمن کٔرِو کَنہِ پٲٹھۍ، یوٚت تام تِم مرنہٕ۔\n6. دۄن گواہَن یا ترٚین گواہَن ہٕندِس زبانہِ سٍتـ̡ یُس موتُک لایق آسہِ، سُہ گژھِ مارنہٕ یُن۔ {مگر} أکِس گواہ سٕندِس ونِس پیٹھ گژھِ نہٕ سُہ مارنہٕ یُن۔\n7. گواہن ہٕندِ اتھہٕ گژھن تس مارنہٕ خٲطرٕ گۅڈٕ تس پیٹھ تہٕ پتہٕ سارنٕے لوکن ہٕندِ اتھہٕ۔ تَمہِ کِنۍ کٔرِو بُرٕ پانَس مَنٛز دوٗر کٔرِتھ۔\n8. یێلہِ تۅہہِ ہٕندِس خٲطرٕ کُنہِ فٲصلس مَنٛز، خونس تہٕ خونس درمِیان ، عرضی تہٕ عرضس درمِیان تہٕ ٹاس تہٕ ٹالَس درمِیان ، تہٕ تُہٕندِس دروازس مَنٛز تنازعہٕ ہُند معاملہٕ پٲدٕ سپدُن، تێلہِ گژھِو تۅہہِ وۅتھٕن، تہٕ تُہٕندِس خدایہ سٕندِس خدایس ژٲرِ۔\n9.\\tتہٕ تُہۍ گژھِو پادٕرَن نِش، تہٕ یِمن دۅہن یِنہٕ وٲلِس قاضس نِش تہٕ پرژھہٕ گٲر کٔرِو۔ تہٕ تِم ہٲوِن ژےٚ فیصلُک سزا:\n10. تہٕ تُہۍ کٔرِو تَمہِ سزاہٕ مُطٲبِق، یُس تِم یُس خداوند ژٲرِتھ ژٲرِ، تہٕ یُس تۅہہِ ہٲوِ۔ تہٕ تُہۍ کرِو تِمن سارِنٕے مُطٲبِق یُس تِم تۄہہِ ونان چھِ:\n11. شریعت کِس جملہٕ مُطٲبق یُس تِم تۅہہِ ہیچھناوٕن، تہٕ یُس فیصلہٕ تۅہہِ وَننہٕ یِن، تُہۍ گژھِ نہٕ تتھ جملس سٍتـ̡ انکار کرُن، یُس تِم دٔچھنِس اتھس سٍتـ̡ تہٕ کھوورِ اتھس سٍتـ̡ دِنہٕ یِن۔\n12. تہٕ یُس انسان یُس بے تکلف سٍتـ̡ کٲم کرِ، تہٕ یُس پادٕرِ سٕندِس خداہس برونہہ کُن خدمت کرنہٕ خٲطرٕ کھڑا آسہِ، یا قاضی سٕندِس سٍتـ̡ سُہ انسان تہِ گژھِ مَرُن، تہٕ ژے کٔرِو اسرٲیلِس نِش بد کار دور کرنہٕ۔ {تہٕ وِل...: ہیب۔ بوزُن نہٕ}\n13.\\tتہٕ سارِنٕے لُکھ گژھن بوزن، تہٕ خوفزدہ گژھن تہٕ زیادٕ کُنہِ تہِ کُنہِ تہِ کٔرِتھ۔\n14. یێلہِ ژے تتھ زمینس مَنٛز وٲتِتھ یُس خداوند تُہند خدا دِژمُت چُھ، تہٕ اَتھ مَنٛز روزِو، تہٕ وَنُن، بہٕ کَرٕ پانس پیٹھ اکھ بادشاہ بَناوُن، یِتھ کٔنۍ سارِنٕے قومن ہٕندۍ پٲٹھۍ۔\n15. تہٕ کُنہِ تہِ پٲٹھـ̡ کُنہِ تہِ پٲٹھـ̡ پانس پیٹھ بادشاہ مقرر کرُن، یُس خداوند تُہند خدا ژٲرِ، {یێلہِ} پنہٕ نِس باین منزٕ کُنہِ تہِ بادشاہ مقرر کٔرِتھ، یُس نہٕ تُہند بٲے آسہِ۔\n16.\\tمگر سُہ کرِ نہ پانس سٍتـ̡ گُرِ ہُند ضرب تہٕ نہ کرِ لوکن مصرس کُن واپس، یوتام سُہ گُرِ ہُند ضرب کرُن: یێلہِ زن خداوند چُھہ تۅہہِ ووٚنمُت، تێلہِ گژھہِ نہٕ یێلہِ یِتھٕ پٲٹھـ̡ واپس۔\n17. سُہ کرِ پانس سٍتـ̡ زنانن ہُند ضرب ، یُتھ نہٕ تٔمۍ سُند دِل پھیرِ، تہٕ نۂ کرِ سُہ پانس سٍتـ̡ رۄپہٕ تہٕ سۄنہٕ سٍتـ̡ زیادٕ بڑاونہٕ۔\n18.\\tتہٕ یێلہِ سُہ پننہِ بادشاہی کِس تختس پیٹھ بِہِتھ، سُہ کرِ أمِس أکِس کتابہِ مَنٛز امہِ شریعتُک اکھ نسخہٕ لیکھِتھ یُس کاہنن ہٕندِس برونہہ کُن آسہِ۔\n19. تہٕ سُہ روزِ أمِس سٍتـ̡ تہٕ سُہ پَنٕنہِ زندگی ہٕندِس سارِنٕے دۅہہٕ پٔرِتھ، یُتھ سُہ خداوند پنہٕ نِس خداہس سٍتـ̡ خوفزدہ کرُن، یێمہِ شریعت تہٕ یِمن قونونن ہٕندِس سارِنٕے کلامَن ہٕندِس سٍتـ̡ رٔٹِتھ روزُن:\n20. یُس نہٕ تٔمۍ سُند دِل پننین باین ہٕندِس کھۅتہٕ تھوٚد تُلِتھ تہٕ سُہ گژھہِ نہٕ حُکمس نِش پھیُرُن، دٔچھُن اتھہٕ کُن، یا کھوورِ طرفہٕ، یُتھ زِ سُہ گژھہِ پننہِ سلطنتس مَنٛز، سُہ تہٕ تٔمۍ سٕندِس شُرِس سٍتـ̡ اِسرٲیلِس مَنٛز۔","1. پادٕرۍ، لیوی سٕندِس سارِنٕے قبیلہٕ سٍتـ̡ گژھِ نہٕ اسرٲیلِس سٍتـ̡ کانہہ حصہٕ تہٕ وراثت: تِم گژھن خداوند سٕندِ نارٕ سٍتـ̡ دِنہٕ آمٕژ نذرانہ تہٕ تٔمۍ سٕندِس وراثتس کھٮ۪ن۔\n2. تێمہِ کِنۍ گژھہِ نہٕ تِمن پننین باین مَنٛز کانہہ وراثت: خداوند چُھہ تِمن ہُند وراثت، یێلہِ تٔمۍ تِمن ووٚنمُت چُھ۔\n3. تہٕ یِہ آسہِ پادٕرۍ سُند حق یُس لُکن ہٕندِ طرفہٕ قربانی دِنہٕ یِن، چاہے سُہ داند آسہِ یا کۅکر۔ تہٕ تِم دِن پادٕرِس پھیپھ، تہٕ زٕ گلہٕ تہٕ ماو دِنہٕ۔\n4.\\tگۅڈنیُک پھل تہِ، پننہِ شرابُک تہٕ تُہٕندِس تیلُک تہٕ پننہِ کۅکرِ ہُند گۅڈنیُک پھل، تہٕ پننہِ کۅکرِ ہُند گۅڈنیُک پھل، تہٕ دِیُن تس دِنہٕ۔\n5. خداوند سٕندِ خٲطرٕ چُھ تُہند خدایہ چُھ سُہ چُھہ تُہندِ سارِنٕے قبیلو منزٕ ژٲرمُت، یُس خداوند سٕندِس ناوس سٍتـ̡ تہٕ تٔمۍ سٕندِس نیٚچوِس ہمیشہٕ خٲطرٕ خدمت کرنہٕ خٲطرٕ کھڑا روزُن۔\n6. تہٕ یێلہِ کانہہ لیوی چُھہ تُہٕندِس دروازس منزٕ سارِنٕے اسرٲیلـ̡ منزٕ یێلہِ سُہ روزُن، تہٕ یێلہِ سُہ سارِنٕے دِنہٕ آمُت چُھ، تہٕ یێلہِ سُہ چُھہ تُہٕندِس سارِنٕے دَرِ سٍتـ̡ تتھ جایہِ یُس خداوند ژٲرِ۔\n7. تیلہِ گژھہِ سُہ خداوند سٕندِس خدایہ سٕندِس ناوس سٍتـ̡ خدمت کرُن، یِتھٕ پٲٹھـ̡ تٔمۍ سٕندِس سارِنٕے بٲے لاوی یِم خداوند سٕندِ برونہہ کنہِ کھڑا چھِ۔\n8.\\tتِمن ہٕندِ کھٮ۪نہٕ خٲطرٕ یِتھۍ حِصہٕ آسٕن، یُس تٔمۍ سٕندِس وٲرِس کٕننہٕ سٍتـ̡ میلہِ۔ {یہ...: ہیب۔ فادرن ہٕنٛز فروخت}\n9. یێلہِ تہٕ یێلہِ تُہٕندِس خدایہِ سٕندِس خدایہِ دِنہٕ آمٕژ زمینس مَنٛز وٲتِو، تێلہِ گژھہِ نہٕ تِمن قومن ہٕندِس مکروہ سٍتـ̡ کرُن ہیچھناوُن۔\n10.\\tیُس نہٕ تۅہہِ منز کانہہ تہِ لبنہٕ یُس پننِس نیچوِس یا کورِ نارس منز نیرِ، {یا} یُس خدایہِ ہُند استعمال کرِ، {یا} وقتُک مُشٲہِدٕ کرُن، یا جادوگر، یا ڈایَل آسہِ،\n11. یا اکھ دلکش، یا واقف روحن سٍتۍ مشیر، یا جادوگر، یا نیکرومینسر۔\n12.\\tیِم سارِنٕے کامہِ سٍتـ̡ چُھہ خداوند سٕندِ خٲطرٕ ناپاک تہٕ یِمو کُنہِ سٍتـ̡ بێیہ\n13. تُہۍ گژھ خداوند پننِس خداہس سٍتـ̡ کامل آسُن۔ {کامل: یا، سید، یا، مخلص}\n14.\\tیِمن قومن ہٕندِس مُطٲبق، یِمن ہٕندِس مُشٲہِدٕ کرن والٮ۪ن تہٕ خدایہِ ہٕندِس خداہس سٍتـ̡ چُھہ نہٕ تۅہہِ سٍتـ̡ دِنہٕ آمُت۔ {قبضہ: یا، وراثت}\n15.\\tخداوند تُہند خدا کرِ توے سٍتـ̡ میانـ̡ پى۪ٹھہٕ پى۪ٹھ، تێہٕندِس بٲے سٍتـ̡ اکھ پیغمبر پٲدٕ کٔرِتھ۔ تٔمِس سٍتـ̡ بوزُن؛\n16. یُس تہٕ ژے یُس تہٕ یُس تہٕ یێلہِ تہٕ یێلہِ تہٕ بہٕ چُھس نہٕ یێمہِ سٍتـ̡ یێمہِ سٍتـ̡ خدایہِ سٕنز آواز بوزٕنـ̡ تہٕ بہٕ چُھس نہٕ یہِ بٔڈ نار وُچھُن، یێلہِ بہٕ چُھس نہٕ مَرُن۔\n17.\\tتہٕ خداوند ووٚن میہ زِ تِمو چُھہ رٔژ پٲٹھـ̡ کتھ کٔرمٕژ۔\n18.\\tبہٕ کٔرٕ تِمن ہٕندِس بٲے منزٕ اکھ پیغمبر تہٕ تٔمۍ سٕندِس ٲسس مَنٛز پنٕنۍ کلام تھٲوِتھ ۔ تہٕ سُہ کرِ تِمن سارِنٕے سٍتـ̡ کتھ یُس بہٕ أمِس حُکُم کرِ۔\n19.\\tتہٕ یُس نہٕ میانہِ کتھِ بوزِ، یُس نہٕ میانہِ ناوٕ سٍتـ̡ بولہِ، بہٕ کرٕ أمِس سٍتـ̡ تٔمِس سٍتـ̡ یێلہِ سٍتـ̡ سٍتـ̡ یێلہِ سٍتـ̡ سٍتـ̡ یێلہِ\n20.\\tمگر پیغمبر، یُس میانہِ ناوٕ سٍتـ̡ کتھ کرنُک خیال کرِ، یُس نہٕ میہ أمس کتھ کرنُک حکم دِتمُت چُھ، یا یُس بیین خداہن ہٕندِس ناوٕ سٍتـ̡ کتھ کرِ، سُہ پیغمبر تہِ گژھہِ مرُن۔\n21. تہٕ یێلہِ ژے پننِس دِلس مَنٛز وَنُن چُھ، أسـ̡ کِتھہٕ پٲٹھـ̡ پٲٹھـ̡ زانہٕ یُس نہٕ خداوند چُھہ وَنـ̡ دِژمُت؟\n22.\\tییلہ کانہہ نبی خداوند سٕندِ ناوٕ سٍتـ̡ کتھ کرِ، یێلہِ سُہ چیز یُس نہٕ خداوند سٕندِ ناوٕ سٍتـ̡ کتھ کرِ، سُہ چُھ نہٕ خداوند سٕندِ ناوٕ سٍتـ̡ کتھ کٔرمٕژ، {مگر} پیغمبرن چُھ سُہ کتھ کٔرمٕژ: تُہۍ گژھِ نہٕ تس سٍتـ̡ خوفہٕ پٲٹھـ̡ کتھ کرٕنـ̡ ۔","1. یێلہِ یێلہِ خداوند تُہٕندِس خداہِ سٕندِس قومن ژٔٹِتھ ژٔٹِتھ چُھہ، یێمہِ سٕنزِ زمینہٕ خداوند تُہٕندِس خداہس دِژ، تہٕ تہٕ تِمن ہٕندِس شہرن مَنٛز تہٕ تِمن ہٕندِس گَھرن مَنٛز روزُن۔ {کامیاب: ہیب۔ وراثت، یا، مالک}\n2. توے کٔرِو پننہِ زمینہِ مَنٛز تریہ شہر الگ الگ یُس خداوند تُہند خدا چُھہ دِژمُت۔\n3. ژٕ کٔرِو پنٕنـ̡ وَتھ تیار، تہٕ کٔرِو پَنٕنـ̡ زمینہٕ کِس بٔٹھِس ترٚین حصن مَنٛز تقسیٖم، یُس خداوند تُہُند خدایہِ چُھہ ژٔلِتھ دِژمُت، یُتھ پرٮ۪تھ کانہہ قاتل ژلہِ تتہِ۔\n4.\\tتہِ چھہ یہ قاتل سُند معاملہ، یُس تتہِ ژلِتھ ژلہِ، یُس زندٕ روزِ، یُس پننِس ہمساین لاعلمی سٍتۍ مارِ، یُس نہٕ تس پتھ کالس منز نفرت کران اوس۔ {منز...: ہیب۔ راتھ پیٹھٕ تریمہِ دۅہہ}\n5.\\tیِتھے پٲٹھۍ ییلہ اکھ انسان پننِس ہمساین سٍتۍ لٔکرِ ژٹنہٕ خٲطرٕ کُلہٕ ژٹنہٕ خٲطرٕ کُلہٕ سٍتۍ ٹاس دِوان چُھ، تہٕ کلہٕ چُھہ کُلہٕ ژٹنہٕ خٲطرٕ کلہٕ ژٹان تہٕ کلہٕ چُھہ ہمساین پیٹھ گاش دِوان، تہٕ سُہ چُھ مران۔ سُہ ژلہِ تِمو منزٕ أکِس شہرس کُن، تہٕ روزِ زندٕ: {ہیڈ: ہیب۔ ششتٕر} {ہیلوے: ہیب۔ لٔکر} {گاش...: ہیب۔ findeth}\n6.\\tخونُک انتقام لینے وول گژھہِ قاتلس پُت، ییلہ زن تٔمۍ سُند دِل گرم آسہِ، تہٕ تس رٔٹِتھ کرُن، کیازِ وتھ چھِ زیٹھ، تہٕ مارِن أمِس ییلہ زن سُہ اوس نہٕ موتس لایق، تکیازِ تس اوس نہٕ پتھ کالس منز أمس نفرت۔ {سلے...: ہیب۔ زندگی منز مارو تمِس مارُن} {منز...: ہیب۔ راتھ پیٹھٕ تریمہِ دۅہہ}\n7. اَمہِ مۄکھٕ چُھس بہٕ ژے حُکُم دِوان زِ ژے کٔرِو پننہِ خٲطرٕ ترےٚ شہر الگ الگ کرنہٕ۔\n8. تہٕ یێلہِ خداوند تُہٕندِس خدایہِ سٍتـ̡ تُہٕندِس بٔٹھِس سٍتـ̡ بٔڈِتھ دِیہِ، یێلہِ تٔمۍ تُہٕندِس مٲلِس سٍتـ̡ دِنُک وعدٕ کورمُت چُھ، تہٕ سُہ سُہ زمین دِیہِ یُس تٔمۍ پننین مٲلن دِنُک وعدٕ کورمُت اوس۔\n9. یێلہِ ژے یِم سارِنٕے حُکُم پوٗرٕ کٔرِتھ، یُس بہٕ از ژے حُکُم دِوان چُھ، یێلہِ تہٕ یێلہِ تہٕ یێلہِ چُھہ تٔمِس خداہس سٍتـ̡ محبت کرُن، تہٕ تٔمۍ سٕنزِ وتہِ پٲٹھـ̡ پٔکِتھ پٔکِنـ̡ ۔ تیلہٕ کٔرِو یِمو ترےٚ علاوٕ پانس خٲطرٕ مزید تریہ شہر شٲمِل:\n10. یُس نہٕ تُہٕندِس سرزمینس مَنٛز بےٚ گناہ خوُن یُس خداوند تُہند خدا دِیُت تہٕ تۅہہِ سٍتـ̡ خوُن گژھہِ دِنہٕ۔\n11.\\tمگر یێلہِ کانہہ انسان پننِس ہمساین سٍتـ̡ نفرت کرِ، تہٕ أمِس پیارس منز روزِ، تہٕ أمِس خلاف کھڑا گژھِ، تہٕ أمِس مارُن تہٕ یِمو منزٕ کُنہِ شہرس مَنٛز ژلِن: {فٲنِش: حب۔ زندگی منز}\n12.\\tتیلہِ سوزِ تٔمۍ سٕندِس شہرٕکۍ زِٹھۍ تہٕ أنِن أمِس تتہِ نِن، تہٕ سُہ کرِ خونُک انتقام کَرن وٲلِس اتھس مَنٛز، یُتھ سُہ مرُن۔\n13.\\tچانہِ اچھ گژھہِ نہ تس پیٹھ رحم کٔرِتھ، مگر ژے کرِ اسرٲیلِس نِش معصوم خونُک گۅناہ ژٹُن، یُتھ ژے رژھرِ۔\n14.\\tتُہۍ ہٹٲوِو نہٕ پَنٕنِس ہمساین ہُند نشان، یُس تِمو پرانہِ زمانہٕ سٍتـ̡ تُہٕندِس وَرستس مَنٛز تھاونہٕ آمُت چھُ، یُس تُہٕندِس خدایہِ سٕندِس زمینس مَنٛز دِنہٕ آمُت چھُ۔\n15.\\tکُنہِ تہِ گناہ کُنہِ تہِ گناہ کِس سٍتـ̡ گژھِ نہٕ أکِس شخصس خلاف کھڑا سپدُن، کُنہِ تہِ گناہ سٍتـ̡ یُس سُہ گناہ کرُن، دۄن گواہَن ہٕندِس زبانس پیٹھ، یا ترٚین گواہَن ہٕندِس زبانہٕ پیٹھ، گژھہِ معاملہٕ قایم کرنہٕ۔\n16.\\tاگر کانہہ جھوٹ گواہ کٲنسہِ شخصس خلاف گوٲہی دِنہٕ خٲطرٕ کھڑا سپدِ۔ {یہ...: یا، پَسُن}\n17. تیلہِ گژھن دۅشوے نفر، یمن درمیان تنازعہ {چُھ}، گژھن خداوند سٕندِس برونہہ کُن، پادٕرین تہٕ قاضین برونہہ کُن، یُس تمن دوہن منز آسہِ۔\n18.\\tتہٕ قاضی گژھن محنتی سان تفتیش کٔرِتھ: تہٕ وُچھِو، {یێلہ} گواہ {بنہ} اپُز گواہ آسہِ، {تہٕ} پننِس بٲیِس خلاف اپُز گوٲہی دِژمٕژ۔\n19. تیلہٕ کٔرِو تٔمِس سٍتـ̡ یِتھٕ پٲٹھۍ تٔمۍ پننِس بٲیِس سٍتـ̡ کورمُت اوس، یێلہِ کٔرِو ژے پانس مَنٛز بُرٕ دوٗر کٔرِتھ۔\n20. یُس باقٕے روزان چُھ، تِم گژھن بوزن، تہٕ خوفہٕ، تہٕ یِمن نہٕ یِتھٕ کُنہِ تہِ بُرٲیی ہُند ارتکاب کَرُن۔\n21. تہٕ تُہٕنٛزِ أچھ گژھِ نہٕ رحم کَرٕنۍ۔ {مگر} زندگی {گژھہِ} زندگی خٲطرٕ، أچھ بدلہٕ أچھ، دندٕ بدلہٕ دند، اتھہٕ بدلہٕ اتھہٕ، کھۄر بدلہٕ کھۄر۔","1. ییلہ تہۍ پننین دشمنن خلاف جنگ کرنہِ نیرِو، تہٕ گُرۍ، تہٕ رتھ وُچھِو، تہٕ پانس کھۅتہٕ زیادٕ لُکھ وُچھِو، تِمن سٍتـ̡ گژھ نہٕ تِمن سٍتـ̡ خوفزدہ گژھُن، کیازِ خداوند چُھہ تُہند خدا چُھہ پانس سٍتـ̡ ، یُس ژے مصر کہِ سرزمینہٕ منزٕ نیبر کڈنہٕ آمُت چُھ۔\n2. تہٕ یێلہِ یێلہِ تُہۍ جنگس نزدیک وٲتِو، پادٕرۍ گژھہِ نِش تہٕ لُکن سٍتـ̡ کتھ کرنہٕ،\n3. تہٕ یِمن وَنُن زِ اے اسرٲیل، یێمہِ دۅہہٕ چُھہ پَنٕنـ̡ دُشمن سٍتـ̡ جنگہٕ کرنہٕ خٲطرٕ، پَنٕنـ̡ دِل گژھ نہٕ بێہوش، خوفہٕ نہٕ تہٕ ہێکہٕ تہٕ یِمن سٍتـ̡ خوفزدہ گژھُن۔ {بے ہوش: ہیب۔ نرم آسُن} {تھرمبل: ہیب۔ جلدی کٔرِو}\n4. خداوند سُہ چُھہ یُس تۅہہِ سٍتـ̡ چُھہ تُہٕندِس دُشمنن خٕلاف لڑنہٕ خٲطرٕ تہٕ تُہٕندِس بچاونہٕ مۅکھہٕ چُھہ تُہٕندِس خداہس سٍتـ̡ نیران۔\n5.\\tتہٕ افسر گژھن لوکن سٍتـ̡ کتھ کٔرِتھ ونُن، کُس انسان چُھہ یُس نۆو مکانہ بنوومُت چُھ، تہٕ یہ چُھنہٕ وقف کورمُت؟ سُہ گژھ تہٕ پننِس گرس واپس گژھُن، نتہٕ سُہ مَرِ جنگس منٛز، تہٕ بیاکھ نفر کرِ یہِ وقف کرنہٕ۔\n6. تہٕ کُس انسان چُھ یٔمۍ انگور باغ ووتمُت تہٕ وُنیُک تام چُھ نہٕ کھیوٚمُت؟ سُہ تہِ گژھ تہٕ پننِس گرس منز واپس، نتہٕ سُہ گژھہِ جنگس منز مرُن، تہٕ بیاکھ نفر کھٮ۪یہِ۔ {کھیوٚن...: ہیب۔ یہ بنیوو عام}\n7. تہٕ کُس مرد چُھ یٔمۍ خانٛدارِنۍ منگنی کٔرمٕژ تہٕ أمِس نِش آسہِ نہٕ؟ سُہ گژھ تہٕ پننس گھرس منٛز واپس، تاکہ سُہ جنگس منٛز مرنہٕ، تہٕ بیاکھ نفر نِیہٕ أمس نِن۔\n8.\\tتہٕ افسر گژھن لُکن سٍتـ̡ کتھ کرنہٕ، تہٕ تِم ونن زِ کُس انسان چُھہ یُس خوفزدہ تہٕ کمزور چُھہ؟ سُہ گژھ تہٕ پننِس گرس منز واپس، نتہٕ گژھہِ تٔمۍ سٕندِس بٲے سُند دِل تہٕ دِل تہِ۔ {بے ہوش: ہیب۔ پگھلُن}\n9. تہٕ یہِ گژھہِ ییلہ افسرن عوامس سٍتۍ کتھ کرنہٕ ختم کرِ، تِم بناوِ فوجن ہٕندِ کپتان لوکن ہٕنز رہنمٲیی کرنہٕ۔ {قیادت کرنہٕ خٲطرٕ...: ہیب۔ عوامس منز روزُن}\n10.\\tییلہ تہۍ کُنہِ شہرس نزدیک وٲتِتھ اتھ خلاف لڑنہٕ خٲطرٕ وٲتِو، تیلہِ کٔرِو اَتھ سٍتـ̡ امنُک اعلان۔\n11. تہٕ یہِ گژھہِ یێلہِ یہِ تۅہہِ امنُک جواب دِیہِ، تہٕ تۅہہِ ہٕندِ خٲطرٕ یلہٕ دِیہِ، تیلہِ گژھہِ یہِ زِ یێلہِ سارِنٕے لُکھ یِم تۅہہِ ہٕندِ خٲطرٕ خراج دِنہٕ یِن، تہٕ تِم گژھن تۅہہِ ہٕنز خدمت۔\n12. تہٕ اگر یہِ نہٕ تۅہہِ سٍتـ̡ صلح کرِ، مگر توے سٍتـ̡ جنگ کرِ، تیلہِ کرِ توے اتھ محاصرٕ:\n13. تہٕ یێلہِ خداوند تُہٕندِس خدایہِ سُہ تُہٕندِس اتھس مَنٛز دِیُو، تێلہِ دِیُو تُہٕندِس پرٮ۪تھ أکِس مردس تلوارِ ہٕندِس دِلہٕ سٍتـ̡ مارُن:\n14.\\tمگر زنانہٕ، لۄکٹۍ، چاروٲے تہٕ شہرس مَنٛز موجود سارِنٕے چیز، تہٕ یێمہِ ہُند سارِوٕے مال تہِ نِیُن پانس نِنـ̡ ۔ تہٕ تُہۍ کھیٚیہِ پَنٕنـ̡ دُشمن ہُند غُلُب، یُس خداوند تُہٕندِس خداہَن دِژمُت چُھ۔ {نِیو: ہیب۔ خراب}\n15.\\tیِتھٕ پٲٹھۍ کٔرِو تِمن سارِنٕے شہرن سٍتـ̡ یِم نہٕ تۅہہِ نِش واریاہ دوٗر چھِ، یِم نہٕ یِمن قومن ہٕندِس شہرس مَنٛز چھِ۔\n16. مگر یِمن لُکن ہٕندِس شہرس منز، یُس خداوند تُہند خدا چُھہ وراثت دِژمُت، تۅہہ ہێکہِ نہٕ کانہہ تہِ زندٕ روزُن یُس شاہ دِوان چُھ:\n17.\\tمگر ژے کٔرِو تِم پوٗرٕ پٲٹھۍ تباہ کرنہٕ۔ {یعنی}، حتی، تہٕ اموری، کنعانی، تہٕ پریزی، حوی تہٕ یبوسی؛ یِتھٕ کٔنۍ خداوند چُھہ تُہٕندِس خدایہِ سُند حُکُم دِژمُت:\n18.\\tزِ تِم ہیچھناوٕنـ̡ تِمن سارِنٕے بد کاریو پتہٕ یُس تِمو پننین دیوتاہن سٍتـ̡ کٔرِمُت چُھ۔ یێلہِ پَزِ تُہۍ خداوند پننِس خداہس خلاف گۅناہ کٔرِو۔\n19.\\tییلہ کُنہِ شہرس واریاہس کالس محاصرہ کرِ، اتھ پیٹھ قبضہ کرنہٕ خٲطرٕ جنگ کٔرِتھ، تِمن خلاف کُلہٕ زبردستی کٔرِتھ گژھِ نہٕ تِمن ہٕندِس کُلِس تباہ کٔرِتھ، تکیازِ تِمن کھٮ۪تھ تہٕ ژٔٹِتھ ژٔٹِتھ تہٕ ژٔٹِتھ یِمن ہٕندِس محاصرس مَنٛز استعمال کرنہٕ مۅکھہٕ:  {امہ خاطرہ...: یا، اے انسان، میدانُک کُل گژھہِ محاصرس منز ورتاوُن} {ملازمت...: ہیب۔ ژے برونہہ کُن گژھُن}\n20. صرف تِم کُلۍ یِم ژے زانان چھِو زِ تِم چھِنہٕ مازٕ خٲطرٕ کُلۍ آسان، تہٕ ژٔٹِتھ ژٔٹِتھ ژٔٹِو۔ تہٕ تُہۍ کٔرِو تتھ شہرس خلاف قلعہ تعمیر یُس توے سٍتۍ جنگ کران چُھ، یوٚت تام نہٕ سُہ زیر گژھِ۔ {یہ...: ہیب۔ یہ آو بۄن}","1. یێلہِ یێلہِ تُہٕندِس خدایہِ سٕندِس زمینس مَنٛز مارنہٕ آمُت یُس تُہُند خدایہِ دِژمُت چُھ، تہٕ یہِ گژھہِ نہٕ معلوم سپدِتھ زِ أمِس کٔمۍ چُھ مارمُت:\n2. تَمہِ پَتہٕ یِن تُہٕندِس زِٹھہٕ تہٕ تُہٕندِس مُقرر سٍتـ̡ یِمن شہرن ہٕنز پیمائش کٔرِتھ یِم مارنہٕ آمٕتِس اندۍ پٔکھۍ چھِ:\n3. تہٕ یہِ گژھہِ یہِ زِ شہرس {یُس} مقتول انسانس سٍتـ̡ چُھ، تَمہِ شہرٕکۍ بزرگ تہِ نِن اکھ گاو، یُس نہٕ کُنہِ تہِ آسہِ۔\n4. تہٕ اَمہِ شہرٕکۍ زِٹھۍ اَنِن گاو أکِس کھرٕ وادی منٛز، یۄسہٕ نہٕ کَن تہٕ وونہٕ آسہِ، تہٕ وادی مَنٛز کٔرِن گاوٕ سٕنزِ گردنہٕ ژٹنہٕ۔\n5. تہٕ پادٕر، لیوی سٕندِ نیچوۍ یِن نزدیک۔ تِہندِ خٲطرٕ چُھ خداوند تُہند خدایہ تٔمِس خدمت کرنہٕ خٲطرٕ تہٕ خداوند سٕندِ ناوٕ سٍتـ̡ برکت دِنہٕ خٲطرٕ منتخب کوٚرمُت۔ تہٕ تِہندِ کلامٕ سٍتـ̡ گژھہِ پرٮ۪تھ کانہہ تنازعہ تہٕ پرٮ۪تھ کانہہ ٹاس {آزماونہٕ}: {لفظ: Heb. ٲس}\n6.\\tتہٕ اَمہِ شہرٕکۍ سارِنٕے بزرگ، یُس مقتول {انسان} سٍتـ̡ آسہِ، وادی مَنٛز کلہٕ ژٹنہٕ آمٕژ گاورس پیٹھ چھلناوُن:\n7. تہٕ تِم دِن جواب تہٕ ونان، سانہِ اتھو چُھ نہٕ یہِ خوُن وُچھمُت، تہٕ نہ چُھہ سانہِ أچھن وُچھمُت۔\n8. اے خداوند، پننِس قومہٕ اسرٲیلِس سٍتـ̡ رحم کرُن، یُس ژے نجات دِژمُت چُھ، تہٕ پَنٕنـ̡ پَنٕنـ̡ بےٚ گناہ خوُن تراوُن نہٕ اِسرٲیلـ̡ سٕندِس سٍتـ̡ ۔ تہٕ یِمن ہُند خون یِیہِ معاف۔ {پننین لوکن تام: ہیب۔ منزۍ بیترِ}\n9. یێلہِ کٔرِو ژے پانس مَنٛز بے گناہ خونُک گُناہ دِنہٕ، یێلہِ تہٕ یێلہِ تہٕ یُس خداوند سٕندِس نظرس منز صحیح آسہِ۔\n10. یێلہِ تہٕ یێلہِ تُہۍ پَنٕنـ̡ دُشمن سٍتـ̡ جنگ کرنہٕ خٲطرٕ نیرِو، تہٕ خداوند چُھہ تِم پننِس اتھس مَنٛز دِژمُت، تہٕ تێہہ چُھہ تِم قٲد کٔرِتھ،\n11. تہٕ وُچھِو قٲدٮ۪ن مَنٛز اَکھ خوٗبصوٗرت زنانہٕ، تہٕ تٔمِس سٍتـ̡ یێلہِ سٍتـ̡ سُہ پنہٕ نِس زنانہٕ سٍتـ̡ حٲصِل کٔرِتھ۔\n12. تیلہٕ اَنُن أمِس گَرٕ پَنٕنِس گَرَس مَنٛز۔ تہٕ سۅ کرِ کلہ کاس، تہٕ کیل ژٹنہِ۔ {پیر: یا، بڑاونہٕ خٲطرٕ: ہیب۔ بناوُن، یا پَلَو}\n13.\\tتہٕ سۅ گژھہِ پننہِ قٲدِ ہُند پوشاک پانس نِش کڈِتھ تہٕ تُہندِس گرس منز روزِ تہٕ پننِس مٲلِس تہٕ ماجہ ہُند پوٗرٕ ریتس ماتم کرُن، تہٕ اَمہِ پتہٕ گژھِو تٔمِس نِش اژُن، تہٕ سُہ بنہِ تٔمۍ سٕنز خانٛدارِنہِ۔\n14.\\tتہٕ یہِ گژھہِ یێلہِ نہٕ أمِس سٍتـ̡ خۅش آسہِ، تیلہِ گژھہِ أمِس ییتہِ یێلہِ تہِ گژھِ۔ مگر ژے کٔرِو نہٕ أمِس پٲنسہٕ خٲطرٕ کٕنُن، تِکیازِ ژے کٔرِو أمِس عاجزی کٔرمٕژ۔\n15. اگر أکِس مردس زٕ خانٛدارِنہِ آسہِ، اکھ محبوب تہٕ بییِس نفرت، تہٕ تِمو آسہِ أمِس بچہٕ پٲدٕ کٔرِتھ، دۄشوے محبوب تہٕ نفرت۔ تہٕ {اگر} گۅڈنیُک نیچو آسہِ أمس سُند یُس نفرت اوس کرنہٕ آمُت:\n16. تیلہِ گژھہِ یێلہِ سُہ پننین نیچوین وٲرث بناوِ، یُس أمس نِش آسہِ، {یُس} سُہ کرِ نہٕ پیاری سُند نیچو نفرتس برونہہ کُن، {یُس پٔزۍ پٲٹھۍ} گۅڈٕ زامُت چُھ:\n17.\\tمگر سُہ کرِ نفرتُک نیچو تسٕندِس سارِنٕے چیزُک دۄگنہٕ حصہٕ دِتھ تسٕندِس طاقتُک آغاز دِتھ۔ گۅڈنچہ اولاد سُند حق چھُ تٔمِس۔ {یہ...: ہیب۔ یُس أمِس نِش لبنہٕ چُھ یِوان}\n18.\\tیێلہِ کٲنسہِ شخصس ضدی تہٕ باغی نیچو آسہِ، یُس نہٕ پننِس مٲلہِ سٕنزِ آوازِ ہُند فرمانبردار آسہِ، تہٕ یێلہِ تِمن ہٕنزِ کتھ بوزِ۔\n19. تیلہِ گژھن تٔمۍ سُند مول تہٕ موج أمِس تھپھ کٔرِتھ، تہٕ أمِس نِن پننِس شہرٕکِس بزرگن نِش تہٕ پننہِ جایہِ کِس دروازس پیٹھ۔\n20. تہٕ تِم وَنَن تٔمۍ سٕندِس شہرٕکِس زِٹھٮ۪ن زِٹھہِ زِ یہِ چُھ سون نیچو ضدی تہٕ باغی، سُہ کرِ نہٕ سانہِ آوازِ ہٕنز فرمانبردار۔ {سُہ} چُھ اکھ لالچ، تہٕ اکھ شرابہٕ۔\n21.\\tتہٕ تٔمۍ سٕندِس شہرٕکۍ سٲری نفر کٔرِن أمِس کَنہِ سٍتـ̡ کٔنہِ سٍتـ̡ سُہ مَرُن، یێلہِ کٔرِو تۅہہ پانس مَنٛز بُردی دوٗر کٔرِتھ۔ تہٕ سارِنٕے اسرٲیلِس بوزُن تہٕ خوف۔\n22. تہٕ یێلہِ کٲنسہِ شخصس موتُک لایق گۅناہ آسہِ، تہٕ سُہ ییہِ مارنہٕ یُن، تہٕ ژے کُلِس پیٹھ پھٲنسی دِیُن:\n23.\\tتٔمۍ سُند لاش گژھہِ نہٕ سارِوٕے رٲژ کُلِس پیٹھ روزُن، مگر تۅہہ کٔرِو سُہ تمہِ دۅہہ کُنہِ تہِ پٲٹھۍ دفن۔ (یُس پھانسی دِنہٕ آمُت چُھ، سُہ چُھ خدایہ سُند لعنت؛) یُس تُہٕنٛز زمین گژھِ نہٕ ناپاک کرنہٕ، یُس خداوند تُہند خدا ژےٚ وراثت دِوان چھُ۔ {لعنت...: ہیب۔ خدایہ سُند لعنت}","1.\\tژے گژھ نہٕ پننِس بٲے سُند بیل یا تٔمۍ سٕندِس کۅکرس گُرِ گٔژھتھ وُچھِتھ تہٕ تِمن نِش ژوٗرِ روزُن، بہرحال تہٕ تِم أنِو پننِس بٲیِس نِش۔\n2. تہٕ اگر نہٕ تُہند بوے تۅہہِ نزدیک آسہِ، یا اگر نہٕ تۅہہ أمِس زانان آسہِ، تیلہِ گژھِو سُہ پننِس گرس منز أنِتھ، تہٕ یہ روزِ توے نِش یوٚت تام تُہند بٲے یہِ ژھانڈِ، تہٕ تۅہہ کرِو یہ دُبارٕ أمِس نِش واپس۔\n3.\\tیتھے پاٹھۍ کرو تمۍ سٕندِس گٔرِس سٍتۍ۔ تہٕ یِتھٕ پٲٹھۍ کٔرِو تٔمۍ سٕندِس لباسس سٍتۍ۔ تہٕ پننِس بٲے سٕندِس سارِنٕے رٲومٕژ چیزس سٍتۍ، یُس أمِس رٲومُت چُھ، تہٕ ژے لٔبِتھ چھُ، تہٕ ژے کٔرِو نہٕ پنُن پان ژوٗرِ روزُن۔\n4.\\tژے گژھ نہ پننس بٲے سُند گٔر یا تٔمۍ سُند داند وتہِ وتہِ وُچھِتھ تہٕ تِمن نِش ژوٗرِ روزُن، تہٕ ژٕ کٔرِو یٔقیٖنی طور أمِس دُبارٕ تُلنس منز مدد۔\n5.\\tزنانہِ گژھہِ نہ مردس سٍتـ̡ پوشاک لاگُن، تہٕ نہ گژھِ مرد زنانہِ ہُند پلو لاگُن، تکیازِ یێلہِ سارِنٕے سٍتـ̡ چُھہ خداوند تُہندِ خداہٕ سٕندِ خٲطرٕ مُنفرت۔\n6.\\tاگر کُنہِ کُلِس یا زمینس پیٹھ وتہِ منز کُنہِ جاناوار سُند گھونسلہ آسہِ، {چاہے تِم بچہٕ آسن، یا ٹھوٗل، تہٕ بچہٕ یا ٹھولن پیٹھ بِہِتھ ڈیم آسہِ، تیلہِ گژھِ نہٕ ژیہ بچہٕ سٍتۍ ڈیم نِن:\n7.\\t{مگر} ژیہ کُنہِ تہِ پٲٹھـ̡ بند تراوُن، تہٕ نِن جوان پانس نِش۔ تاکہ ژے گژھہِ ٹھیٖک روزُن، تہٕ {یُتھ} ژے کرِ پنہٕ نِس دۅہس زیٹھراوُن۔\n8.\\tییلہ ژیہ اکھ نۆو مکانہ بناوِ، تیلہِ بناو پننہِ چھتہِ خٲطرٕ اکھ جنگ، یُتھ زن کانہہ تہِ شخص ییہ تتہِ پیٹھٕ پنہٕ نِس مکانس پیٹھ خون۔\n9. ژٕ گژھ نہٕ پنٕنِس انگور باغس مُختلف بیٲلۍ سٍتـ̡ وونہٕ، یُس ژے ووومُت چُھ، تہٕ پننہِ انگورُک پھل گژھہِ ناپاک کرنہٕ۔ {تُہند پھل: ہیب۔ بیٲلۍ ہُند مکمل آسن}\n10. ژے گژھ نہٕ بیل تہٕ گَرٕ رٔلِتھ ہل کٔرِتھ۔\n11. ژے گژھ نہٕ مختلف قسمک پلو لاگُن، یِتھ کٔنۍ زَن ییرُک تہٕ کُنہِ کُنہِ سٍتـ̡ یکوٹہ لاگُن۔\n12.\\tژے کٔرِکھ ژۅشونی پوشاکَن ہٕندِس ژۅشونی حصس سٍتـ̡ یُس ژے پانس پوشہٕ کٔرِتھ چھُ۔ {کوارٹرز: ہیب۔ ونگس}\n13.\\tاگر کانہہ مرد زنانہِ رٔٹِتھ أمِس نِش گژھِ، تہٕ أمِس سٍتـ̡ نفرت کرِ،\n14.\\tتہٕ أمِس خٕلاف کتھ کرنٕچ موقعہٕ دِیُن، تہٕ أمِس بد ناو تھووُن، تہٕ ونُن، مے رٔٹِتھ یہِ زنانہٕ، تہٕ ییلہ بہٕ أمِس نِش آو، مےٚ وُچھ نہٕ أمِس دٲیر:\n15.\\tتیلہِ گژھن کورِ ہُند مول تہٕ تٔمۍ سٕنزِ موج نِن تہٕ اَننہٕ دروازس پیٹھ شہر کین بزرگن نِش۔\n16.\\tتہٕ کورِ ہُند مول وَنُن زِٹھٮ۪ن زِ مے ٲس پنٕنۍ کوٗر أمِس مردس زنانہٕ دِژمٕژ، تہٕ سُہ چُھ أمِس نفرت۔\n17.\\tتہِ چھہ تمۍ سٍتـ̡ کتھ کرنک موقعہ دِژمُت زِ میہ لٔب نہٕ چانہِ کورِ دٲر۔ تہٕ توتہِ چھِ یِم {میانہِ کورِ ہٕنزِ کنوارپنٕچ نشانہٕ﴾۔ تہٕ تِم پھٔہلٲوِن شہرٕ کین بزرگن برونہہ کُن۔\n18.\\tتہٕ تَمہِ شہرٕکۍ زِٹھۍ نِن أمِس نفرس تہٕ دِیُن أمِس عذاب۔\n19.\\tتہٕ تِم دِن أمِس ہتھ رۄپہٕ رۄپہٕ سٍتـ̡ تہٕ دِیُن لڑکہِ ہٕندِس مٲلِس دِن، تکیازِ تٔمِس چُھ اِسرٲیلٕچ أکِس کنوارِس بد ناو تھوومُت، تہٕ سۅ آسہِ تسٕنزِ زنانہٕ۔ سُہ ہیکہِ نہٕ أمِس سارِنٕے دۅہن دوٗر کٔرِتھ۔\n20.\\tمگر اگر یہ کتھ پزر آسہِ، {تہٕ کنوارِیتک نشانہٕ} گژھن نہٕ لڑکہِ خٲطرٕ لبنہٕ:\n21.\\tتیلہِ أنِن تٔمۍ سٕندِس مٲلہِ سٕندِس گرٕ کِس دروازس کُن تہٕ تٔمۍ سٕندِس شہرٕکۍ مرد کٔرِن أمِس کٔنہِ سٍتـ̡ سُہ مرُن، تکیازِ تٔمۍ کٔر اسرٲیلِس مَنٛز بیوقوفی کٔرمٕژ، یێلہِ کٔرِو تٔمِس مٲلہِ سٕندِس گرس مَنٛز بدکار گٔژھِتھ تہٕ یێلہِ کٔرِو بُرٕ پانس نِش دوٗر کٔرِتھ۔\n22. اگر کانہہ مرد خانٛدرٕ کٔرِتھ زنانہِ سٍتـ̡ لبنہٕ ییہِ، تیلہِ گژھن تم دۅشوے مرُن، یُس مرد تہٕ زنانہِ سٍتـ̡ آسہِ، یێلہِ کٔرِو تُہۍ بُد دِنہٕ یِنہٕ وٲلِس اِسرٲیلِس نِش دوٗر کٔرِتھ۔\n23.\\tیێلہِ کُنہِ خاوندس سٍتـ̡ منگنی کرنہٕ ییہِ، تہٕ اکھ مرد أمِس شہرس مَنٛز لٔبِتھ تہٕ أمِس سٍتـ̡ روزِ۔\n24. تیلہِ أنِو تِم دۅشوے اَمہِ شہرٕ کِس دروازس تام، تہٕ تِمن کٔنہِ کٔرِتھ تہٕ تِم مَرٕنـ̡ ۔ لڑکی ، تکیازِ سۅ ٲس نہ شہرس منز رودمژ، {آسن}۔ تہٕ مرد، تکیازِ تٔمۍ کٔر پننِس ہمساین سٕنزِ زنانہِ عاجز کرنہٕ، تہٕ تۅہہ کٔرِو پانس منزٕ بُرٕ دوٗر کٔرِتھ۔\n25.\\tمگر اگر کانہہ مرد کھاہس منز منگنی واجنہِ لڑکی لبان تہ مرد أمس زبردستی کرِ، تہٕ أمس سٍتۍ روزِ، تیلہِ گژھہِ صرف أمس سٍتۍ روزن وول مرد مرُن: {زبردستی: یا، رٔٹِو مضبوط}\n26.\\tمگر لڑکہِ سٍتـ̡ کرُن نہٕ کانہہ تہِ۔ {لڑکہِ منز چھہ نہ کانہہ گناہ {موت} لایق آسان، تکیازِ ییلہ کانہہ انسان پننس ہمساین خلاف کھڑا سپدان چھہ تہ تس ماران چھہِ، تتھے پاٹھۍ چھہ یہ معاملہ:\n27.\\tتکیازِ أمِس لٔب سۅ کھاہس منز، {تہٕ} منگنی واجنہِ لڑکی کٔر کٔرِتھ تہٕ {اتہِ} اوس نہٕ أمِس بچاونہٕ خٲطرٕ کانٛہہ تہِ۔\n28.\\tاگر کانہہ مرد کُنہِ کُنِہ لٔبِتھ یۅسہٕ نہٕ منگنی آسہِ، تہٕ أمِس رٔٹِتھ روزِ، تہٕ تِم یِن لبنہٕ یِن۔\n29.\\tیُس مرد أمِس سٍتـ̡ روزِ، سُہ دِیہِ أمِس مٲلِس پنٛژاہ رۄپہٕ تہٕ سُہ بنہِ أمِس زنانہٕ۔ کیازِ تٔمۍ چھُ أمِس عاجز کورمُت، سُہ ہیکہِ نہٕ أمِس سارِنٕے دۅہہٕ دوٗر کٔرِتھ۔\n30.\\tمرد گژھِ نہ مٲلۍ سٕنز زنانہٕ نِن، تہٕ نہ گژھِ مٲلہِ سُند سکرٹ دریافت کرُن۔","1. یُس کنن منز زخمی آسہِ، یا تٔمۍ سُند رازدار رُکُن ژٹنہٕ آسہِ، سُہ گژھِ نہٕ خداوند سٕنزِ جماعتس مَنٛز اژُن۔\n2. حرامی گژھِ نہٕ خداوند سٕنزِ جماعتس مَنٛز اژُن۔ دٔہمہِ پُرِ تام تہِ گژھِ نہٕ سُہ خداوند سٕنزِ جماعتس مَنٛز دٲخل سپدُن۔\n3. امونیت یا موآبیت گژھِ نہٕ خداوند سٕنزِ جماعتس مَنٛز دٲخل گژھُن۔ دٔہمہِ پُرِ تام تہِ گژھن نہٕ تِم خداوند سٕنزِ جماعتس مَنٛز ہمیشہٕ خٲطرٕ دٲخل گژھن:\n4. کیازِ تِمو سٍتـ̡ سٍتـ̡ روٹی تہٕ آبہٕ سٍتـ̡ میلہِ، ییلہ تہٕ تُہۍ مصرہٕ منزٕ نیبر نیرِو۔ تہٕ امہ مۅکھہ زِ تِمو کٔر توے خٕلاف میسوپوٹیمیا کِس پیتھور کِس بیور سُند نیچو بلام، تہٕ تۅہہِ لعنتُک مۅکھہٕ۔\n5. بہر حال خداوند تُہند خدا کرِ نہٕ بلام سٕنز کتھ بوزان۔ مگر خداوند تُہند خدایہ بدلوو یہ لعنت تہٕ تۅہہِ خٲطرٕ نعمت، کیازِ خداوند تُہند خدا اوس ژے محبت کران۔\n6. ژٕ گژھ نہٕ پنٕنِس سارِنٕے دۅہس خٲطرٕ تِہُند امن تہٕ تِہٕنزِ خۄشحٲلی ہٕنز تلاش کٔرِتھ۔ {خوشحالی: ہیب۔ اَصٕل کَرنہٕ آمُت چھ\n7. ژے گژھ نہٕ ادومی سٕندِس سٍتـ̡ نفرت۔ تکیازِ سُہ چُھ تُہند بوے تہٕ ژے گژھ نہٕ مصری سٕنز نفرت۔ تکیازِ تۅہہ ٲسکھ تٔمۍ سٕندِس ملکس منز اجنبی ٲسمٕژ۔\n8. یِم بچہٕ یِم تِمن سٍتـ̡ پٲدٕ سپدان چِھہ تِمن ہٕندِس تریمہِ پُرِ سٍتـ̡ خداوند سٕنزِ جماعتس مَنٛز دٲخل گژھن۔\n9. یێلہِ لشکر پننین دُشمنن خلاف نیرِ، تیلہِ تھاوُن پان پرٮ۪تھ بدکار چیزس نِش۔\n10.\\tاگر تۅہہِ منز کانہہ انسان آسہِ، یُس ناپاکی کِنۍ پاک آسہِ نہ، تیلہِ گژھہِ نہ سُہ خٲمہِ منزٕ نیبر نیرُن، سُہ گژھِ نہٕ خٲمس اندر یِنہٕ۔\n11. مگر یہ گژھہِ ییلہ شام گژھہِ، سُہ گژھہِ پانس آبہٕ سٍتـ̡ واش کٔرِتھ، تہٕ ییلہ آفتاب لوسُن، سُہ گژھہِ دُبارٕ خٲمس مَنٛز۔ {cometh...: Heb. کُن پھیرُن}\n12.\\tژے گژھہِ کیمپ ورٲے تہِ جاے، ییتہِ تہِ ژیہ نیبر نیرِو:\n13.\\tتہِ گژھہِ پننہِ ہتھیارس پیٹھ پیڈل لاگُن۔ تہٕ یہ گژھہِ ییلہ ژیہ نیبر کُن آرام کرِ، تۅہہ کرِ اتھ سٍتۍ کھٔنِتھ، تہٕ یُس پانس نِش یِنہٕ وول چھُ، واپس پھیُرِو: {وِلٹ...: ہیب۔ بِہِتھ بِہُن}\n14. خداوند سٕندِ خٲطرٕ چُھہ تُہند خدا تُہٕندِس خٲمس مَنٛز پکان تہٕ تُہٕندِس دُشمن ہٕندِس مَنٛز چُھہ پکان ۔ تێمہِ کِنۍ گژھہِ تُہند خٲم مقدس ، یُتھ سُہ ژے مَنٛز کانہہ ناپاک چیز وُچھِ، تہٕ ژے نِش پھیرِ۔ {ناپاک...: ہیب۔ کُنہِ تہِ چیزچ ننگہ}\n15. تُہۍ گژھ نہٕ پننِس آقا سٕندِس آقا سٕندِس آقا سٕندِس نِش ژٔلِتھ دِنہٕ آمُت:\n16.\\tسُہ روزِ توے سٍتـ̡ تۅہہِ سٍتـ̡ تتھ جایہ یُس سُہ تہندِس دروازس مَنٛز ژٲرِ، یێتہِ سُہ سُہ زیادٕ پسند آسہِ، تێلہِ گژھہِ نہٕ تس سٍتـ̡ ظُلم کرنہٕ۔ {یِتھ...: ہیب۔ تٔمِس خٲطرٕ چُھ اصل}\n17.\\tاسرٲیلـ̡ کورِ ہٕنزِ کُنہِ تہِ طوائفہٕ آسہِ نہٕ تہٕ اسرٲیلـ̡ سٍت {طوائف: یا، سوڈومیٹس}\n18.\\tکُنہِ تہِ قسمہٕ خٲطرٕ گژھِ نہٕ کُنہِ تہِ عہد خٲطرٕ کُنہِ تہِ کُنہِ تہِ کُنہِ کُنہِ تہِ خدایہ سٕندِس گَرَس مَنٛز کُنہِ تہِ کُنہِ تہِ کُنہِ کُنہِ تہِ کُنہِ تہِ کُنہ\n19. ژے گژھ نہٕ پننِس بٲیس سود دِنہٕ۔ پونسہٕ ہُند رُسو، رُسو، کُنہِ تہِ چیزُک سود یُس سود دِنہٕ یِوان چُھ:\n20.\\tأکِس اجنبی سٍتـ̡ چُھہ سود دِتھ دِتھ۔ مگر پننِس بٲیِس سٍتـ̡ گژھ نہٕ سود دِنہٕ، یُتھ خداوند تُہند خدا کرِ تۅہہِ سٍتـ̡ برکت دِنہٕ یُس تہٕ تُہُند خدایہ تُہٕندِس زمینس مَنٛز یێلہِ تہِ تُہۍ یہِ حٲصِل کرِ۔\n21. یێلہِ تہٕ یێلہِ تُہۍ خداوند پننِس خداہس سٍتـ̡ عہد کٔرِو، تێلہِ گژھہِ نہٕ یہِ پورٕ کرنس منز کوتاہی کٔرِتھ، یێلہِ چُھہ تُہُند خدایہ یێلہِ تێلہِ ہُند تقاضہٕ کرُن۔ تہٕ یہ آسہِ ژے منز گۅناہ۔\n22. مگر اگر ژیہ عہد نِش باز کٔرِو، تیلہِ گژھہِ نہٕ تۅہہِ منز کانہہ گۅناہ۔\n23.\\tیُس تہِ چُھہ چُھہ ژے رژھرُن تہٕ انجام دِنہٕ یُن۔ {حتیٰ کہِ} یُس ژے خداوند پنُن خدایہ سٍتـ̡ وعدٕ کورمُت چُھ، یُس ژے پننہِ ٲسِس سٍتـ̡ وعدٕ کورمُت چُھ۔\n24. ییلہ تہۍ پننِس ہمساین ہٕندِس انگورس منز یِو، تیلہِ گژھِو ژیہ پننہِ مرضی سٍتـ̡ انگور کھٮ۪وان۔ مگر ژے تراوُن نہٕ پننِس بانس منز کانہہ تہِ۔\n25.\\tییلہ ژیہ پننِس ہمساین ہٕندِس کھنڈس منز وٲتِو، تیلہِ کٔرِو پنٕنۍ اتھہٕ سٍتۍ کَن تُلِتھ۔ مگر ژیہ گژھ نہ پننس ہمساین ہٕندِس کھڑا مکایہ سٍتۍ دٲر دِنہٕ۔","1.\\tییلہ کٲنسہِ مردس زنانہِ رٔٹِتھ أمِس سٍتـ̡ خاندر کرِ، تہٕ یہ سپدِ زِ أمِس چھُنہٕ أمِس نظرِ مَنٛز کانہہ احسان میلان تکیازِ أمِس چھُ أمِس مَنٛز کانہہ ناپاکی لبنہٕ آمٕژ، تیلہِ دِیہِ أمِس طلاق ہُند نوٹ تہٕ دِیُن أمِس اتھس مَنٛز، تہٕ دِیُن أمِس گَرٕ منزٕ نٮ۪بر۔ {کینٛہہ...: ہیب۔ عریثُک معاملہ} {طلاق: عبرانی۔ ژٹُن}\n2.\\tییلہ سۅ تمۍ سندِ گرہ منزہ نیبر نیرِ، سۅ گژھہِ بییِس مردس سٍتـ̡ بٔنِتھ۔ \n3. تہٕ اگر دوٚیِم خانٛدار أمِس سۭتۍ نفرت کرِ، تہٕ أمِس طلاق ہُند بل لیکھِتھ، تہٕ أمِس دِیہِ أمِس اتھس منٛز، تہٕ دِیہِ أمِس گَرٕ منٛزٕ نیبر۔ یا اگر دوٚیِم خانٛدار مٔرِتھ، یٔمۍ سُہ أمِس زنانہٕ بنیوو۔ \n4. تٔمۍ سُند سٲبقہٕ خانٛدار، یُس أمِس دُبارٕ سوزمُت اوس، سُہ گژھِ نہٕ أمِس دُبارٕ پننہِ خانٛدارِنہِ ہٕندِس مَنٛز نِنہٕ، اَمہِ پَتہٕ گژھہِ سۄ ناپاک کرنہٕ۔ یێلہِ چُھہ خداوند سٕندِس برونہہ کُن گۅناہ تہٕ تہٕ ژے گژھِ نہٕ زمینس گۅناہ کٔرِتھ، یُس خداوند تُہند خدا چُھہ توے دِژمُت چُھ۔ \n5.\\tییلہ کٲنسہِ مردس نٔو زنانہِ آسہِ، سہ گژھہِ نہ جنگس منز نیرُن، تہٕ نہ گژھہِ تس کُنہِ تہِ کاربارس پیٹھ الزام لگاونہٕ: {مگر} سُہ روزِ أکِس ؤریس منز آزاد، تہٕ پننہِ زنانہِ ہُند خۅش کرُن یُس تٔمِس نِش آسہِ۔ {تہِ نہ...: ہیب۔ أمِس سٍتـ̡ گژھِ نہٕ کانہہ تہِ چیز}\n6.\\tکانہہ تہِ انسان گژھِ نہ نیتھر یا پیٹھمہِ ملہِ ہُند گروی نِن، تکیازِ سُہ چُھ انسان سٕنزِ زندگی ہُند گروی نِوان۔ \n7. یێلہِ کانہہ شخٕص بنی اِسرٲیلِیَن مَنٛز کُنہِ تہِ بٲے ژوٗرِ نِوان لبنہٕ ییہِ، تہٕ أمِس سٍتـ̡ تجارت کٔرِتھ یا کٕننہٕ ییہِ۔ تیلہِ گژھہِ سُہ چور مَرُن۔ تہٕ تُہۍ کٔرِو بُرٕ پانس مَنٛز دوٗر کٔرِتھ۔ \n8.\\tکوڑھ کِس وباہَس مَنٛز رٔٹِو تہٕ یُس پادٕرۍ لیوی ہیچھناوان چھُ، تِتھہٕ کٔرِو تِمن مُطٲبِق کٔرِو۔ \n9. یاد تھاوُن زِ خداوند تہندِ خداین کیا کوٚر مریمس سٍتـ̡ وتہِ تہٕ تمہِ پتہٕ گٔیہٕ تم مصرہٕ منزٕ نیبر۔ \n10.\\tییلہ ژیہ پننِس بٲیِس کانہہ چیز دِیہِ، تۅہہ گژھِو نہٕ تٔمۍ سٕندِس گرس منز تٔمۍ سُند وعدٕ حٲصِل کرنہٕ خٲطرٕ اژُن۔ {دِیُن...: ہیب۔ کُنہِ تہِ چیزُک قرضہٕ دِیُن وغیرہ}\n11. تہٕ یُس نفر ژے دِیُو، سُہ کرِ تۅہہِ سٍتـ̡ وعدٕ کٔرِتھ۔ \n12. تہٕ اگر انسان غریب آسہِ، تۅہہ گژھِ نہٕ تٔمۍ سٕندِس وعدس سٍتـ̡ شۄنگنہٕ: \n13. بہر حال، آفتاب لوسنہٕ وِزِ تہٕ گژھہِ تٔمِس وعدٕ دُبارٕ دِنہٕ، یُتھ سُہ پنہٕ نِس پوشس منز شوٚنگِتھ تہٕ تۅہہِ کرِ برکت تہٕ یِہ گژھہِ تۅہہِ خدایہِ سٕندِس خداہس برونہہ کُن نیکی کرنہٕ۔ \n14.\\tژے کٔرِو نہٕ کُنہِ کرایہ دار خادمس سٍتـ̡ ظُلم کٔرِتھ {یُس غریب} تہٕ محتاج آسہِ، {چاہے سُہ پننین باین ہُند آسہِ}، یا تُہٕندِس ملکَس مَنٛز چُھہ تُہٕندِس دروازس مَنٛز روزنہٕ آمُت: \n15.\\tتٔمۍ سٕندِس دۅہہٕ سٍتـ̡ چُھہ تٔمۍ سُند کرایہ دِنہٕ، تہٕ نہ گژھہِ آفتاب اَتھ پیٹھ لوسُن۔ تکیازِ سُہ چُھ غریب، تہٕ چُھہ پنُن دِل اتھ پیٹھ بٔٹھِتھ، یێلہِ سُہ چُھہ تۅہہِ سٍتـ̡ خداہس سٍتـ̡ فریاد کٔرِتھ، تہٕ یہِ گژھہِ تۅہہِ سٍتـ̡ گۅناہ۔ {setteth...: ہیب۔ تٔمۍ سُند روح تُلِتھ چُھہ اَتھ کُن تُلان۔\n16.\\tمٲلۍ یِن نہٕ شُرین ہٕندِ خٲطرٕ مارنہٕ یِن، تہٕ نہ گژھن مٲلن ہٕندِ خٲطرٕ مارنہٕ یُن، پرٮ۪تھ کانہہ شخص گژھِ پننہِ گۅنہٕ کِنۍ مارنہٕ یُن۔ \n17.\\tژے گژھ نہ اجنبی سٕندِس فیصلس منز انحراف کرُن، نہ باپ سٕندِس فٲصلس سٍتـ̡ تہٕ نہ کُنہِ بیواہ سُند پلو تُلُن: \n18. مگر ژے گژھہِ یاد روزُن زِ تہٕ ژے ٲسٕکھ مصرس مَنٛز اکھ غلام تہٕ خداوند تُہند خدایہ دِژ تتہِ نِش نجات دِنہٕ۔ \n19.\\tییلہ ژیہ پننِس کھہس منز پنُن فصل ژٹِتھ کھہس منز اکھ کھورِ مٔشِد گژھِ، تہٕ ژے گژھِو نہٕ یہِ اننہٕ خٲطرٕ دُبارٕ نیرُن: یہِ گژھہِ اجنبی سٕندِ خٲطرٕ، یتیم سٕندِ خٲطرٕ تہٕ بیواہ ہٕندِ خٲطرٕ، یُتھ خداوند تُہند خدا کرِ تۅہہِ ہٕندِس سارِنٕے کامہِ سٍتـ̡ برکت دِنہٕ۔ \n20.\\tییلہ ژے پنُن زیتون کُلِس مارِو، تیلہِ گژھہِ نہٕ بییہ کُلِس پیٹھ نیرُن، یہ گژھہِ اجنبی سٕندِ خٲطرٕ، بے باپ سٕندِ خٲطرٕ تہٕ بیواہ ہٕندِ خٲطرٕ۔ {گژھو...: ہیب۔ یہ کٔرِو پانس پتہٕ}\n21.\\tییلہ ژیہ پننِس انگورُک انگور جمع کٔرِو، تمہ پتہ گژھہِ نہ یہ اجنبی، بے باپ، تہٕ بیواہ ہٕندِ خٲطرٕ۔ {پَتہٕ: ہیب۔ تۅہہِ پتہٕ}\n22.\\tتہٕ ژے گژھہِ یاد تھاوُن زِ تہٕ اوسُکھ مصرٕکِس سرزمینس مَنٛز غلام اوسمُت، تَمہِ مۄکھٕ چُھس بہٕ ژے یہِ کٲم کرنُک حُکُم دِوان۔","1. یێلہِ انسانن درمِیان کانہہ تنازعہ سپدِ، تہٕ تِم فیصلہ کٔرِن، یێلہِ {قاضی} کرِ تِمن ہُند فیصلہ کرنہٕ۔ تیلہِ گژھن تِم نیکوکارن ہُند جواز ثٲبت تہٕ بدکارن ہنز مذمت کرن۔ \n2. تہٕ یہِ گژھہِ یێلہِ بدکار سُہ مارنہٕ لایق آسہِ، تہٕ قاضی کرِ أمِس بُتھِس برونہہ کُن، تٔمۍ سٕنزِ غلطی مطٲبق، أکِس خاص تعدادس سٍتـ̡ مارنہٕ۔ \n3.\\tژتٲجی پٹۍ دِیہِ، {تہٕ} زیادٕ نہٕ زیادٕ: اگر سُہ زیادٕ کھۅتہٕ زیادٕ دِیہِ، تہٕ یِمو پیٹھٕ واریہو پٹیو سٍتۍ مار دِیہِ، تیلہِ گژھہِ تُہند بٲے تۅہہِ خٲطرٕ بدکار باسُن۔ \n4.\\tییلہ سُہ مکایہِ نیبر نیرِتھ ژیہ نہٕ داند کٔرِتھ۔ {ٹریڈ...: ہیب۔ تھریشتھ}\n5.\\tاگر بٲے اکوٹہٕ روزن، تہٕ یِمو منزٕ اکھ مٔرِتھ تہٕ بچہٕ آسہِ نہٕ، تیٚلہِ گژھِ نہٕ مُرنہٕ سٕنزِ زنانہٕ کُنہِ اجنبی سٕندِس سٍتـ̡ خاندر کرنہٕ۔ {تٔمۍ سٕندِس خانٛدارس...: یا تٔمِس بییِس رشتہ دارس}\n6. تہٕ یہِ گژھہِ زِ یُس گۅڈٕ زامُت آسہِ، سُہ گژھہِ پننِس بٲے سٕندِس ناوس سٍتـ̡ کامیاب سپدُن، یُس نہٕ تٔمۍ سُند ناو اسرٲیلـ̡ منزٕ کڈنہٕ یُن۔ \n7.\\tتہٕ اگر مرد پننِس بٲے سٕنزِ زنانہِ نِش نِنہٕ یژھان آسہِ، تیلہِ گژھہِ بٲے سٕنزِ زنانہِ بٔڈِس نِش دروازس تام واتناوُن، تہٕ ونُن زِ میانہِ خانٛدار سُند بٲے چھُ اسرٲیلس مَنٛز پننِس بٲیِس ناو تھاونہٕ نِش انکار کرُن، سُہ کرِ نہٕ میٲنِس خانٛدار سٕندِس بٲے سٕنز فرض۔ {بٲے سٕندِس: یا، بییِس رشتہٕ دارس}\n8.\\tتیلہِ گژھن تٔمۍ سٕندِس شہرٕکۍ بزرگ أمِس بُلاون، تہٕ أمِس سٍتـ̡ کتھ کرٕن، تہٕ {یێلہ} سُہ کھڑا گژھِ، تہٕ ونُن، بہٕ چُھس نہٕ أمِس نِنُک پسند۔ \n9.\\tتیلہِ گژھہِ تٔمِس بٲے سٕنز زنانہٕ زِٹھٮ۪ن ہٕنزِ موجودگی منز أمِس نِش یِنہٕ، تہٕ تٔمِس کھورِ نِش کھورِ کھورِ نِش تہٕ تٔمِس بُتھِس پیٹھ تھوکُن تہٕ جواب دِیہِ تہٕ وَنُن زِ تٔمِس شخصس یُس نہٕ تٔمِس بٲے سُند گرٕ بناوِ۔ \n10. تہٕ تٔمۍ سُند ناو یِیہِ اسرٲیلِس مَنٛز وننہٕ یُن، یُس تٔمۍ سُند جوُر یلہٕ آسہِ۔ \n11.\\tییلہ مرد اَکھ أکِس سٍتـ̡ رٔلِتھ کوشش کران چُھ، تہٕ أکِس سٕنزِ زنانہٕ پَنُن خانٛدار یُس أمِس ماران چُھ، تہٕ پَنُن اَتھٕ تُلِتھ تہٕ رازن ہٕندِس سٍتـ̡ رٔٹِتھ رٔٹِتھ: \n12. تیلہٕ ژٔٹِکھ تٔمۍ سُند اَتھٕ ژٹُن، تٔمۍ سٕنزِ أچھ گژھِ نہٕ رحم کٔرِتھ۔ \n13.\\tژے آسہِ نہ پننہِ بیگس منز مختلف وزن، اکھ بوٚڈ تہ اکھ لۅکٹ۔ {غوطہ...: ہیب۔ اکھ کنہ تہ اکھ کن}\n14.\\tژے آسہِ نہ پننِس گرس منز اکھ بٔڈ تہٕ لۅکٹ۔ {غوطہ...: عبری۔ اکھ ایفا تہٕ اکھ ایفاہ}\n15. {مگر} ژے آسہِ کامل تہٕ منصفانہ وزن، اکھ کامل تہٕ منصفانہ پیمانہٕ آسُن، یُس تُہند خدایہ تُہند خدایہ دِوان چھُ، تُہند دۅہ گژھہِ زیٹھراوُن۔ \n16.\\tیِم سارِنٕے یِتھٕ کامہِ کٔرِتھ، {تہٕ} یِم سارِنٕے بد کار کران چِھ، {چُھہ} خداوند تُہٕندِس خداہٕ سٕندِ خٲطرٕ مُنفرت۔ \n17. یاد تھاوُن زِ عمالیقن کیا کوٚر توے سٍتـ̡ ییلہ تم مصرہٕ منزٕ نیبر نیرِو۔ \n18.\\tکِتھہ پاٹھۍ ووت سُہ ژے وتہِ سٍتـ̡ تہٕ ژے پٔتِس سارِنٕے کمزورس سٍتـ̡ لٔگِتھ تہٕ بێہوش گٔیہِ۔ تہٕ سُہ اوس نہٕ خدایہ سٍتـ̡ کھوژان۔ \n19. تێلہِ گژھہِ یێلہِ یێلہِ خداوند تُہٕندِس خدایہِ سٍتـ̡ تُہٕندِس دُشمن سٍتـ̡ دِیُت تُہٕندِس زمینس مَنٛز، یُس خداوند تُہُند خدا چُھہ تُہٕندِس دُشمن سٍتـ̡ دِژمُت، {یێلہِ} چُھہ تُہٕندِس خداہس سٍتـ̡ اسمانس تلہٕ پى۪ٹھٕ آمالیک سٕنز یاداشت مِٹاونہٕ یِوان۔ تێہہ گژھِ نہٕ یہِ مٔشِد گٔژھِتھ۔","1. تہٕ سُہ گژھہِ یێلہِ تُہۍ تتھ زمینس مَنٛز یُس خداوند تُہند خدا دِیُت تہٕ تُہٕندِس خدایس دِیُت تہٕ اَتھ مَنٛز روزِ۔ \n2. یُس ژے زمینہِ ہٕندِس سارِوٕے پھلَس مَنٛز نِیُن، یُس تُہُند خداوند تُہُند خدا دِنہٕ آمُت چُھ، تہٕ یُس أکِس ٹوٗکرِ مَنٛز تراوُن، تہٕ گژھِو تتھ جایہِ یُس خداوند تُہند خدا پنُن ناو تھاونہٕ خٲطرٕ منتخب کرِ۔ \n3. تہٕ تُہۍ گژھِو تٔمِس پادٕرِس نِش یُس تِمن دۅہن آسہِ، تہٕ تٔمِس وَنُن، بہٕ چُھس از دۅہہٕ خداوند پننِس خداہس سٍتـ̡ اقرار کران زِ بہٕ چُھس تتھ ملکس مَنٛز آمُت یُس خداوند سانین مٲلن سٍتـ̡ دِنہٕ خٲطرٕ حلف چُھ دِتمُت۔ \n4. تہٕ پادٕرۍ کٔرِن تُہٕندِ اَتھٕ منزٕ ٹوٗکرِ تہٕ تھاوُن خداوند پنُن خدایہ سٕندِس قربان گاہَس برونہہ کُن۔ \n5. تہٕ تہٕ ژٕ کرٕ خداوند پنُن خدا، اکھ شامی یُس ختم گژھنہٕ خٲطرٕ تیار اوس، تہٕ سُہ گوٚو مصرس مَنٛز، تہٕ تتہِ بنیوو اکھ بٔڈ، طاقتور تہٕ آباد۔ \n6. تہٕ مصریو کٔر اسہِ بد کار تہٕ دِژ اسہِ مُتٲثِر تہٕ کوٚرُکھ اسہِ سخٕت غلامی ۔ \n7. تہٕ یێلہِ أسۍ پننین آباؤ اجدادن ہٕندِس خدایس نِش فریاد کٔر، خداوند بوٗز سانہِ آواز، تہٕ سانہِ مصیبت، تہٕ سانہِ محنت، تہٕ سانہِ ظلمس وُچھن: \n8. تہٕ خداوند کٔر اسہِ مِرٕ منزٕ طاقتور اتھہٕ سٍتـ̡ تہٕ نٔر پھٔہلٲوِتھ تہٕ سٮ۪ٹھاہ خوفناک سٍتـ̡ تہٕ علامتو سٍتـ̡ تہٕ عجائب سٍتـ̡ نیبر۔ \n9. تہٕ تٔمۍ چھُ اسہِ یَتھ جایہِ مَنٛز أنِمُت، تہٕ دِژُن اسہِ یہِ زمین، {حتیٰ کہ} یُس دۄدٕ تہٕ ماچھہِ سٍتـ̡ وسان چھُ۔ \n10. تہٕ وُن، وُچھ، بہٕ اوٚن زمینُک گۄڈنیُک پھل، یُس ژے میہ دِژمُت چھُ۔ تہٕ ژٕ تھاوُن یہِ خداوند پَنُن خداہٕ سٕندِس برونہہ کُن، تہٕ کٔرِو خداوند پنٕنِس خداہٕ سٕندِس برونہہ کُن عبادت کرنہٕ۔ \n11. تہٕ گژھِو پرٮ۪تھ کُنہِ نیکی سٍتـ̡ خوش سپدُن یُس خداوند تُہٕندِس خدایہِ سٕندِ دِژمُت چُھ، تہٕ تُہٕندِس گَرَس تہٕ تُہٕندِس گرس تہٕ لیوی تہٕ تُہٕندِس درمِیان چُھہ اجنبی سٍتـ̡ دِژمُت۔ \n12. یێلہِ ژے پنُن دسُہ دِنہٕ ختم کٔرِو، تہٕ دِژُکھ لوی، اجنبی، بے باپ تہٕ بیواہ ہٕندِس دِنہٕ خٲطرٕ، یُس تُہٕندِس دروازس مَنٛز کھٮ۪نہٕ تہٕ بٔرِتھ بٔرِتھ۔ \n13. تێلہِ چُھہ ژے خداوند پنُن خدایہ برونہہ کُن ونُن، بہٕ چُھس پننہِ گرٕ منزٕ پاک چیز نِش نِمُت، تہٕ یِم تہِ دِژمٕژ لویِس تہٕ اجنبی سٕندِس تہٕ بے باپِس تہٕ بیواہ ہٕندِس حُکمَس مُطٲبِق یِم ژے مے حُکُم دِژمٕژ چھِ: مے چُھنہٕ تُہٕندِس حُکمن ہٕنز خلاف ورزی کٔرمٕژ، تہٕ نہ چُھس مٔشِد گومُت: \n14. میہ چُھہ نہٕ پننِس ماتم سٍتـ̡ اَمہ سٍتـ̡ کھیوٚمُت، نۂ چُھہ نہٕ اتھ {کُنہِ}ناپاک {استعمال} خٲطرٕ نِمُت، تہٕ نہ چُھس مُردن ہٕندِ خٲطرٕ {گژھُن} دِژمُت: {مگر} مے چُھہ خداوند پننِس خدایہ سٕنز آواز بوزمٕژ، {تہٕ} یُس ژے میہ حکم دِژمُت چُھ، تِمن مُطٲبق چُھہ کورمُت۔ \n15. پَنٕنـ̡ مُقدس بَسٲیِنـ̡ سٍتـ̡ وُچھِو، تہٕ پَنٕنـ̡ قوم اسرٲیلـ̡ تہٕ سُہ زمینہٕ یُس ژے اسہِ دِژمُت چُھ، یێلہِ سٍتـ̡ دۄدٕ تہٕ ماچھ سٍتـ̡ وسان چُھ۔ \n16. از دۅہہٕ چُھہ تُہٕندِس خداہِ سٕندِ خداہِ یِم قونوُن تہٕ فیصلہٕ کرنُک حُکُم دِیُتمُت، تێمہِ مۄکھٕ تھاوُن تہٕ یِم پَنٕنہِ پوٗرٕ دِلہٕ سٍتـ̡ تہٕ پوٗرٕ روحہٕ سٍتـ̡ انجام دِنہٕ خٲطرٕ۔ \n17. ژے چُھ از دۅہہ خداوند سُند خدا بننُک وعدٕ کورمُت، تہٕ تٔمۍ سٕنزِ وتہِ پیٹھ پکُن، تہٕ تٔمۍ سٕندِس حکمن، تہٕ تٔمۍ سٕندِس فٲصلس پیٹھ عمل کرنُک تہٕ تٔمۍ سٕنزِ آواز بوزنہٕ خٲطرٕ: \n18.\\tتہٕ خداوند چُھہ از دۅہہ ژیہ تٔمۍ سٕندِ مخصوص لُکھ بننُک وعدٕ کورمُت، تہٕ تٔمۍ سٕندِس سارِنٕے حُکمن ہُند عمل کرُن۔ \n19. تہٕ یُس تٔمۍ سارِنٕے قومن ہٕندِس سٍتـ̡ تٔمِس سٍتـ̡ تہٕ ناوٕ سٍتـ̡ تہٕ عزتس سٍتـ̡ بنوومُت چُھ۔ تہٕ یێلہِ تێلہِ چُھہ تُہٕندِس خدایہِ سٕندِ خٲطرٕ پاک قوم بٔنِتھ، یێلہِ تٔمۍ سٕندِ کتھ کٔرمٕژ چُھ۔","1. تہٕ موسىٰ دِژ اسرٲیلِکۍ بزرگن سٍتـ̡ لُکن ہُند حُکُم تہٕ وونُن زِ تِم سارِنٕے حُکمن ہُند عمل کرُن یِم بہٕ از دۅہہ حُکُم کران چھُ۔ \n2. تہٕ سُہ دۅہہ گژھہِ یێلہِ ژے اردن کِس زمینس کُن نیرِو یُس خداوند تُہند خدا ژیہ دِژمُت چُھ، تێلہِ کٔرِو بٔڈۍ کٔنہِ تہٕ تِمن سٍتـ̡ کٔرِو تِمن ہٕندِس سٍتـ̡ دِنہٕ۔ \n3. تہٕ یێلہِ تێلہِ یێلہِ تہٕ تُہٕندِس خدایہِ سٕندِس خداہس دِنہٕ آمٕژ زمینہٕ کُن گژھِو یُس دۄدٕ تہٕ ماچھ سٍتـ̡ وسان چُھ۔ یێلہِ چُھہ تُہٕندِس مٲلِس خداہِ سُند وعدٕ کورمُت۔ \n4. تێمہِ کِنۍ گژھہِ یێلہِ ژیہ اردنس پیٹھ نیرِو، تہٕ یِم کٔنہِ یِم بہٕ ژے از دۅہہ ایبال کِس پہاڑس مَنٛز حُکُم دِوان چھِ، تہٕ ژے کٔرِو یِم کٔنہِ کُنہِ کُنہِ سٍتـ̡ دِنہٕ۔ \n5. تہٕ تتہِ کٔرِو خداوند پننِس خدایہِ سٕندِ خٲطرٕ اکھ قربان گاہ، یُس کنن ہُند قربان گاہ بناوُن، تہٕ تُہۍ تُلِو نہٕ تِمن پیٹھ ششتٕر {اوزار}۔ \n6. تُہۍ کٔرِو پَنُن خداوند سُند قربان گاہ یُس پَنُن پَنُن پَنُن کُنہِ کُنہِ سٍتـ̡ بَناوُن، تہٕ تێہہ کٔرِو اَتھ پٲٹھـ̡ خداوند پننِس خداہس سٍتـ̡ دزنہٕ نذرانہ پیش کرنہٕ۔ \n7. تہٕ تُہۍ کٔرِو امن ہٕندِ نذرانہ پیش تہٕ اَتہِ کھٮ۪وان تہٕ خداوند پَنٕنِس خداہٕ سٕندِس برونہہ کُن کٔرِو شاد ۔ \n8.\\tتہٕ ژے پٔزِ کنن پیٹھ امہِ شریعتٕکۍ سٲری لفظ صاف پٲٹھۍ۔ \n9. تہٕ موسیٰ تہٕ کاہنَو کٔر سارِنٕے اسرٲیلِس سٍتـ̡ کتھ زِ اے اسرٲیل، ہوشیار تہٕ بوزو۔ اَز دۅہہٕ چُھہ تُہۍ خداوند پَنٕنـ̡ خدایہِ سٕندِ لُکھ بٔنِو۔ \n10. تێمہِ کِنۍ گژھ تُہۍ خداوند پَنٕنِس خدایہ سٕنزِ آوازِ ہٕنز اطاعت کٔرِتھ، تہٕ تٔمۍ سٕندِس حکمس تہٕ تٔمۍ سٕندِس حکمس کٔرِو یُس بہٕ از ژے حکم دِوان چُھس۔ \n11.\\tتہٕ موسىٰ دِژ امی دۅہہ لوکن پیٹھ الزام زِ \n12. یِم گژھن کوہ گریزِم کِس پٲٹھـ̡ کھڑا گژھِتھ لُکن ہٕندِس دُعا دِنہٕ مۅکھہٕ، یێلہِ یێلہِ تُہۍ اردنس پیٹھ وٲتِو۔ شمعون تہٕ لیوی تہٕ یہوداہ تہٕ عیساکر، تہٕ یوسف تہٕ بنیمن: \n13.\\tتہٕ یِم گژھن کوہ ایبالس پیٹھ لعنتُک مۅکھہٕ کھڑا گژھن۔ روبن، گاد تہٕ آشر، تہٕ زبولون، دان تہٕ نفتالی۔ {لعنت: حب۔ لعنت}\n14. تہٕ لاوی کَرٕن کَتھ تہٕ سارِنٕے اِسرٲیلِس سٍتـ̡ بَڑِ آوازِ سٍتـ̡ وَنُن، \n15.\\tلعنت کرُن سُہ انسان یُس {کُنہِ} کھٔنِتھ یا پگلٲوِتھ بَناوان چُھ، یُس خداوند سٕندِ خٲطرٕ کُنہِ تہِ کُنہِ تہِ کُنہِ کُنہِ تہِ کامہِ سٍتـ̡ بناوان چُھہ، تہٕ {یہ} چُھہ {a} خفیہ {جاے} مَنٛز تھاوُن۔ تہٕ سارِنٕے لُکھ دِن جواب تہ \n16.\\tیُس پننِس مٲلِس یا ماجہ ہٕندِ دٔسۍ گاش دِوان چھُ۔ تہٕ سارِنٕے لُکھ وَنُن آمین۔ \n17.\\tیُس پننِس ہمساین ہُند نشان ہٹٲوِتھ چھُ۔ تہٕ سارِنٕے لُکھ وَنُن آمین۔ \n18.\\tلعنت کرُن یُس انہِ وتہِ نِش بھٹناوان چھُ۔ تہٕ سارِنٕے لوٗکھ وَنُن آمین۔ \n19.\\tیُس اجنبی، بے باپ تہٕ بیواہ سُند فیصلہٕ غلط کرُن آسہِ، سُہ گژھہِ لعنت۔ تہٕ سارِنٕے لوٗکھ ونن آمین۔ \n20. یُس پننِس مٲلہِ سٕنزِ زنانہِ سٍتـ̡ روزان چُھ، سُہ چُھہ لعنت دِوان۔ تکیازِ سُہ چُھ پننِس مٲلہِ سٕنزِ زنانہِ ہُند پوشہٕ کھولان۔ تہٕ سارِنٕے لُکھ وَنُن آمین۔ \n21.\\tیُس کُنہِ تہِ قسمہ کِس درندس سٍتـ̡ روزان آسہِ، لعنت کرُن۔ تہٕ سارِنٕے لُکھ وَنُن آمین۔ \n22.\\tیُس پننہِ بینہِ سٍتـ̡ روزِ، مٲلہِ سٕنزِ کورِ یا ماجہ ہٕنزِ کورِ سٍتـ̡ روزُن۔ تہٕ سارِنٕے لُکھ وَنُن آمین۔ \n23.\\tیُس پننہِ ماجہ سٍتـ̡ روزان چُھ، سُہ چُھہ لعنت۔ تہٕ سارِنٕے لوٗکھ وَنُن آمین۔ \n24.\\tیُس پننِس ہمساین ژوٗرِ پٲٹھـ̡ ماران چُھ۔ تہٕ سارِنٕے لُکھ وَنُن آمین۔ \n25.\\tیُس بے گناہ شخصس مارنہٕ خٲطرٕ انعام رٹان چھُ، سُہ چُھ لعنت۔ تہٕ سارِنٕے لوٗکھ وَنُن آمین۔ \n26.\\tلعنت کرُن یُس نہٕ اتھ شریعت کین کلامَن ہٕنز تصدیق کرِ۔ تہٕ سارِنٕے لُکھ وَنُن آمین۔","1. تہٕ یێلہِ تہٕ تێلہِ گژھہِ تێلہِ تێلہِ یێلہِ تہٕ تُہٕندِس سارِنٕے حُکمن ہُند عمل کرُن یُس بہٕ از تہٕ چُھس ژے حُکُم دِوان چُھ، یێلہِ خداوند تُہُند خدا کرِ ژے سارِنٕے قومن ہٕندِس تھزرس پیٹھ۔ \n2. تہٕ یِم سٲری نعمتہٕ گژھن توے سٍتـ̡ یێلہِ تہٕ \n3. بابرکت {شال} ژے {شَہ} شہرس مَنٛز، تہٕ بابرکت {شَل} ژٕ {بٔن} کھاہس مَنٛز۔ \n4. چانہِ جسمُک پھل تہٕ پننہِ زمینہِ ہُند پھل تہٕ چانہِ چارواین ہُند پھل تہٕ چانہِ کۅکرِ ہُند پھل تہٕ پننہِ کۅکرِ ہُند پھل تہٕ چانہِ کۅکرِ ہُند پھل آسُن۔ \n5. چانۍ ٹوٗکرِ تہٕ تُہند دُکانہٕ آسہِ بابرکت {بابرک}۔ {دکان: یا، ڈو، یا، گنڈُن}\n6. بابرکت {شُل} ییلہ تہٕ ژٕ اژان چُھ، تہٕ بابرکت {شُل} ییلہ تہٕ نٮ۪بر نیرِو۔ \n7. خداوند کرِ تۅہہِ سٍتـ̡ دُشمن یُس تۅہہِ سٍتـ̡ بُتھِس برونہہ کُن کھڑا سپدان چُھ، تِم گژھن تۅہہِ سٍتـ̡ اَکہِ وتہِ نِش نیرِتھ تہٕ ژلہِ سَتھ وتہٕ ژلٕنـ̡ ۔ \n8. خداوند دِیہِ تۅہہِ سٕندِس ذخیرَس مَنٛز تہٕ یُس تہٕ تُہٕندِس خدایہِ سٕندِس دِنہٕ آمُت چھُ۔ تہٕ سُہ کرِ تۅہہِ تُہٕندِس زمینس مَنٛز برکت یُس خداوند تُہند خدا دِوان چُھ۔ {ذخیرٕ: یا، بارن}\n9. خداوند کرِ تۅہہِ پانس خٲطرٕ اکھ مقدس قوم قٲیم، یِتھ کٔنۍ تٔمۍ تۅہہِ سٍتـ̡ حلف کورمُت چُھ، یێلہِ تہٕ تٔمۍ سٕندِس وتہِ پٲٹھـ̡ پٔکِتھ پٔکِو۔ \n10. تہٕ زمینہِ ہٕندِس سارِنٕے لُکھ وُچھن زِ تُہہِ چُھہ خداوند سٕندِ ناوٕ سٍتـ̡ بُلاونہٕ آمُت۔ تہٕ تِم گژھن تۅہہِ سٍتـ̡ کھوژان۔ \n11. تہٕ خداوند کرِ ژے مالہٕ سٍتـ̡ سٮ۪ٹھاہ زیادٕ، پننہِ جسمہٕ کِس پھلس منز، تہٕ پننہِ چارواین ہٕندِس پھلس منز، تہٕ تُہنزِ زمینہِ ہٕندِس پھلس منز، تتھ زمینس مَنٛز یُس خداوند تُہٕندِس مٲلس سٍتـ̡ دِنُک قسم چُھ دِتمُت۔ {مالہٕ منز: یا، خیر خٲطرٕ} {جسم: ہیب۔ یٔڈِ}\n12. خداوند کھولہِ تۅہہِ خٲطرٕ پنُن اصل خزانہٕ، اسمان، یُس تُہنزِ زمینہِ ہٕندِس موسمس مَنٛز روٗد دِیہِ، تہٕ تُہٕندِس سارِنٕے کامہِ سٍتـ̡ برکت دِنہٕ۔ \n13. تہٕ خداوند بناوِ ژے کلہٕ، تہٕ لٔٹ نہٕ۔ تہٕ تُہۍ گژھِو صرف تھوٚد روزُن، تہٕ تہٕ ژٕ گژھِ نہٕ بۄن کُن۔ یێلہِ تہٕ یێلہِ بہٕ چُھہ ژے از حُکُم دِوان چُھ، یێلہِ تہٕ یێلہِ چُھہ تُہٕندِس خدایہِ سٕندِس حُکمن سٍتـ̡ بوزُن، یُس بہٕ چُھس ژے از حُکُم دِوان چُھہ، یێلہِ تہٕ یێلہِ تہٕ تِمن ہُند عمل کرنُک حُکُم چُھہ: \n14.\\tتہٕ ژے گژھ نہٕ تِمن لفظن نِش دور گژھُن یُس بہٕ از دٔچھُن اتھہٕ دِوان چھُ، یا کھوورِ اتھہٕ سٍتـ̡ یِمن ہٕنزِ خدمتہٕ کرنہٕ خٲطرٕ باقین دیوتاہن ہٕندِ پَتہٕ گژھُن۔ \n15. مگر یێلہِ نہٕ تۅہہ خداوند پنُن خدایہ سٕنز آواز بوزِو، تٔمۍ سٕندِس تمام حُکمن تہٕ تٔمۍ سٕندِس قونونن ہٕنز پابندی کرٕن، یِمن ہُند بہٕ چُھہ از دۅہہ حُکُم دِنہٕ آمُت۔ یێلہِ یِم سارِنٕے لعنتَن ہٕندِس سٍتـ̡ یِن تہٕ یێلہِ تێہہِ سٍتـ̡ یێلہِ یێلہِ تہٕ یێلہِ تێلہِ یێلہِ یێلہِ تہٕ یێلہِ تێلہِ یِمن ہُند حُکُم دِنہٕ آمُت چھُ۔ یێلہِ یِم سارِن \n16.\\tبد دعا کٔرِتھ {شال} ژے شہرس مَنٛز، تہٕ لعنتی {شَل} ژے {بَہ} کھاہس مَنٛز۔ \n17.\\tچانۍ ٹوٗکرِ تہٕ تُہند دُکان گژھہِ لعنت۔ \n18. چانہِ جسمُک پھل تہٕ پننہِ زمینہِ ہُند پھل تہٕ پننہِ زمینہِ ہُند پھل تہٕ چانہِ کۅکرِ ہُند پھلہٕ تہٕ پننہِ کۅکرِ ہُند پھلہٕ تہٕ تہندِس دامنس ہُند پھلہٕ گژھہِ لعنت۔ \n19.\\tییلہ ژیہ اژان چھیہ، تہ ییلہ ژیہ نیبر نیرِتھ تہِ گژھہِ لعنت۔ \n20. خداوند سوزِ ژے پیٹھ یُس تہِ کرُن یُس تہِ کرُن چُھہ تۅہہِ سٍتـ̡ بد دعا تہٕ ملامت کٔرِتھ، یوتام نہٕ ژے تباہ گٔیہِ، تہٕ یوتام نہٕ ژے جلدٕے ختم گٔیہِ۔ تۅہہِ ہٕنزِ بد کاری سٍتـ̡ ییمہِ سٍتـ̡ ژے مے ترٲومُت چُھ۔ {for...: Heb. یُس ژے کرُن چُھہ}\n21.\\tخداوند کرِ یہ وبا ژٔٹِتھ ژٔٹِھتھ یوتام نہٕ سُہ ژےٚ زمینہٕ نِش کھٮ۪یہِ، یێلہِ تہِ ژے یہِ حٲصِل کرنہٕ خٲطرٕ گژھِ۔ \n22. خداوند دِیہِ ژےٚ کھٮ۪نہٕ سٍتۍ، تپھ سٍتۍ، ورمہٕ سٍتۍ، تہٕ سٮ۪ٹھاہ دزنہٕ سٍتۍ، تلوار سٍتۍ، تہٕ دھماکہٕ سٍتۍ، تہٕ پھپھہٕ سٍتۍ۔ تہٕ تِم کرِ تۅہہِ ہُند پیچھا یوٚت تام نہٕ تُہۍ مرنہٕ۔ {تلوار: یا، خشک سالی}\n23. تہٕ تُہند آسمان، یُس تہندِس کلس پیٹھ چُھہ، تہٕ تۅہہِ تلہ کنہِ زمین آسہِ ششتٕر۔ \n24. خداوند کرِ تۅہہِ ہٕنزِ زمینہِ ہُند پاؤڈر تہٕ گرد، اسمانہٕ سٍتـ̡ وسُن تہٕ تۅہہِ ہٕندِس پٲٹھـ̡ یێلہِ تُہٕندِس سٍتـ̡ تباہ گٔیہِ۔ \n25.\\tخداوند کرِ تۅہہِ پننین دُشمنن برونہہ کُن مارُن، تہٕ ژٔلِو تِمن برونہہ کُن سَتھ وتہٕ ژلُن، تہٕ یِمن ہٕندِس سارِنٕے سلطنتس مَنٛز ژٔلِتھ تہٕ یِیہِ سارِنٕے دُشمن ہٕندِس بادشاہتس مَنٛز نِنہٕ۔ {ہٹاونہٕ آمُت: حب۔ ہٹاونہٕ خٲطرٕ}\n26. تہٕ تُہند لاش آسہِ ہوہٕکۍ سارنٕے جاناوارن تہٕ زمینہٕ کین درندن ہُند ماز تہٕ کانہہ تہِ انسان گژھِ نہٕ ژٔلِتھ۔ \n27. خداوند دِیہِ ژے مصرٕکِس بوٹہٕ سٍتـ̡ تہٕ اِمِروڈس سٍتـ̡ تہٕ کھورِ سٍتـ̡ تہٕ خارٕ سٍتـ̡ یُس نہٕ ژے شفا دِتھ ہێکہِ ہێکہِ نہٕ۔ \n28.\\tخداوند کرِ ژے دیوانگی تہٕ انہِ تہٕ دِل ہٕندِ حیرانگی سٍتـ̡ مارٕ: \n29. تہٕ تُہۍ گژھِو دُپہرس گٔژھِتھ، یِتھٕ پٲٹھۍ انہِ گٔیہِ گٔژھِتھ گٔژھِتھ، تہٕ تۅہہِ گژھہِ نہٕ پننہِ وتہِ سٍتـ̡ \n30.\\tژے کرِ زنانہِ سٍتـ̡ منگنی تہٕ بییِس مردس سٍتـ̡ روزُن، تہٕ ژے کرِ نہٕ اَتھ مَنٛز روزُن، تہٕ ژے کٔرِو نہٕ اَتھ مَنٛز روزُن۔ {جمع کٔرِو...: ہیب۔ ناپاک، یا کٔرِو عام ماز کِس طورس پیٹھ}\n31.\\tتُہُند گَر یِیہِ تۅہہِ ہٕندِس أچھن برونہہ کُن مارنہٕ یُن، تہٕ تۅہہِ گژھِ نہٕ تُہٕندِس بُتھِس برونہہ کُن نِنہٕ یُن، تہٕ یِیہِ نہٕ تۅہہِ واپس دِنہٕ۔ {گژھِ نہٕ...: ہیب۔ تُہٕندِس نِش گژھِ نہٕ واپس}\n32.\\tتُہٕندِ نیچوۍ تہٕ کورِ یِن بییِس لُکہٕ سٍتـ̡ دِنہٕ، تہٕ تُہٕنزِ أچھ گژھن سارِوٕے دۅہس تِمن ہٕندِ خٲطرٕ وُچھِتھ تہٕ سارِوٕے دۅہس تِمن ہٕندِ خٲطرٕ روزِ نہٕ کانہہ طاقت۔ \n33. چانہِ زمینُک پھل تہٕ تُہٕنزِ سارِنٕے محنتہٕ سٍتـ̡ گژھہِ تِژھ قوم یُس نہٕ ژے زانان آسہِ۔ تہٕ تُہہِ گژھہِ ہمیشہٕ مظلوم تہٕ کٔرِتھ کٔرِتھ: \n34.\\tیُتھ ژٕ گٔژھِو پَنٕنـ̡ أچھن ہٕندِس نظرس سٍتـ̡ پاگل گٔژھِتھ یُس ژے وُچھِو۔ \n35.\\tخداوند دِیہِ ژے کۅٹھن تہٕ زنگن مَنٛز، یُس نہٕ تُہندِ کھورِ ہٕندِس تلہٕ پیٹھٕ کلہٕ پیٹھٕ ژٔٹِتھ دِنہٕ یُس نہٕ ٹھیک ہیکہِ سپدِتھ۔ \n36. خداوند اَنِن ژے تہٕ تُہُند بادشاہ یُس ژے پانس پیٹھ مقرر کرُن، أکِس قومس مَنٛز یُس نہٕ تۅہہِ تہٕ تُہٕندِس آباؤ اجداد زانان آسہِ۔ تہٕ تتہِ کٔرِو تُہٕندِس دیوتاہن ہٕنز، لٔکرِ تہٕ کنن ہٕنز خدمت۔ \n37. تہٕ تُہۍ گژھِو سارِنٕے قومن مَنٛز اکھ حیران، اکھ محاورہٕ تہٕ اکھ لفظ، یُس خداوند تُہۍ نِیہِ۔ \n38.\\tژے کٔرِو واریاہ بیٲلۍ کھہس مَنٛز، تہٕ کٔرِو کم کُنہِ سٍتـ̡ کُنہِ کُنہِ کُنہ \n39.\\tژے کٔرِو انگور وُنُن، تہٕ پَلَو لاگُن، مگر شرابٕ پییہِ نہٕ تہٕ سٍتـ̡ سٍتـ̡ {انگور} جمع کٔرِتھ۔ کیازِکہِ کیمہٕ گژھن یِم کھٮ۪ن۔ \n40.\\tژے گژھہِ پننین سارنٕے ساحلن منز زیتون کُلۍ، مگر تیلہٕ سٍتـ̡ کرِ نہٕ پانس مسح کرنہٕ۔ تکیازِ تُہند زیتون تراوِ {تٔمۍ سُند پھل}۔ \n41.\\tژے پییہِ نیچوۍ تہٕ کورِ زٲنِتھ، مگر تِمن ہُند مزٕ گژھِ نہٕ۔ تِم گژھن قٲد کرنہٕ۔ {ژے گژھِ نہٕ تۅہہِ ہٕندِس سٍتـ̡ بێیہِ۔ تِم گژھن نہٕ تُہٕندِس سٍتـ̡ آسٕنـ̡\n42. تُہٕندِس سارِنٕے کُلۍ تہٕ مٮ۪وٕ کٔرِن ٹِڈِ۔ {کھٮ۪ن: یا، قبضہٕ}\n43.\\tیُس اجنبی یُس تۅہہِ اندر چھُ، سُہ گژھہِ تۅہہِ ہیوٚر تھزر۔ تہٕ ژے گژھہِ واریاہ بۄن بۄن وسان۔ \n44.\\tسُہ دِیہِ تۅہہِ دِنہٕ، تہٕ تُہۍ دِیہِ نہٕ أمِس دِنہٕ: سُہ آسہِ کلہٕ تہٕ تُہۍ گژھِہ لٔٹ بٔنِتھ۔ \n45. یِم سارِنٕے لعنتَن یِن توے سٍتـ̡ یِمن ہٕندِس حُکمَس تہٕ تٔمۍ سٕندِس حکمس تہٕ تٔمۍ سٕندِس حکمس پیٹھ عمل کرنہٕ خٲطرٕ، یێلہِ تٔمۍ سٕندِس حکمس تہٕ تٔمۍ سٕندِس حکمس پیٹھ عمل کرُن چُھہ نہٕ تۅہہِ سٍتـ̡ یێلہِ سٍتـ̡ تۅہہِ سٍتـ̡ یێلہِ سٍتـ̡ تٔمۍ سٕندِس حکمس تہٕ تٔمۍ سٕندِس حکمس پیٹھ عمل کرنہٕ خٲطرٕ تہٕ تٔمۍ سٕندِس حکمس پیٹھ عمل کرنہٕ خٲطرٕ چُھہ نہٕ تۅہہِ سٍتـ̡ خدایہ س \n46. تہٕ تِم گژھن توے سٍتـ̡ أکِس نشانہٕ سٍتـ̡ تہٕ عجائب کِس سٍتـ̡ تہٕ تُہٕندِس بُلِس خٲطرٕ ہمیشہٕ خٲطرٕ۔ \n47. کیازِکہ توے کٔر نہٕ خداوند پننِس خدایہِ سٕنز خۅش تہٕ خوشی سٍتـ̡ سارِنٕے چیزن ہٕنزِ کثرت خٲطرٕ۔ \n48. تێمہِ کِنۍ کٔرِو پَنٕنـ̡ پَنٕنـ̡ دُشمن ہٕنز خدمت یُس خداوند تۅہہِ خٕلاف سوزِ، فاقہٕ سٍتـ̡ تہٕ ترشس منز، ننگہٕ سٍتـ̡ تہٕ سارِنٕے چیزن ہٕنزِ محتاجی سٍتـ̡ تہٕ سُہ تراوِ تۅہہِ ہٕندِس گردنہِ پیٹھ ششتُرُک جوہ، یوتام نہٕ سُہ ژے تباہ کرِ۔ \n49.\\tخداوند کرِ توے خلاف دور پیٹھ، زمینہِ ہندِ اندس پیٹھ، {تیژ تیژ} یُتھ زن عقاب وُڈان چُھ؛ اکھ قوم یمۍ سٕنز زبان ژیہ نہٕ سمجِتھ آسہِ؛ {سمجُن: عبرانی۔ بوزو}\n50.\\tاکھ زبردست قوم، یُس نہ بُزرگ شخصس سٍتۍ احترام کرِ، تہٕ نہ جوانن پیٹھ احسان کرِ: {شدید...: ہیب۔ بُتھِس مضبوط}\n51.\\tتہٕ سُہ کھٮ۪یہِ تُہٕندِس چارواین ہُند پھل تہٕ تُہٕندِس زمینُک پھل کھٮ۪نہٕ، یوتام نہٕ تُہۍ تباہ گژھِ۔ \n52. تہٕ سُہ کرِ تۅہہِ سارِنٕے دروازن مَنٛز گھیرٕ، یوتام تُہٕنزِ تھدِ تہٕ تارٕ دار دیوار یِن یَتھ پیٹھ تۅہہِ سٲرِسٕے سرزمینس پیٹھ بھروسہ آسہِ، تہٕ سُہ کرِ تُہٕندِس سارِنٕے سرزمینس مَنٛز تُہٕندِس سارِنٕے دروازن مَنٛز گھیرٕ، یُس خداوند تُہٕندِس خداہن دِژمُت چھُ۔ \n53. تہٕ ژے کھیوٚو پننہِ جسمُک پھل، پننین نیچوٮ۪ن تہٕ کورِ ہُند ماز، یُس خداوند تُہندِ خداین ژےٚ دِژمُت چُھ، محاصرس مَنٛز، تہٕ تِمن مُشکِلَن مَنٛز، یێمہِ سٍتـ̡ تُہٕندِس دُشمن دِنہٕ سٍتـ̡ تُہٕندِس دُشمن سٍتـ̡ تُہٕندِس دُشمن سٍتـ̡ دِنہٕ آمُت: {جسم: حب۔ یٔڈ}\n54.\\tیُتھ زِ یُس انسان یُس تہِ نرم تہٕ سٮ۪ٹھاہ نازک آسہِ، تٔمۍ سٕنز نظر گژھہِ پننِس بٲیِس سٍتـ̡ تہٕ پننِس بٔرِس سٍتـ̡ تہٕ پننین شُرین ہٕندِس باقیاتس کُن یُس سُہ تراوِ۔ \n55.\\tیُتھ سُہ دِیہِ نہٕ تِمَن منزٕ کٲنٛسہِ تہِ پننین شُرین ہُند ماز یُس سُہ کھٮ۪یہِ، کیازِ أمِس چُھہ نہٕ تِمن ہٕندِس محاصرس مَنٛز تہٕ تُہٕندِس دُشمن سٍتـ̡ تُہٕندِس سارِنٕے دروازس مَنٛز تُہٕندِس دُشمن مَنٛز دِنہٕ آمُت۔ \n56.\\tیۅہے نرم تہٕ نازک زنانہ، یۅسہٕ نزاکت تہٕ نرمی خٲطرٕ پننِس کھورِ ہُند سول زمینس پیٹھ تراونٕچ مہم جوئی کرِ، تٔمۍ سٕنز نظر گژھہِ پننہِ چھۅکہٕ سٕندِس خانٛدارس تہٕ نیچوِس تہٕ کورِ ہٕندِس کُن بد کار۔ \n57.\\tتہٕ پننِس شُرِس کُن یُس تٔمۍ سٕندِس کھورِ منزٕ نیران چُھ، تہٕ پننین شُرین کُن یُس سُہ زینہٕ یِن، تکیازِ سُہ چُھ تِمن سارِنٕے چیزن ہٕندِس محتاجس سٍتـ̡ ژوٗرِ پٲٹھۍ، یێمہِ سٍتـ̡ تُہند دُشمن تہٕ تُہٕندِس دروازس مَنٛز تُہٕندِس دُشمن ہٕندِس دُشمن سٍتـ̡ تُہٕندِس دروازس مَنٛز دِیہِ۔ {نوجوان: ہیب۔ زینہٕ پتہٕ}\n58. یێلہِ نہٕ تۅہہِ یێمہِ شریعت ہٕندِ سارِنٕے کلامَن ہٕندِس سٍتـ̡ یِم اتھ کتابہِ مَنٛز لیکھنہٕ آمٕتۍ چھِ، تێلہِ گژھہِ تُہٕندِس عظیم تہٕ خوفناک ناوُک خوف یُس خداوند پنُن خدا۔ \n59. تیلہٕ کرِ خداوند تُہند وبا حیرت انگیز، تہٕ تُہندِ بُلٕچ وبا، بٔڈۍ آفت، تہٕ واریاہس کالس تہٕ دکھ بیمارِ تہٕ واریاہس کالس روزُن۔ \n60.\\tامہِ علاوٕ اَنہِ سُہ ژے مِصرٕچ سارِنٕے بیمارِ یِمو سٍتـ̡ ژےٚ کھوژان ٲس۔ تہٕ تِم گژھن ژےٚ ژٔٹِتھ ۔ \n61. تہٕ پرتھ کانہہ بیمار، تہٕ پرٮ۪تھ کانہہ وبا، یُس نہٕ اتھ شریعت کِس کتابس منز لیکھنہٕ آمُت چُھ، تِم کرِ خداوند توے پیٹھ دِنہٕ، یوتام نہٕ تُہۍ تباہ گژھِ۔ {اَنُن: عبر۔ وجہ}\n62. تہٕ تہٕ یێلہِ تہٕ تُہۍ ٲسِو واریاہ زیادٕ آسمانٕکۍ ستارٕ ہٕندۍ پٲٹھۍ۔ تکیازِ تہٕ تێہہ چُھہ نہٕ خداوند پنٕنِس خدایہ سٕنزِ آوازِ ہٕنز فرمانبرداری کٔرِتھ۔ \n63. تہٕ یہِ سپدِ، یِتھٕ کٔنۍ خداوند چُھہ تۅہہِ سٍتـ̡ خوش سپدُن، تہٕ تۅہہِ ہُند بُراونہٕ مۅکھہٕ۔ یێلہِ خداوند چُھہ تۅہہِ سٍتـ̡ خۅش سپدِتھ تہٕ تۅہہِ ہُند خاتمہ کرنہٕ خٲطرٕ۔ تہٕ یێلہِ تہٕ یێلہِ تہِ تُہہِ سٍتـ̡ تُہٕندِس قبضس مَنٛز گژھِو۔ \n64. تہٕ خداوند کرِ ژے سارنٕے لُکن مَنٛز، زمینہٕ کِس اَکہِ اندس پیٹھٕ بییِس اندس تام۔ تہٕ تتہِ کٔرِو تُہۍ باقین دیوتاہن ہٕنز عبادت کٔرِتھ، یِم نہٕ تۅہہِ تہٕ تُہٕندِس مٲلِس زانان آسہِ، {حتیٰ کہ} لٔکرِ تہٕ کٔنہِ تہِ۔ \n65. تہٕ یِمن قومن مَنٛز گژھہِ نہٕ تۅہہِ کانہہ آسٲنی میلہِ، تہٕ نہ گژھہِ تۅہہِ سٍتـ̡ آرام دِنہٕ، مگر خداوند دِیہِ تتہِ دِیہِ ژےٚ تھرتھر دِل تہٕ أچھن ہُند غم تہٕ دٮ۪ماغ۔ \n66.\\tتہٕ تُہٕنزِ زُو روزِ ژےٚ برونہہ کُن شَکَس مَنٛز۔ تہٕ ژٕ روزِ دۄہ تہٕ رٲژ کھوژان، تہٕ پننہِ زِنٛدگی ہُند کانہہ تہِ یقین روزُن: \n67. صُبحَس وَنُن چُھہ خدایہ ہا! تہٕ توتہِ وَنُن زِ خدایہ آسہِ صبح! تُہٕندِس دِلُک خوفہٕ سٍتـ̡ یێمہِ سٍتـ̡ ژے خوفہٕ آسہِ، تہٕ تُہٕندِس أچھن ہٕندِس نظرس سٍتـ̡ یُس ژے وُچھِو۔ \n68.\\tتہٕ خداوند اَنِہ ژے جہازٕ سٍتـ̡ دُبارٕ مصرس مَنٛز، یێمہِ سٍتـ̡ میہ ژے کتھ کٔرمٕژ، تہٕ تتہِ یِن نہٕ تۅہہِ دُشمن ہٕندِس دُشمنن تہٕ خادمن ہٕندِ بدلہٕ کٕننہٕ یِن، تہٕ کانہہ تہِ مرد ہیوٚت نہٕ۔","1. یِم چھِ عہدٕکۍ کلام، یُس خداوند موسیٰ ہس موآب کِس سرزمینس مَنٛز بنی اسرٲیلِس سٍتـ̡ کرُن حُکُم دِیُتمُت، یُس تٔمۍ تِمن سٍتـ̡ حوربس مَنٛز کورمُت اوس۔ \n2. تہٕ موسىٰ کٔر سارنٕے اسرٲیلِس بُلاونہٕ تہٕ تِمن وُچھمُت، یُس خداوند پننین نظرن برونہہ کُن کٔر، یُس تہٕ فرعونس تہٕ تٔمۍ سٕندِس سارِنٕے خادمَن تہٕ تٔمۍ سٕندِس سارِنٕے سرزمینس سٍتـ̡ کورمُت۔ \n3. تِم بٔڈ فتنہ یِم تۅہہِ أچھن وُچھمٕتۍ، نشانہٕ تہٕ تِم بٔڈ معجزہٕ: \n4. توتہِ چُھ نہٕ خداوند از تام وُچھنہٕ خٲطرٕ دِل تہٕ وُچھنہٕ خٲطرٕ أچھ تہٕ بوزنہٕ خٲطرٕ کَن دِژمُت۔ \n5. تہٕ مے چُھس ژتٲجی ؤری بیابانن منز وُچھمُت: چانہِ پلو چُھنہٕ وٲنسہٕ وٲنسہِ، تہٕ تُہند جوُر چُھنہٕ کھورِ پٲٹھـ̡ وٲنـ̡ وٲنـ̡ ۔ \n6.\\tژے چُھہ نہٕ روٹی کھیوٚمُت، نہ چُھہ شراب، نہ چُھہ شراب، یُتھ ژے زانہِ زِ بہٕ چُھس خداوند تُہند خدا۔ \n7. تہٕ ییلہ تم اتھ جایہ وٲتۍ، ہیشبونُک بادشاہ سیہون تہٕ بشانُک بادشاہ اوگ آو اسہِ خلاف جنگہٕ خٲطرٕ درٛاو، تہٕ أسۍ مارۍ تمن مار۔ \n8.\\tتہٕ أسۍ تِہٕنز زمین رٔٹِتھ تہٕ دِتُکھ یہِ روبینن تہٕ گادِین تہٕ مناسی کِس نصف قبیلس وراثتس منز۔ \n9. تَمہِ مۄکھٕ کٔرِو یَتھ عہدٕکِس کلامَس پیٹھ عمل تہٕ کٔرِو یُس تہٕ کٔرِو تُہۍ کٔرِو سُہ کُنہِ کُنہِ کُنہِ سٍتـ̡ \n10. تُہۍ چُھہ از تہِ خداوند پنٕنِس خداہس برونہہ کُن کھڑا روزان؛ پَنٕنـ̡ قبیلن ہٕندِس کپتان، پۯنـ̡ بزرگ تہٕ پۯنـ̡ سٍتـ̡ سارِنٕے اِسرٲیلـ̡ سٍتـ̡ \n11.\\tتُہٕندِس لٔکرِس منز، تُہٕنزِ زنانہٕ تہٕ تُہٕندِس خٲمس مَنٛز، تُہٕندِس لٔکرِ ہٕندِس دٔرِس تام: \n12. یُس خداوند پنُن خدایہ سٍتـ̡ تہٕ تٔمۍ سٕندِس حلفس مَنٛز دٲخل گژھُن، یُس خداوند تُہند خدا از دۅہہ توے سٍتـ̡ کران چُھہ: {دٲخل: ہیب۔ پاس}\n13.\\tیُتھ سُہ یُس تۅہہِ سٍتـ̡ أکِس لُکہٕ خٲطرٕ پانس سٍتـ̡ قایم کٔرِتھ، تہٕ یێلہِ سُہ تہٕ یێلہِ تۅہہِ سٍتـ̡ خدایہِ بٔنِتھ تہٕ یێلہِ تٔمۍ تُہٕندِس مٲلِس سٍتـ̡ ، ابراہیمس سٍتـ̡ ، اسحاق تہٕ یعقوبس سٍتـ̡ حلف کورمُت۔ \n14. بہٕ چُھس نہٕ صرف ژے سٍتـ̡ یہِ عہد تہٕ یہِ حلف کٔرِتھ۔ \n15. مگر سُہ یُس از دۅہہ اسہِ سٍتـ̡ سٲنـ̡ خدایہِ سٍتـ̡ کھڑا چُھ، تہٕ سٍتـ̡ {أمِس} سٍتـ̡ یُس نہٕ از کل اسہِ سٍتـ̡ چُھہ: \n16. (تۅہہ چھے پتاہ زِ أسۍ کِتھہ پٲٹھـ̡ أسـ̡ مصر کِس سرزمینس مَنٛز روزان چُھ، تہٕ أسـ̡ کِتھہ پٲٹھـ̡ وٲتِتھ قومن مٔنزۍ یِمن نِش تہٕ یێلہِ تێلہِ تێلہِ گٔیہِ۔ \n17.\\tتہٕ تِہٕندِ بُت، تہٕ تِہٕندِ بُت، لٔکرِ تہٕ کٔن، رۄپہٕ تہٕ سۄنہٕ وُچھمٕتۍ، یِم {یِمَن} مَنٛز ٲسِ:) {بُت: عبرانی۔ گُرِ دیوتا}\n18. یێلہِ گژھہِ تۅہہِ مَنٛز کانہہ مرد، یا زنانہٕ، یا خاندان، یا قبیلہٕ آسہِ، یێمہِ سُند دِل یێمہِ دۅہہ سٲنِس خدایہ سٕندِس خداہس نِش پھیُرِ، یێمہِ سٍتـ̡ گژھہِ یِمن قومن ہٕندِس دیوتاہن ہٕنزِ خدمت کرنہٕ خٲطرٕ۔ یێلہِ گژھہِ تێلہِ مَنٛز کانہہ موٗل آسہِ یُس پَلہٕ تہٕ کُلہٕ آسہِ۔ {گال: یا، اکھ زہریلہٕ جڑی بوٹی: ہیب۔ روش}\n19.\\tتہٕ ییلہ سُہ امہِ لعنتٕچ کتھ بوزان چُھ، سُہ چُھ پننِس دِلس مَنٛز برکت دِوان، یێلہِ بہٕ چُھس پننہِ دِل کِس تخیلس مَنٛز پکان تہٕ شرابہٕ ہُند شرابہٕ ہُرراوُن: {تخیل: یا، ضد کرُن} {شرابہٕ...: ہیب۔ شرابہٕ چُھس پیاس}\n20. خداوند دِیہِ نہٕ أمِس بَچاونہٕ، مگر تیلہِ گژھہِ خداوند سُند غصہٕ تہٕ تٔمۍ سُند حسد أمِس شخصس سٍتـ̡ دِنہٕ، تہٕ یِم سٲری لعنت، یُس اتھ کتابہِ مَنٛز لیکھنہٕ آمُت چھُ، تہٕ خداوند کرِ تٔمِس سُند ناو اسمانس تل مٹاونہٕ۔ \n21. تہٕ خداوند کرِ سُہ سُہ اِسرٲیلِیات کِس سارِنٕے قبیلو نِش بُرِس سٍتـ̡ الگ کَرُن، یُس شریعت کِس یتھ کتابہِ مَنٛز لیکھنہٕ آمُت چُھ: {are: Heb. is}\n22.\\tیُتھ یُس تُہٕندِس شُرین ہٕندِس یِنہٕ وٲلِس نسلس یُس تۅہہِ پَتہٕ وُتھ، تہٕ یُس اجنبی یُس دوٗرِ زمینہٕ پیٹھٕ یِنہٕ وُچھِ، سُہ وَنُن یُس تَمہِ زمینہِ ہٕندِس وُپھ تہٕ تِم بیمارِ یِم خداوند اَتھ پیٹھ دِژمٕژ چھِ۔ {یُس...: حب۔ یێمہِ سٍتـ̡ خداوند چُھ یہِ بیمار کورمُت}\n23. {تہٕ یہ} سٲرۍسٕے زمینہٕ {چُھ} گندھک تہٕ نوٗن، {تہٕ} دزان، {یہ} چُھہ نہٕ وونہٕ آمُت، تہٕ نہ چُھہ اتھ مَنٛز کانہہ گاسہٕ وۄپدان، یِتھ کٔنۍ سدوم تہٕ عمورہ، آدمہ تہٕ زیبویم ہُند تختہٕ پٲٹھۍ، یُس خداوند پننِس غصہٕ تہٕ غصس سٍتـ̡ ختم کٔرِتھ: \n24.\\tسارِنٕے قومن تہِ ونن زِ خداوند کیازِ چُھ یَتھ زمینس سٍتـ̡ یِتھٕ پٲٹھۍ کورمُت؟ یێمہِ بٔڈ غصہٕ ہُند کیا مطلب چُھہ؟ \n25. تیلہِ گژھن انسان ونان، کیازِ تِمو چُھ پننین مٲلن ہندِ خدایہ سُند عہد ترک کورمُت، یُس تِمو تِمن سٍتـ̡ مصر کہِ سرزمینہٕ منزٕ نیبر کڈنہٕ وِزِ تِمن سٍتـ̡ کورمُت اوس۔ \n26.\\tتکیازِ تِمو گٔے تہٕ باقین دیوتاہن ہٕنز خدمت کٔرِتھ، تہٕ تِمن ہٕنز پوجا کٔرٕن، تِمن دیوتاہن ہٕنز پوٗزا کٔرٕن، یِمن نہٕ تِمن زانان ٲس، تہٕ {یِمَن} تِمن دِژمٕژ ٲس: {یِمَن سٍتـ̡ تِمن دِژمٕژ آسہٕ﴾ {دِنہٕ آمُت: ہیب۔ تقسیم}\n27.\\tتہٕ خداوند سُند غصہٕ آو اتھ زمینس سٍتـ̡ دِنہٕ، یُس اتھ کتابہِ مَنٛز لیکھنہٕ آمُت چھُ: \n28. تہٕ خداوند کٔر تِم غصہٕ تہٕ غصہٕ سٍتـ̡ تہٕ سٮ۪ٹھاہ غصہٕ سٍتـ̡ تِمن ہٕنزِ زمینہٕ منزٕ موٗل کٔرِتھ تہٕ دِژُن بییِس زمینس مَنٛز، یِتھ کٔنۍ از تہِ چُھ۔ \n29. راز {چیز} چُھ خداوند سانہِ خدایہ سٕندِ سٍتـ̡ ، مگر تِم {چیز} یِم ظٲہر سپدان چِھہ تِم چِھ اسہِ تہٕ سانین شُرین ہٕندِس سٍتـ̡ ہمیشہٕ خٲطرٕ تعلق تھاوان، یێلہِ {أسـ̡ ہێکہِ امہِ شریعتٕکۍ سٲری کلام کٔرِتھ۔","1. تہٕ یێلہِ یێلہِ یِم سارِنٕے چیٖز یێلہِ یِم برکت تہٕ لعنت، یُس مے ژے برونہہ کُن دِژمُت چُھ، تہٕ تێہہ کرِ سارنٕے قومن مَنٛز یاد پٲٹھۍ، یێلہِ تہٕ تُہٕندِس خدایہِ سٕندِ خدایہِ ژےٚ ژٔلِمُت چھُ، \n2. تہٕ گژھ خداوند پنُن خدایہ سٕندِس نِش واپس، تہٕ تٔمۍ سٕنزِ آوازِ ہٕنز اطاعت کٔرٕن یُس بہٕ از دۅہہ تہٕ تُہٕندِس شُرِس سٍتـ̡ چُھہ پنہٕ نِس دِلہٕ سٍتـ̡ تہٕ پنہٕ نـ̡ سٲرۍسٕے دِلہٕ سٍتـ̡ تہٕ پنہٕ نـ̡ سٍتـ̡ سٍتـ̡ تٔمۍ سٕنزِ آوازِ ہٕنز اطاعت کرٕنـ̡ ۔ \n3. یێلہِ یێلہِ خداوند تُہُند خدا چُھہ تُہٕندِس قید کٔرِتھ، تہٕ کرِ تُہٕندِس خداہس سٍتـ̡ رحم کٔرِتھ تہٕ یێلہِ تُہٕندِس خدایہِ سٍتـ̡ تُہٕندِس خدایہِ سٍتـ̡ ژٔٹِتھ ژٔٹِتھ دِیہِ۔ \n4. یێلہِ تۅہہِ منزٕ کانہہ تہِ اسمانہٕ کِس دٔرِمِس حصس کُن کڑنہٕ یِیہ، تتہِ نِش کرِ خداوند تُہند خدا تُہہِ سٍتـ̡ جمع کٔرِتھ، تہٕ تتہِ نِیہِ تۅہہِ نِن: \n5. تہٕ خداوند تُہُند خدا اَنِہ تُہٕندِس تٔمِس زمینس مَنٛز یُس تُہٕندِس مٲلِس سٍتـ̡ آسہِ، تہٕ تێہہِ کرِ اَتھ سٍتـ̡ حٲصِل کرنہٕ۔ تہٕ سُہ کرِ تۅہہِ نیکی تہٕ کرِ تۅہہِ پننین مٲلن کھوتہٕ زیادٕ۔ \n6. تہٕ خداوند تُہند خدا کرِ تُہند دِل تہٕ تُہٕندِس دِلس سٍتـ̡ تہٕ تُہٕندِس دِلَس سٍتـ̡ تہٕ پننہِ سارِنٕے روحہٕ سٍتـ̡ محبت کرنہٕ خٲطرٕ، یُتھ ژے زندٕ روزِ۔ \n7. تہٕ خداوند تُہند خدا دِیہِ یِم سارِنٕے لعنت، تہٕ تُہٕندِس دُشمنن تہٕ تِمن سٍتـ̡ یِمو تۅہہِ سٍتـ̡ ظلم کٔرِ۔ \n8. تہٕ ژٕ گژھ واپس تہٕ خداوند سٕنزِ آوازِ ہٕنز فرمانبرداری، تہٕ تٔمۍ سٕندِس سٲری حکمس کٔرِو یِم بہٕ از ژے حکم دِوان چھِ۔ \n9. تہٕ خداوند تُہند خدا کرِ ژے پننہِ اتھہٕ کِس پرٮ۪تھ کامہِ منز، پننہِ جسمہٕ کِس پھلس منز، تہٕ پننہِ چارواین ہٕندِس پھلس منز، تہٕ پننہِ زمینہِ ہٕندِس پھلس مَنٛز، اصلہٕ خٲطرٕ، تکیازِ خداوند کرِ توے سٍتـ̡ خیر سٍتـ̡ شاد سپدان، یِتھ کٔنۍ سُہ تہندِس مٲلس پیٹھ شاد سپدِ۔ \n10. یێلہِ تہٕ یێلہِ تُہۍ خداوند پَنٕنِس خدایہِ سٕنز آواز بوزِو، تٔمۍ سٕندِس حکمس تہٕ تٔمۍ سٕندِس حکمس تہٕ تٔمۍ سٕندِس قونونن یُس شریعت کِس یتھ کتابہِ مَنٛز لیکھنہٕ آمُت چُھ، {تہٕ} یێلہِ تہٕ پَنٕنـ̡ پَنٕنـ̡ سارِوٕے دِلہٕ سٍتـ̡ پَنٕنـ̡ خداوند سٕندِس خداہس کُن پھیرِو۔ \n11.\\tیَتھ حُکمَس مُطٲبِق یُس بہٕ از ژے حُکُم دِوان چھُس، سُہ چُھنہٕ ژے نِش پوشیدٕ تہٕ نہ چُھہ یہِ دور ۔ \n12. یہ چُھہ نہٕ اسمانس مَنٛز، زِ ژے کُس گژھہِ اسہِ خٲطرٕ جنتس تام کھسِتھ تہٕ اسہِ نِش اَننہٕ، یُتھ أسۍ یہ بوزِتھ تہٕ کٔرِو؟ \n13.\\tنہ چھہ یہ سمندرس اپارِ تہ ژیہ ونُن، کُس کرِ اسہِ خاطرہ سمندرس اپارِ نیرِ، تہ اسہِ نِش انِ، تاکہ أسۍ بوزِتھ تہٕ کرِ۔ \n14.\\tمگر لفظ {چُھ} چُھہ تۅہہِ سٍتـ̡ واریاہ نزدیک، تہٕ تُہندِس دلس منز، یُتھ ژے یہ کٔرِتھ۔ \n15.\\tوُچھو، میہ چُھہ ژے برونہہ کُن از دۅہہٕ زندگی تہٕ نیکی تہٕ موت تہٕ بدی مقرر کٔرمٕژ۔ \n16. یێمہِ سٍتـ̡ چُھس بہٕ ژے از دۅہہ حکم دِوان زِ خداوند پنُن خدایہ سُند محبت کرُن، تٔمۍ سٕنزِ وتہِ پیٹھ پکُن، تہٕ تٔمۍ سٕندِس حکمس تہٕ تٔمۍ سٕندِس حکمس تہٕ تٔمۍ سٕندِس فٲصلن ہٕنز پاسداری کرٕن، یُتھ تہٕ ژے روزٕ زندٕ روزُن تہٕ بٔڑِتھ روزُن: تہٕ خداوند تُہند خدا کرِ تتھ زمینس مَنٛز برکت یُس تہٕ یێلہِ تہٕ تُہۍ گژھِو تتھ زمینس مَنٛز برکت دِیُن۔ \n17. مگر اگر تُہُند دِل پھیُرِ، یێلہِ نہٕ تُہُند دِل بوزُن، مگر یێلہِ گژھِہ ژٔلِتھ تہٕ باقین دیوتاہن ہٕنز پوٗزا کٔرِتھ تہٕ تِمن ہٕنز خدمت کٔرِو۔ \n18.\\tبہٕ چُھس از ژے مذمت کران زِ ژیہ گژھہِ پزۍ پاٹھۍ فنا گژھُن، {تہٕ} تہٕ یێلہِ تہٕ ژے یێلہِ تہٕ یێلہِ ژے اردن کِس قبضس مۅکھہ نیرِ۔ \n19. بہٕ چُھس آسمانس تہٕ زمینس بلاوان زِ یہ دۅہ چُھہ توے خلاف درج کرنہٕ خٲطرٕ، {یُتھ} مے چُھہ ژے برونہہ کُن زندگی تہٕ موت، برکت تہٕ لعنتُک انتخاب کرُن: \n20. یُتھ تہٕ تُہۍ ہێکہِ تٔمۍ سٕنزِ آوازِ ہٕنز اطاعت کٔرِتھ، تہٕ یێلہِ تہٕ تُہۍ ہێکہِ تٔمِس سٍتـ̡ رٔٹِتھ روزُن، یێلہِ تُہۍ تُہٕندِس مٲلِس سٍتـ̡ روزُن، یێلہِ تُہٕندِس مٲلِس سٍتـ̡ تہٕ یعقوب سٍتـ̡ دِنہٕ خٲطرٕ تہٕ یێلہِ سٍتـ̡ تُہٕندِس مٲلِس سٍتـ̡ بٔرِتھ روزُن یێلہِ خداوند پننین مٲلن سٍتـ̡ ، ابراہیمس سٍتـ̡ ، اسحاق سٕندِس تہٕ یعقوبس سٍتـ̡ دِنہٕ خٲطرٕ حلف دِیُت ۔","1. تہٕ موسىٰ گۆو یِم کلام سارِنٕے اسرٲیلِس سٍتـ̡ وَننہٕ۔ \n2. تہٕ تٔمۍ ووٚن تِمن زِ بہٕ چُھس از ہتھ وُہُن وُہُن۔ بہٕ ہیوٚک نہٕ وُنہِ نیبر نیرِتھ اژِتھ، تہٕ خداوند چُھس مےٚ ووٚنمُت زِ ژٕ گژھ نہٕ یَتھ اردنس اپارِ نیرُن۔ \n3. خداوند تُہند خدا، سُہ گژھہِ تۅہہِ برونہہ کُن، {تہٕ} سُہ کرِ تۅہہِ برونہہ کُن یِمن قومن تباہ تہٕ تۅہہِ ہٕندِس قبضس منز روزِ۔ \n4. تہٕ خداوند کرِ تِمن سٍتـ̡ یِتھٕ پٲٹھـ̡ یێلہِ تٔمۍ سِحون تہٕ اوگس سٍتـ̡ تہٕ تِمن ہٕندِس سرزمینس سٍتـ̡ یُس تٔمۍ تباہ کٔر۔ \n5. تہٕ خداوند دِیہِ تِم تُہٕندِس بُتھِس برونہہ کُن، یُتھ تِمن سارِنٕے حُکمن مُطٲبِق کٔرِو یِمن مُطٲبِق یِمن ہُند حُکُم چُھہ دِژمُت۔ \n6. مضبوٗط تہٕ اصل حوصلہٕ تھاوُن، تِمن سٍتـ̡ گژھہِ نہٕ خوفزدہ تہٕ تِمن سٍتـ̡ کھوژُھن: خداوند تُہند خدا، سُہ چُھہ یُس توے سٍتـ̡ چُھہ سٍتـ̡ نیران۔ سُہ کرِ نہٕ توے سٍتـ̡ ناکام تہٕ نہ تراوُن۔ \n7. تہٕ موسىٰ کٔر یشوع سٕندِس مَنٛز بُلاونہٕ تہٕ وونُن سارِنٕے اِسرٲیلِس مَنٛز، مضبوٗط تہٕ حوصلہٕ تھاوُن، تِکیازِ تُہۍ گژھِو یِمن لُکن سٍتـ̡ تتھ زمینس تام گژھُن یُس خداوند تِمن ہٕندِس مٲلِس سٍتـ̡ دِنُک قَسم کورمُت چُھ۔ تہٕ ژے دِیُن تِمن ہُند وٲرث۔ \n8. تہٕ خداوند، سُہ چُھہ یُس توے برونہہ کُن چُھہ؛ سُہ آسہِ توے سٍتـ̡ روزِ، سُہ کرِ نہٕ تۅہہِ سٍتـ̡ ناکام تہٕ نہ تراوُن: خوفہٕ گژھِہ نہٕ تہٕ خوفزدہ گژھُن۔ \n9. تہٕ موسیٰ ہن لیوکھ یہِ شریعت تہٕ دیتُن یہ شریعت لاوی سٕندِس نیچوِس پادٕنَن تام، یُس خداوند سٕندِ عہدُک صندوق تہٕ اسرٲیلِہ کین سارِنٕے بزرگن تام واتناوُن۔ \n10. تہٕ موسىٰ دِیُت تِمن حُکُم دِتھ زِ پرٮ۪تھ سَتھ ؤری کِس ٲخرس پیٹھ، رِہٲیی ہٕندِس ؤری کِس عیدس مَنٛز، خیمہ خانن ہٕندِس عیدس مَنٛز، \n11. یێلہِ سارِوٕے اِسرٲیلـ̡ خداوند سٕندِس خدایہِ سٕندِس برونہہ کُن یُس سُہ ژٲرِ، تێلہِ پٔرِو یہِ شریعت سارِنٕے اسرٲیلِس برونہہ کُن تہنزِ بوزنہٕ خٲطرٕ۔ \n12. لُکن سٍتـ̡ مرد، زنانہٕ، تہٕ شُرۍ، تہٕ پَنُن اجنبی یُس پنہٕ نِس دروازس مَنٛز جمع کرُن، یُتھ زن تِم بوزِن، تہٕ تِم ہیٚچھِن تہٕ تُہٕندِس خداہس سٍتـ̡ خوفزدہ گژھن، تہٕ یێمہِ شریعت ہٕندِس سارِنٕے کلامَن ہُند عمل کرُن: \n13. تہٕ یێلہِ تِہٕندِس شُرِس یێلہِ نہٕ کانہہ تہِ زان آسہِ، تێلہِ گژھن بوزُن تہٕ یێلہِ تُہٕندِس خداہس سٍتـ̡ کھوژُن ہیچھِو، یوتام تُہۍ اتھ زمینس مَنٛز روزان چھِو، یێلہِ تہٕ یێلہِ تہٕ یێلہِ تُہۍ اردنس اَپارِ گٔژھِو۔ \n14. تہٕ خداوند ووٚن موسیٰ سٕندِس دۅہہٕ یُس ژے مرُن، یشوع بُلٲوِو، تہٕ کٔرِو جماعت کِس خیمہ خانس مَنٛز پیش، یُتھ بہٕ دِیہٕ أمِس دِنہٕ۔ تہٕ موسیٰ تہٕ یشوع گٔیہِ تہٕ گٔیہِ جماعت کِس خیمہ خانس مَنٛز پیش۔ \n15.\\tتہٕ خداوند آو خیمہ خانس مَنٛز اَکہِ اوٚبرٕ کِس ستونس مَنٛز نمودار: تہٕ اوبرُک تھَم اوس خیمہ کِس دروازس پیٹھ کھڑا۔ \n16.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ وُچھ، وُچھِو تہٕ پَنٕنـ̡ پنہٕ نِس مٲلِس سٍتـ̡ شۄنگنہٕ۔ تہٕ یِہ لُکھ وُتھٕ وُتھ، تہٕ یێلہِ تِم یِمن سٍتـ̡ گٔژھِتھ گٔژھِتھ تہٕ یێلہِ تِمن سٍتـ̡ گژھن میٲنۍ عہد پھُٹراوٕنـ̡ ۔ {نِندٕر: ہیب۔ لٔگِتھ رٔٹِو}\n17.\\tتیلہِ گژھہِ تِمن سٍتـ̡ میٲنۍ شرارت دِنہٕ، تہٕ بہٕ تراوٕ تِمن نِش پنُن بُتھ ژوٗر، تہٕ تِم کھٮ۪نہٕ یِن، تہٕ تِمن ہٕندِس سٍتـ̡ واریاہ بُرٕ تہٕ مصیبت واتہٕ۔ یێلہِ تِم وَنَن تمہِ دۅہٕ یِم بُرٲے چھَنہٕ اسہِ سٍتـ̡ آمٕژ، کیازِ سُہ خدا چُھنہٕ اسہِ مَنٛز چُھنہٕ؟ {befall: Heb. Find}\n18.\\tتہٕ بہٕ کَرٕ پَنُن بُتھ تِمن سارِنٕے بُراین خٲطرٕ یِم تِمو کٔرۍمٕتۍ، یِمن مَنٛز تِم باقین دیوتاہن کُن پھیرِ۔ \n19. تێمہِ کِنۍ لیکھِو یہِ بٲتھ پننہِ خٲطرٕ، تہٕ یہِ ہیچھناوُن تہٕ یہِ ہیچھناوُن تہندِس ٲسس مَنٛز، یُتھ زِ یہِ بٲتھ گژھہِ میانہِ خٲطرٕ بنی اسرٲیلِس خلاف گواہ بنہِ۔ \n20. یێلہِ بہٕ تِم تِمن تِمن زمینس مَنٛز اَننہٕ یُس بہٕ تِہندین مٲلن سٍتـ̡ قسم دِوان چُھس، یُس دۄدٕ تہٕ ماچھ سٍتـ̡ وسان چُھس۔ تہٕ تِمو کھیوٚن تہٕ پان بٔرِتھ تہٕ چربی کٔرِتھ۔ تێلہِ گژھن تِم باقین دیوتاہن کُن پھیرٕن، تہٕ تِمن ہٕنز خدمت کٔرِتھ، تہٕ مےٚ اِشارٕ دِن، تہٕ میون عہد پھُٹراون۔ \n21.\\tتہٕ یێلہِ یِمن واریاہ بُرِ تہٕ مصیبت سپدِ، زِ یہِ بٲتھ گژھہِ تِمن خلاف گواہ بٔنِتھ گوٲہی دِنہٕ۔ تکیازِ یہ گژھہِ نہٕ تِہٕندِس بُلِس منزٕ مشراونہٕ یُن، تکیازِ بہٕ چھُس تِہُند تخیل زانان یُس تِمن ہٕندِس زمینس مَنٛز اننہٕ برونہہ تہِ چھُ۔ {خٕلاف: حب۔ برٛونٛہہ} {گۆ...: ہیب۔ کرُن}\n22.\\tموسىٰ ین لیوکھ امی دۅہہ یہ بٲتھ تہ بنی اسرٲیلِس ہیچھناوُن۔ \n23. تہٕ تٔمۍ دیُت نون سٕندِس نیچوِس یشوع سُند عہدٕ تہٕ وونُن، مضبوط تہٕ ہمت تھاوُن، تکیازِ توے کرٕ بنی اسرائیلٕکۍ اَتھ زمینس مَنٛز یُس بہٕ تِمن سٍتـ̡ قسم دِوان چُھس، تہٕ بہٕ روزٕ توے سٍتـ̡ ۔ \n24.\\tتہٕ سپُد یێلہِ موسىٰ سٕندِ کُنہِ کتابہِ مَنٛز امہِ شریعتٕکۍ لفظ لیکھُن بند کورمُت، یوتام تِم مُکمل گٔیہِ، \n25.\\tزِ موسىٰ دِیُت لاوِین ہُند حُکُم، یُس خداوند سٕندِ عہدُک صندوقہٕ ہُند صندوق چھُ، یہِ وونُن زِ \n26.\\tشریعت ہٕنز یہِ کتاب رٔٹِو، تہٕ تھاوُن خداوند پنُن خدایہ سٕندِ عہد کِس صندوقس مَنٛز، یُتھ یہِ آسہِ تۅہہِ خلاف گواہ دِنہٕ خٲطرٕ۔ \n27.\\tکیازِ بہٕ چُھس چانہِ بغاوت تہٕ تُہٕنزِ سختی ہٕنز گردن زانان: وُچھ، یێلہِ بہٕ از تہِ ژے سٍتـ̡ زندٕ چُھس، تہٕ چُھہ ژے خداوند سٕندِس خلاف بغاوت کٔرمٕژ۔ تہٕ میانہِ مرنہٕ پتہٕ کوتاہ زیادٕ؟ \n28. پَنٕنٮ۪ن قبیلن ہٕندِس سارِنٕے زِٹھۍ تہٕ پَنٕنٮ۪ن افسرن کٔرِو میانہِ نِش جمع تاکہ بہٕ یِم لفظ تِہندین کنن مَنٛز بولہٕ تہٕ یِمن خلاف درج کرنہٕ خٲطرٕ آسمانس تہٕ زمینس بلاو۔ \n29. کیازِکہ بہٕ چُھس پتاہ زِ میانہِ مرنہٕ پتہٕ کٔرِو تُہۍ پَنُن پان سراسر بد کار تہٕ یُس میہ چُھہ حُکُم دِژمُت چُھ، تتھ نِش پھیُرِو۔ تہٕ پٔتِمِس دۅہس مَنٛز گژھہِ بُرٕے سٍتـ̡ بُرٕ۔ تِکیازِ تُہۍ کٔرِو خداوند سٕندِس نظرس مَنٛز بُرٕ کٔرِتھ، یُس پنہٕ نِس اَتھٕ سٍتـ̡ شَرارتہٕ کٔرِتھ۔ \n30.\\tتہٕ موسىٰ کٔر اسرٲیلِچ سارِنٕے جمٲژ ہٕندِس کنن مَنٛز امہِ بٲتُک کلام ، یوتام تِم ختم گٔیہِ۔","1. اے آسمان، تہٕ بہٕ کَرٕ کَتھ تہٕ بوزو، اے زمین، میانہِ ٲسٕکۍ کلام۔ \n2.\\tمیون نظریہ گژھہِ رودکۍ پٲٹھۍ، میون کلام گژھہِ شبنم ہٕندۍ پٲٹھۍ، نرم جڑی بوٹین پیٹھ لۅکٹۍ روٗد تہٕ گاسہِ پیٹھ روٗد پٲٹھۍ: \n3. کیازِکہِ بہٕ کرٕ خداوند سُند ناو شایع کرنہٕ: تُہۍ کٔرِو سٲنِس خدایہ سٕنز عظمت۔ \n4.\\t{سُہ چُھ} چُھہ چُھہ کُنہِ کُنہِ سٍتـ̡ کامل: تٔمۍ سٕندِس سارِنٕے طریقو سٍتـ̡ {چُھ} فیصلہٕ: سُہ چُھ سُہ سُند خدا تہٕ بدکاری ورٲے عادل تہٕ صحیح۔ \n5.\\tتِمو چُھ پانس بد کار کورمُت، تِمن ہٕندِس شُرین ہٕندِس مقامس {چُھ} {تِم چِھ} اکھ بدکار تہٕ بدکار نسل۔ {تِمن چُھ...: حب۔ تِمو چُھ پانس سٍتـ̡ خراب کورمُت} {تِہُند...: یا یہ زِ تِم چِھنہٕ تٔمۍ سٕندِس شُرۍ، یہِ چُھ تِہُند داغ}\n6. کیا تُہۍ چھِو یِتھٕ پٲٹھۍ خداوند سُند بدلہٕ دِوان، اے بیوقوف تہٕ نادان؟ {کیا سُہ چُھہ نہٕ تُہند مول {یُس} چُھہ تۅہہِ ہیوٚتمُت؟ کیا تٔمۍ چُھہ نہٕ تُہہِ بنوومُت، تہٕ چُھہ تُہہِ قٲیم کورمُت؟ \n7.\\tپرانہِ زمانہ یاد تھاوُن، واریاہن نسلن ہٕندِس ؤرین پیٹھ غور کرُن: پننِس مٲلِس پرژھہِ، تہٕ سُہ کرِ تۅہہِ ہاوُن۔ تُہٕندِس بٔڈِس سٍتـ̡ تہٕ تِم کرِ تۅہہِ وَنُن۔ {واریاہ ...: عبرانی۔ نسل تہٕ نسل}\n8.\\tییلہ خداتعالین قومن مَنٛز تِہُند وراثت تقسیم کٔر، ییلہ تٔمۍ آدم سٕندِس نیٚچوِس الگ کٔر، تٔمۍ کٔر لوکن ہٕندِ حَد بنی اسرٲیلِن ہٕندِ تعدادٕ مطٲبق۔ \n9. خداوند سُند حصہٕ {چُھ} تٔمۍ سٕندِس لوک۔ یعقوب {چُھ} تٔمۍ سٕندِ وراثتُک حصہٕ۔ {لوٹ: حب۔ رُڈ}\n10.\\tتٔمۍ لوٚب سُہ أکِس ریگستانی زمینس منز، تہٕ کُنہِ بیابانس منز۔ سُہ اوس أمِس نِش نِش نِوان، تٔمۍ دِژ أمِس ہدایت، تٔمۍ تھووُن سُہ أچھن ہُند تارٕ پٲٹھۍ۔ {لیڈ: یا، کمپاسڈ}\n11.\\tیِتھٕ پٲٹھۍ چُھ اکھ عقاب پننِس گرس منز ہلکان دِوان، پننین بچن پیٹھ وہرٲوِتھ، پَنٕنۍ پَکھہٕ پھٔہلٲوِتھ، تِمن رٔٹِتھ پَنٕنِس پَکھَن پیٹھ رٔٹِتھ: \n12.\\t{یێلہِ} کُنہِ خداوند کٔر أمِس رہنُمٲیی تہٕ {أمِس سٍتـ̡ اوس نہٕ کانہہ عجیب خدا۔ \n13.\\tتٔمۍ بنوو أمِس زمینہٕ کِس تھزرس پیٹھ سوار، یُتھ سُہ کھہَن ہُند اضافہٕ کھٮ۪تھ کھٮ۪تھ۔ تہٕ بنوو أمِس کنہِ پَنہِ منزٕ ماچھ چوسُن، تہٕ کٔنہِ کٔنہِ منز تیٖل کڈنہٕ۔ \n14.\\tکۅکرِ ہُند تھنہٕ تہٕ کۅکرِ ہُند دۄد، کۅکرِ ہٕندِس چربہٕ سٍتـ̡ تہٕ کٕنکہٕ سٕندِس کڈنِس چربہٕ سٍتـ̡ تہٕ ژھاوٕرِ سٍتـ̡ کٔرِتھ کٔرِتھ۔ تہٕ ژے کٔر انگورُک خالص خون۔ \n15.\\tمگر یشورون کٔر چربی تہٕ لَتھ دِژٕن: ژے چُھکھ موم موٚٹ، ژٕ چُھکھ موٚٹ، ژٕ چُھکھ موٹُن {موٹ}۔ تێمہِ پَتہٕ تروو تٔمۍ خدایہ {یُس} سُہ بنوومُت، تہٕ ہلکہٕ پٲٹھـ̡ پننہِ نجات ہٕندِس پتھرس ہُند احترام کٔرِتھ۔ \n16.\\tتِمو کٔر أمِس عجیب دیوتاہن سٍتۍ حسد کرنہٕ خٲطرٕ، مکروہ سٍتۍ کٔر تمِس شرارتس ہٕندِس سٍتـ̡ دِنہٕ۔ \n17.\\tتِمو کٔر شیطانن سٍتـ̡ قربانی، نہ خدایس سٍتـ̡۔ تِمن دیوتاہن سٍتـ̡ یِم نہٕ تِمن زانان ٲسۍ، نٔوِس خداہس سٍتـ̡ یِمن نہٕ تُہند مٲل سٍتـ̡ کھوژان اوس۔ {نہٕ کُن...: یا، یِم نہٕ خدا ٲسۍ}\n18.\\tیُس کُنہِ \n19.\\tتہٕ یێلہِ خداوند وُچھ، تٔمِس کٔر تِمن سٍتـ̡ نفرت، پننین نیچوین تہٕ کورِ ہٕندِ اشتعال دِنہٕ سٍتـ̡۔ {نفرت: یا، حقارت کٔرٕن}\n20.\\tتہٕ تٔمۍ ووٚن، بہٕ کٔرٕ تِمن نِش پنُن بُتھ ژوٗرِتھ، بہٕ وُچھٕ تِہُند انجام کیا آسہِ، تِکیازِ تِم چھِ سٮ۪ٹھاہ بدمعاش نسل، یِمن مَنٛز {چُھ} نہٕ ایمان تھاوان۔ \n21.\\tتِمو چُھس میہ حسد کٔرِتھ {یُس خدایہ نہٕ چُھ} سٍتـ̡ چُھہ ۔ تِمو چُھس میہ پننیو باطل سٍتـ̡ شرارت دِژمُت: تہٕ بہٕ کٔرٕ تِمن سٍتـ̡ حسدُک شکار۔ بہٕ کٔرٕ تِمن أکِس بیوقوف قومس سٍتـ̡ شرارت ہٕندِس سٍتـ̡ اِشارٕ دِنہٕ۔ \n22. تکیازِ میانہِ غصہٕ سٍتـ̡ چُھہ نار دزان، تہٕ دزِیہِ بٔنِس جہنمس تام، تہٕ زٲلِن زمینہٕ سٍتـ̡ زٲلِتھ تہٕ پہاڑن ہٕنزِ بُنیاد نار دِنہٕ۔ {دزِن: یا دزِ} {کھٮ۪نہٕ یِن: یا چُھہ کھٮ۪نہٕ}\n23. بہٕ کٔرٕ تِمن پیٹھ شرارت انبار۔ بہٕ کٔرٕ تِمن پیٹھ پنٕنۍ تیر خرچ۔ \n24. {تِم گژھن فاقہٕ سٍتـ̡ زالنہٕ، تہٕ دزنہٕ سٍتـ̡ تہٕ تلخ تباہی سٍتـ̡ کھٮ۪نہٕ یِن: بہٕ سوزٕ تِمن پیٹھ درندن ہٕندِ دند تہِ، گردِ ہٕندِس ناگن ہٕندِس زہر سٍتـ̡ ۔ {Heat: Heb. کولہٕ}\n25.\\tتلوار نیبر تہٕ اندر دہشت دِیہِ جوان تہٕ کُنوارِس تہٕ دۄدٕ دِنہٕ وٲلِس سٍتـ̡ تباہ کٔرِتھ۔ {اندرٕن: ہیب۔ ﴿تباہی﴾ {تباہ کٔرِتھ: حب۔ غم}\n26.\\tمیہ ووٚن، بہٕ کٔرٕ تِم کونن مَنٛز بٔنِتھ، بہٕ کٔرٕ تِمن ہٕنز یاد دِنہٕ یِن: \n27.\\tاگر نہ میہ دُشمن ہٕندِس قہر سٍتـ̡ کھوژان، یێلہِ تِمن ہُند دُشمن ہُند سٍتـ̡ عجیب سلوک کرُن، {تہٕ} یێلہِ گژھن تِم ونن، سون اتھہٕ {چُھ} تھوٚد، تہٕ خداوند چُھ نہٕ یہِ سورُے کورمُت۔ {سانہِ...: یا، سانہِ تھدِ اتھہٕ، تہٕ خداوند چُھ نہٕ کورمُت}\n28.\\tتکیازِ تِم چھِ اکھ قوم یُس مشورٕ نِش خالی چھُ، تہٕ نہ چھُنہٕ تِمن مَنٛز کانہہ فہم تہِ۔ \n29.\\tکاش تِم عقلمند آسن، {یہ} تِم سمجھ یہِ، {یہ} تِم کرن پننِس ٲخری اندس پیٹھ غور۔ \n30.\\tاکھ کِتھہ پٲٹھـ̡ پى۪ٹھہٕ پى۪ٹھ، تہٕ زٕ دَہ ساس ژٔلِتھ ژٔلِتھ، یێلہِ تِہٕنزِ کٔنہِ کٕنـ̡ تہٕ خداوند آسہِ تِم بنٛد کٔرِمٕتۍ۔ \n31.\\tتِہٕنزِ کٔنہِ چُھہ نہٕ سانہِ کُنہِ کُنہِ سٍتـ̡ دُشمن ہٕندِس پٲٹھـ̡ تہِ {آسن﴾۔ \n32.\\tتِہُند انگور چُھہ سدوم کِس انگور سٍتـ̡ تہٕ گومورہ کِس کھاہن ہٕندِس انگورُک {چُھ} تِہُند انگور {چُھ} تلخ: {انگورُک: یا چُھہ بیلہٕ کھۅتہٕ بدتر}\n33.\\tتِہُند شرابُک زہر چھُ ڈریگن ہُند زہر، تہٕ ایسپس ہُند ظالمانہ زہر۔ \n34.\\t{} کیا یہ چھُنہٕ میہ سٍتۍ تھاونہٕ آمُت، {تہٕ} میانین خزانن منز بند کرنہٕ آمُت؟ \n35.\\tمیانہِ خٲطرٕ چُھ انتقام تہٕ بدلہٕ۔ تِہٕندِس کھۅر گژھہِ وقتس سٍتـ̡ کھسنہٕ، تکیازِ تِہٕنزِ آفتُک دۅہ چُھہ اتھس پیٹھ، تہٕ یِمن پیٹھ یِنہٕ وٲلِس چیزس سٍتـ̡ چُھ جلدی کَران۔ \n36.\\tیِکیازِ خداوند کرِ پننین لوکن ہُند فیصلہ تہٕ پننین خدمتگارن ہٕندِ خٲطرٕ توبہ کرُن، یێلہِ سُہ وُچھِتھ زِ {تِہُند} طاقت چُھہ ختم گومُت، تہٕ {اَتہِ} چُھہ نہٕ کانہہ تہِ بند تہٕ نہ بٔرِتھ۔ {طاقت: ہیب۔ اتھہٕ}\n37.\\tتہٕ سُہ وَنُن زِ تِہٕندِس خداہٕ کَتہِ چھِ، یِمن پیٹھ تِمو بھروسہٕ اوس کٔرِتھ، \n38.\\tکٔمۍ کٔر تِمن ہٕنزِ قربانی ہُند چربی کھٮ۪وان، {تہٕ} تِمن ہٕندِس شرابُک شراب؟ تِم تھوٚد تھوٚد تہٕ تۅہہِ مدد کٔرِتھ، {تہٕ} تُہٕندِ رٲچھ کٔرِتھ۔ {تُہُند...: حب۔ تۅہہِ خٲطرٕ اکھ پوشہٕ}\n39.\\tوُچھو وۅنۍ زِ بہ، {حتی} بہ، {am} سُہ تہٕ {چُھس} چُھس نہٕ میہ سٍتـ̡ کانہہ خدا: بہٕ چُھس ماران تہٕ بہٕ چُھس زندٕ بناوان؛ بہٕ چُھس زخم دِوان، تہٕ بہٕ چُھس شفا دِوان: نۂ چُھہ کانہہ {چُھ} یُس میانہِ اتھہٕ سٍتـ̡ نِش نجات دِتھ۔ \n40. تکیازِ بہٕ چُھس پنُن اَتھٕ آسمانس کُن تُلِتھ تہٕ ونان چھُس، بہٕ چُھس ہمیشہٕ خٲطرٕ زندٕ روزان۔ \n41. اگر بہٕ پنٕنۍ چمکدار تلوار لٔگِتھ تہٕ پنُن اَتھٕ رٔٹِتھ فیصلہٕ کٔرِتھ۔ بہٕ کَرٕ پننین دُشمنن سُند انتقام، تہٕ یِمن سۭتۍ نفرت کرن والٮ۪ن ہُند انعام دِیہٕ۔ \n42. بہٕ بناوٕ پنٕنۍ تیر خونس سٍتـ̡ شراب، تہٕ میٲنۍ تلوار کھیٚیہِ ماز۔ {تہٕ یہ} دشمنن سٍتـ̡ انتقام کِس آغازس پیٹھٕ مقتولن تہٕ قیدَن ہٕندِس خونہٕ سٍتـ̡ ۔ \n43. اے قومو، تٔمۍ سٕندِس لُکن سٍتـ̡ خۅش کرُن، تکیازِ سُہ کرِ پننین خادمَن ہٕندِس خونُک انتقام، تہٕ کرِ پننین مُخٲلفن سٍتـ̡ انتقام، تہٕ کرِ پنہٕ نـ̡ لُکن سٍتـ̡ رحمتـ̡ کرنہٕ۔ {شاد کرُن...: یا، تٔمۍ سٕندِس لوکَن ہٕنز تعریف، اے قوبو: یا گیوُن}\n44.\\tتہٕ موسیٰ آو تہٕ کٔرٕن امہِ بٲتٕکۍ سٲری لفظ لُکن ہٕندِس کنن منز، سُہ تہٕ ہوشیہ سُند نیچو۔ {ہوشع: یا، یشوع}\n45.\\tتہٕ موسىٰ کٔر سارِنٕے اسرٲیلِس سٍتـ̡ یِم سٲری لفظ بولُن بند۔ \n46. تہٕ تٔمۍ ووٚن تِمَن سارِنٕے کَلامَن سٍتـ̡ یِمن ہٕنز بہٕ از تہٕ گوٲہی دِوان چُھ، یِمن ہُند حُکُم دِیُن پننین شُرین ہٕندِس شریعت ہٕندِس سارِنٕے کلامَن ہُند حُکُم دِیُن۔ \n47.\\tکیازِ یہِ چُھہ نہٕ تۅہہِ خٲطرٕ کانہہ فضول چیز۔ کیازِ یہِ چُھہ تُہٕنزِ زندگی تہٕ اَمہ چیزٕ سٍتـ̡ ژیہ زمینس مَنٛز پَنٕنـ̡ دۅہہٕ زیٹھراوُن، یێلہِ تہٕ یێلہِ تُہۍ اردن ہٕندِس نِش رٔٹِتھ گٔژھِو۔ \n48. تہٕ خداوند ووٚن امی دۅہہ موسیٰ ہس سٍتـ̡ وونُن، \n49.\\tژے وُچھِو اتھ پہاڑ اباریمس منز، یُس {چُھ} موآب کِس سرزمینس مَنٛز، یعنی {چُھ} یریکوہس خلاف۔ تہٕ وُچھِو کنعانٕچ سرزمین، یُس بہٕ بنی اسرٲیلِس قبضہٕ خٲطرٕ دِوان چھُ: \n50. تہٕ یێلہِ تہٕ یێلہِ تہِ ژے کھسِتھ گٔژھِو، تہٕ یێلہِ پنہٕ نِس لُکن سٍتـ̡ جمع گٔژھِو۔ یِتھٕ پٲٹھـ̡ ہارون تُہُند بوے ہور پہاڑس مَنٛز موٗدمُت، تہٕ سپُد پنہٕ نِس لُکن مَنٛز جمع کرنہٕ۔ \n51.\\tکیازِ تۅہہ کٔر میہ سٍتـ̡ زِن کِس بیابانس مَنٛز، مریبہ کادیش کِس آبس مَنٛز۔ تکیازِ تۅہہ کٔر نہٕ مے بنی اِسرٲیلِس مَنٛز پاکیزہ۔ {میریبہ کادیش: یا، قادیشس مَنٛز جھگڑ}\n52.\\tتوتہِ وُچھِو تۅہہ برونہہ کُن زمین۔ مگر تۅہہ گژھ نہٕ تتہِ تتھ زمینس کُن یُس بہٕ بنی اسرٲیلِس دِوان چھُ۔","1. تہٕ یہِ چھُ سُہ نعمت، یێمہِ سٍتـ̡ موسىٰ سٕندِ انسانہٕ سٍتـ̡ مرنہٕ برونہہ بنی اسرٲیلـ̡ برکت دِژمٕژ۔ \n2.\\tتہٕ ووٚن، خداوند آو سینا پیٹھ، تہٕ ووت سیر پیٹھٕ تِمن نِش۔ سُہ دراو پران پہاڑ پیٹھٕ چمک، تہٕ سُہ آو دَہن ساسہٕ مقدسن سٍتـ̡ تہٕ تِہندِ خٲطرٕ دٔچھِنہِ اتھہٕ سٍتـ̡ دٔچھِتھ دٔپِھنہِ اَتھٕ سٍتـ̡ اکھ آتش شریعت دِنہٕ۔ {اکھ نار...: ہیب۔ شریعت ہُند نار}\n3. آ، سُہ اوس لُکن سٍتـ̡ محبت۔ تٔمۍ سٕندِ سارِنٕے مُقدس {چِھ} تُہٕندِس اتھس منز: تہٕ تِم بِہتھ تُہٕندِس قدمن پیٹھ۔ {پرٮ۪تھ کٲنسہِ} میلہِ تُہند کلام۔ \n4. موسىٰ دِژ اسہِ شریعت ہُند حُکُم، یعقوب سٕنزِ جماعت ہٕنز وراثت۔ \n5.\\tتہٕ سُہ اوس یشورونَس مَنٛز بادشاہ، یێلہِ لُکن ہٕندِ کُلہٕ تہٕ اسرٲیلٕکۍ قبیلہٕ جمع گٔیہِ۔ \n6. روبن زندٕ روزُن، تہٕ نہ مرُن۔ تہٕ تٔمۍ سٕندِس نفرس گژھہِ نہٕ کم۔ \n7. تہٕ یہِ چھُ یہوداہ سٕنز برکت: تہٕ تٔمۍ ووٚن، اے خداوند، یہوداہ سٕنز آواز بوزو، تہٕ أمِس أنِو پننِس لوکَس نِش۔ تہٕ تٔمۍ سٕندِس دُشمنن نِش گژھہِ أمِس مدد۔ \n8.\\tتہٕ لیوی سٍتـ̡ وۆن، {پَنُنـ̡ تھُمِم تہٕ تُہُند اُرِم {بێیہ} پنہٕ نِس مُقدسَس سٍتـ̡، یُس ژے مَساہس مَنٛز ثٲبت کٔر، {تہٕ یێمِس سٍتـ̡ ژے مریبہ کِس آبس مَنٛز کوشش کٔرِو۔ \n9. یٔمۍ پننِس مٲلِس تہٕ ماجہِ ووٚنمُت زِ مے چُھس نہٕ سُہ وُچھمُت۔ نَہ اوس تٔمِس پننِس بٲے تسلیم کٔرِتھ، تہٕ نہ اوس پننین شُرین زانان، کیازِ تِمو چُھہ تُہند کلامٕچ تعمیل کٔرمٕژ، تہٕ تُہند عہد پورٕ کورمُت۔ \n10. تِم ہیچھناوَن یعقوبس پنُن فیصلہٕ، تہٕ اسرٲیلِس پَنُن شریعت تہٕ تُہٕندِس قربان گاہَس پؠٹھ دِنہٕ یِنہٕ۔ {تِم ہیچھناوٕن: یا، تِم ہیچھناوٕن} {تِم تھاوٕن: یا تھاوُن} {برونہہ ...: ہیب۔ تُہنزِ نَسس پیٹھ}\n11. خداوند، تٔمۍ سٕندِس مالہٕ سٍتـ̡ برکت دِیُن، تہٕ تٔمۍ سٕندِس اتھن ہٕنزِ کٲم کٔرِو قبول۔ \n12. {تہٕ} بنیمنَس مُتعلِق ووٚن تٔمۍ زِ خداوند سُند محبوب روزِ أمِس سٍتـ̡ رٲچھ کٔرِتھ۔ {تہٕ خدا} روزِ أمِس سٲرۍسٕے دۅہس پردٕ، تہٕ سُہ روزِ تٔمِس پھیکس درمِیان روزُن۔ \n13. تہٕ یوسفس مُتلق ووٚن تٔمۍ سٕنزِ زمینہٕ سٍتـ̡ خدایہِ سٕندِ سٍتـ̡ بابرکت آسُن، جنتٕچ قیمتی چیزن خٲطرٕ، شبنم خٲطرٕ، تہٕ بٔنِس سٍتـ̡ بێیہِ سٍتـ̡ \n14. تہٕ آفتابہٕ سٕندِ دٔسۍ دِنہٕ آمٕتۍ قۭمتی مٮ۪وٕ خٲطرٕ، تہٕ زونہِ ہٕندِ دٔسۍ دِنہٕ آمٕتۍ قٕمتی چیزن خٲطرٕ، {پُٹ: ہیب۔ زور} {زون: ہیب۔ زونہٕ}\n15. تہٕ قدیم پہاڑن ہٕندٮ۪ن اہم چیزن خٲطرٕ، تہٕ دائمی بالن ہٕندٮ۪ن قیمتی چیزن خٲطرٕ، \n16.\\tتہٕ زمینہِ ہٕندِس قۭمتی چیزن تہٕ یُس کُنہِ سٍتـ̡ روزان چُھ، تہٕ یُس بٲے سٕندِس کلہٕ سٍتـ̡ بێیہِ سٍتـ̡ دِنہٕ آمُت۔ \n17.\\tتٔمۍ سُند جلال {چُھ} تٔمۍ سٕندِس دانٛد ہٕندِس گۄڈنِکِس پٲٹھۍ، تہٕ تٔمۍ سٕندِ سینگ چِھہ یونیکورن ہٕندِس سینگ ہِوۍ: تِمن سٍتـ̡ دِیہِ سُہ لُکن زمینہٕ کِس اندس تام رٔلِتھ: تہٕ تِم چھِ دَہ ساس افرائیم، تہٕ تِم چھِ ساسہٕ بٔدۍ منسیہ۔ {یونیکورن: عبرانی۔ اَکھ یونیکورن}\n18.\\tتہٕ زبولُن سٍتـ̡ ووٚن زِبولُن، تێنہِ نیرنس مَنٛز۔ تہٕ عیساکر، پننین خیمن مَنٛز۔ \n19.\\tتِم بُلاونہٕ یِن لُکن پہاڑس کُن۔ اَتہِ کٔرِن تِم نیکی ہٕنز قربانی دِن: تِکیازِ تِم چِھہ سمندرن ہٕنزِ کثرت تہٕ سٮ۪کہِ مَنٛز ژوٗرِ تھاونہٕ آمٕتۍ خزانہٕ چوسان۔ \n20.\\tتہٕ گادس متعلق ووٚن تٔمۍ سُہ یُس گاڈس بڑاوان چُھ، سُہ چُھ شیر سٕندِ پٲٹھی روزان، تہٕ کلہٕ کِس تاجس سٍتـ̡ نٔر ژٹان۔ \n21. تہٕ تٔمۍ کٔر پانس خٲطرٕ گۄڈنیُک حصہٕ فراہم، تکیازِ تتہِ، شریعت دِنہٕ وٲلس سُند اکھ حصہٕ، {اوس} بِہتھ اوس۔ تہٕ سُہ آو لُکن ہٕندِس کلہٕ سٍتـ̡ ، تٔمۍ کٔر خداوند سُند انصاف تہٕ تٔمۍ سٕندِ فیصلہٕ سٍتـ̡ اسرٲیلس سٍتـ̡ عملہٕ۔ {بِہِتھ: ہیب۔ سیلڈ}\n22.\\tتہٕ دانس متعلق ووٚن تٔمۍ زِ دان چُھہ شیر سُند بچہٕ: سُہ گژھہِ بشان پیٹھٕ وۄٹھ دِنہٕ۔ \n23.\\tتہٕ نفتالی سٍتـ̡ وۆن، اے نفتالی، یُس عنایتس سٍتـ̡ مطمئن، تہٕ خداوند سٕنزِ نعمتہٕ سٍتـ̡ پورٕ گٔژھِتھ: مغرب تہٕ جنوبُک قبضہ کرُن۔ \n24.\\tتہٕ آشرس مُتلق ووٚن آشرس بچہٕ دِنہٕ۔ سُہ گژھہِ پننین باین ہٕندِ خٲطرٕ قبول، تہٕ سُہ گژھہِ تیٖلس مَنٛز کھۄر ڈباونہٕ۔ \n25.\\tتُہٕندِس بوٗٹَس {گژھِ}ششتٕر تہٕ پیتلُک؛ تہٕ تُہٕندِس دۅہہٕ پٲٹھۍ{تُہٕندِس دۅہہٕ﴾ ہُند طاقت {بَن}۔ {تُہٕندِس بوٗٹَس﴾ یا تُہٕندِس بوٗٹَس تَل\n26. {یشورون سٕندِس خداہس ہیو چُھہ نہٕ کانہہ تہِ، {یُس} چُھہ تُہندِ مددتہٕ سٍتـ̡ اسمانس پیٹھ سوار سپدان چُھ، تہٕ آسمانس پیٹھ تٔمۍ سٕندِس عظمتس سٍتـ̡ چُھہ سٍتـ̡ سٍتـ� \n27. ابدی خدا چُھ تُہند پناہ گاہ، تہٕ تَل چُھہ ابدی ہتھیار تہٕ سُہ کرِ دُشمن ژٔٹِتھ ۔ تہٕ وَنُن زِ تِمن کٔرِو تِمن تباہ ۔ \n28. اَمہِ پَتہٕ روزِ یعقوب سُند چشمہٕ یُس مکایہِ تہٕ شرابٕچ زمینہٕ پٲٹھۍ۔ تٔمۍ سٕندِس آسمانس سٍتـ̡ پۯاوُن شبنم۔ \n29. اے اسرائیل، اے اسرٲیل، کُس چُھہ تۅہہِ ہیوٗ ہیوٗ چُھ، اے خداوند سٕندِ دٔسۍ نجات دِنہٕ آمٕژ لوکو، چانہِ مددٕچ ڈھال، تہٕ یُس چُھہ تُہنزِ عظمتٕچ تلوار! تہٕ تُہٕندِس دُشمن ہٕندِس سٍتـ̡ پۯاونہٕ یِنـ̡ تہٕ تُہٕندِس تھزرس پٲٹھـ̡ پۯاوٕنـ̡ ۔ {لٔبـ̡...: یا، دباونہٕ آمُت}","1. تہٕ موسیٰ ووت موآب کِس مٲدانو پیٹھٕ نیبو کِس پہاڑس تام، یُس یریحا کِس تھزرس پیٹھ اوس۔ تہٕ خداوند ہٲو أمِس سٲرۍسٕے گلعادٕچ زمین، دانس تام، {پسگاہ: یا، بال}\n2. تہٕ سارِنٕے نفتالی، تہٕ افرائیم سٕنز سرزمین، تہٕ منسیہ، تہٕ یہوداہ ہٕچ سارِنٕے سرزمین، سمندرس تام، \n3. تہٕ جنوب، تہٕ وادی یریحُک مٲدان، کھجور کُلٮ۪ن ہُند شہر، زورس تام۔ \n4. تہٕ خداوند ووٚن أمِس زِ یہِ چھُ سُہ زمین یُس بہٕ ابراہیم، اسحاق تہٕ یعقوبس سٍتـ̡ قسم دِوان چھُس، بہٕ دِیہٕ یہِ چانہِ نسلس دِژمُت، مے دِژ ژے پننہِ أچھو سٍتـ̡ وُچھمُت، مگر ژٕ گژھ نہٕ تتہِ نیرُن۔ \n5. یێمہِ پٲٹھـ̡ موسیٰ خداوند سُند خادم موآب سٕندِس سرزمینس مَنٛز موُد۔ \n6.\\tتہٕ تٔمۍ دفن سُہ موآب کِس زمینس مَنٛز أکِس وادی مَنٛز، یُس بیت پیورس خلاف اوس، مگر از تام چُھنہٕ کٲنسہ تہِ تٔمۍ سٕندِس قبرس مُتعلِق خبر۔ \n7. تہٕ موسیٰ اوس ہتھ وُہُر وُہُر ییلہ سُہ مرُن: تٔمۍ سٕنز أچھ ٲس نہٕ ژھوٚٹ، تہٕ نہ ٲس تٔمۍ سٕنز فطری قوت کم۔ {قدرتی...: ہیب۔ نمی} {کم: ہیب۔ ژل}\n8. تہٕ بنی اسرائیل روو موآب کِس مٲدانس مَنٛز موسیٰ سٕندِ خٲطرٕ ترہن دۅہہٕ، یِتھٕ پٲٹھۍ گٔیہِ موسیٰ سٕندِ خٲطرٕ روونُک تہٕ ماتم کرنُک دۅہ ختم۔ \n9. تہٕ یشوع سُند نیچو اوس حکمت ہٕندِ روحہٕ سٍتـ̡ بٔرِتھ بٔرِتھ۔ تِکیازِ موسىٰ اوس أمِس پیٹھ اتھہٕ تھوومُت، تہٕ بنی اسرٲیلِیو کٔر أمِس کُن بوزُن، تہٕ کٔرٕن خداوند موسیٰ سُند حُکُم۔ \n10.\\tتہٕ اسرٲیلِس مَنٛز آو نہٕ کانہہ تہِ پیغمبر یُس موسیٰ سٕندِس پٲٹھۍ، یُس خداوند بُتھِ بُتھِ زانان اوس، \n11. تِمن سارِنٕے نشانن تہٕ عجائب سٍتـ̡ یُس خداوند سُہ مصرٕچ سرزمینس مَنٛز فرعونس تہٕ پننین سارنٕے خادمَن تہٕ تٔمۍ سٕندِس سارِنٕے سرزمینس مَنٛز کرنہٕ خٲطرٕ سوزمُت، \n12. تہٕ تتھ سارِنٕے طاقتور اتھس منز، تہٕ سارِنٕے بٔڈ دہشت سٍتـ̡ یُس موسىٰ ہن سارِنٕے اسرٲیلِس سٍتـ̡ ہٲومُت اوس۔"];
